+    let mut reader = BufReader::new(reader);
+    let mut line = Vec::new();
+    let mut oversized = false;
+    let mut written = 0_u64;
+    let mut truncated = false;
+    loop {
+        let buffer = reader.fill_buf().await?;
+        if buffer.is_empty() {
+            break;
+        }
+        let length = buffer
+            .iter()
+            .position(|byte| *byte == b'\n')
