-        .max_depth(maximum_depth.saturating_add(1))
-        .follow_links(false)
-        .into_iter()
-        .filter_entry(should_descend)
-    {
-        let Ok(entry) = entry else {
-            continue;
-        };
-        if entry.file_type().is_dir() && entry.path().join(".git").exists() {
-            repositories.insert(entry.path().to_path_buf());
-        }
-    }
