fn write_records(path: &Path, indices: impl Iterator<Item = usize>) {
    let mut file = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .unwrap();
    for index in indices {
        serde_json::to_writer(&mut file, &record(index)).unwrap();
        file.write_all(b"\n").unwrap();
    }
