-                "agent cwd is not a registered worktree: {}",
-                requested.display()
-            )));
-        }
-        let path = self.execution_path().await?;
-        let agent = self
-            .agents_in_path(&path)?
-            .into_iter()
-            .find(|agent| agent.id == id && agent.available)
