            );
            assert_eq!(
                std::fs::read_to_string(worktree_path.join("version.txt")).unwrap(),
                if pull_first { "latest\n" } else { "initial\n" }
            );
            assert_eq!(
                git_output(&linked, &["rev-parse", "HEAD"]).await.unwrap(),
                initial_head
            );
        }
    }

