                .ok_or_else(|| AowError::ProjectNotFound(id.to_owned()))?;
            let previous = state.projects[index]
                .worktree_icons
                .get(&request.path)
                .copied();
            if request.icon == WorktreeIcon::Default {
                state.projects[index].worktree_icons.remove(&request.path);
            } else {
                state.projects[index]
