            "POST",
            &format!("{path}/run"),
            serde_json::Value::Null
        )
        .await
        .0,
        StatusCode::ACCEPTED
    );
    assert_eq!(
        call(&router, "DELETE", &path, serde_json::Value::Null)
            .await
            .0,
        StatusCode::NO_CONTENT
    );
