    assert!(manager.store.run_path(id, &run_id).unwrap().exists());
    assert!(!manager.store.root.join("locks").exists());
    assert_eq!(
        call(
            &router,
            "GET",
            "/api/aow/automations",
            serde_json::Value::Null
        )
        .await
        .1,
        serde_json::json!([])
    );
    assert_eq!(
        call(
            &router,
            "GET",
            &format!("{path}/runs"),
