    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method("PUT")
                .uri("/api/aow/im/feishu")
                .header("content-type", "application/json")
                .body(Body::from(
                    r#"{"app_id":"cli_test","app_secret":"private-secret"}"#,
                ))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::OK);
