-fn mode_string(mode: u32) -> String {
-    let kind = match mode & 0o170000 {
-        0o040000 => 'd',
-        0o120000 => 'l',
-        0o100000 => '-',
-        0o060000 => 'b',
-        0o020000 => 'c',
-        0o010000 => 'p',
-        0o140000 => 's',
-        _ => '?',
-    };
-    let mut value = String::with_capacity(10);
-    value.push(kind);
-    for (mask, character) in [
-        (0o400, 'r'),
-        (0o200, 'w'),
-        (0o100, 'x'),
-        (0o040, 'r'),
-        (0o020, 'w'),
-        (0o010, 'x'),
-        (0o004, 'r'),
-        (0o002, 'w'),
-        (0o001, 'x'),
-    ] {
-        value.push(if mode & mask != 0 { character } else { '-' });
-    }
-    value
-}
