                StatusCode::BAD_REQUEST,
            ),
            (
                r#"{"username":"other","password":"test-password"}"#,
                StatusCode::UNAUTHORIZED,
            ),
            (
                r#"{"username":"admin","password":"wrong-password"}"#,
