                    .collect();
                assert_eq!(
                    statuses,
                    if filter == "&state=all" {
                        vec!["open", "merged", "closed"]
                    } else {
                        vec!["open"]
                    }
                );
            } else {
                assert_eq!(value["number"], 42);
            }
        }
        let detail = manager
            .call(&query, "detail", json!({"number":42}), &paths())
            .await
            .unwrap();
        assert_eq!(detail["title"], "team/one");
