-                    options.epoch,
-                    options.after,
-                    options.vt_snapshot,
-                    options.observer,
-                )
-                .await
-        } else {
-            self.inner
-                .terminald
-                .attach_with_resume_capabilities(
-                    pane_id,
-                    options.epoch,
-                    options.after,
-                    options.vt_snapshot,
-                )
-                .await
