    let tabs = state
        .terminals
        .list(None)
        .await
        .map_err(terminal_http_error)?;
    let items: Vec<_> = tabs
        .tabs
        .iter()
        .flat_map(|tab| tab.panes.iter().map(move |pane| (tab, pane)))
        .filter_map(|(tab, pane)| info(tab, pane))
        .collect();
