+        let state = self.lock_state()?;
+        if let Some(root) = &request.workspace_root {
+            state.ensure_workspace_available(root)?;
+        }
+        if let Some(cwd) = &request.cwd {
+            state.ensure_workspace_available(cwd)?;
+        }
+        Ok(())
+    }
+}

