+            .filter(|tab| tab.workspace_root == request.workspace_root)
+            .map(|tab| (tab.id.clone(), tab.clone()))
+            .collect::<HashMap<_, _>>();
+        let old = state.tabs.clone();
+        for (index, tab_id) in workspace_indices.iter().zip(&request.tab_ids) {
