+                .iter()
+                .filter(|tab| {
+                    tab.panes
+                        .iter()
+                        .any(|pane| pane.kind == TerminalPaneKind::Agent)
+                })
+                .count();
+            let tab_ids = tabs
+                .iter()
+                .map(|tab| tab.id.clone())
