+    );
+    let mut created = previous.clone();
+    created.layout = TerminalLayout::Split {
+        axis: TerminalSplitAxis::Row,
+        ratio: 0.5,
+        first: Box::new(TerminalLayout::Pane {
+            pane_id: "a".into(),
+        }),
