+            pane_id: "failed".into(),
+        }),
+    };
+    created
+        .panes
+        .push(pane("failed", TerminalPaneStatus::Running));
+    created.revision += 1;
+
+    let mut current = created.clone();
+    current.name = "renamed concurrently".to_owned();
+    current.revision += 1;
+    current.panes[0].status = TerminalPaneStatus::Exited;
+    current.panes[0].exit_code = Some(9);
