+    sender
+        .send(Ok(Bytes::copy_from_slice(&image[..20])))
+        .await
+        .unwrap();
+    let deadline = tokio::time::Instant::now() + Duration::from_secs(2);
+    loop {
+        if std::fs::read_dir(&manager.inner.clipboard.directory)
+            .unwrap()
+            .next()
+            .is_some()
