    std::fs::File::options()
        .write(true)
        .open(&expired)
        .unwrap()
        .set_times(
            std::fs::FileTimes::new()
                .set_modified(now - CLIPBOARD_IMAGE_TTL - Duration::from_secs(1)),
        )
        .unwrap();

    let used = manager.inner.clipboard.clean_expired_at(now).unwrap();
    assert!(!expired.exists());
    assert!(live.exists());
    assert_eq!(used, 4);
}

