                "/api/fs/file{}",
                encode_absolute(&root.path().join("after.ts").to_string_lossy())
            ))
            .header(CONTENT_TYPE, "application/json")
            .body(Body::from(r#"{"name":"../escape.ts"}"#))
            .unwrap(),
        )
        .await
        .unwrap();
