-    fn enqueue(&self, command: WorkerCommand) {
-        if let Err(error) = self.client.sender.try_send(command) {
-            self.state.fail();
-            tracing::warn!(
-                session_id = %self.state.session_id,
-                %error,
-                "VT worker queue unavailable; falling back to raw terminal replay"
