-fn reserve_snapshot_bytes(total: &AtomicUsize, additional: usize) -> bool {
-    additional == 0
-        || total
-            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |current| {
-                current
-                    .checked_add(additional)
-                    .filter(|next| *next <= MAX_TOTAL_CACHED_SNAPSHOT_BYTES)
-            })
-            .is_ok()
-}
