+    command: WorkerCommand,
+    rpc: &mut RpcClient,
+) -> Result<bool, RpcError> {
+    match command {
+        WorkerCommand::Create {
+            session,
+            cols,
+            rows,
+        } => {
+            if !session.can_process() {
+                return Ok(false);
+            }
+            rpc.call(
+                "create",
+                json!({
+                    "session_id": session.session_id,
+                    "generation": session.generation,
+                    "initial_offset": 0,
+                    "cols": cols,
