    assert_eq!((after.revision, after.start_offset), (1, 6));
    assert_eq!(after.data, b"after");
    let (_, gap) = take_write(receiver.recv().await.unwrap());
    assert_eq!((gap.revision, gap.start_offset), (1, 20));
