impl ManagerState {
    fn ensure_workspace_available(&self, path: &str) -> Result<(), TerminalError> {
        if self
            .removing_workspaces
            .iter()
            .any(|root| Path::new(path).starts_with(root))
        {
            return Err(TerminalError::Invalid(
                "Worktree 正在清理，暂时不能创建资源".into(),
            ));
        }
        Ok(())
    }
}

