                        tokio::time::sleep(Duration::from_millis(20)).await;
                    }
                    stream = client.attach(pane_id).await.unwrap();
                }
            }
        }
        assert_eq!(manager.get_snapshot(&tabs[0].id).unwrap(), tabs[0]);
        drop(stream);
        stop_daemon(shutdown, daemon).await;
