    let tabs = fixture
        .state
        .terminals
        .list(Some(&first.cwd))
        .await
        .unwrap()
        .tabs;
    assert_eq!(tabs.len(), 2);
    assert!(tabs.iter().any(|tab| tab.id == first.tab_id));
    assert!(tabs.iter().any(|tab| tab.id == second.tab_id));
    let closed = fixture
        .state
        .terminals
        .delete_workspace(&first.cwd)
        .await
        .unwrap();
