    assert_eq!(reloaded.settings().unwrap().node_addresses, expected);
    reloaded
        .update_settings(UpdateSettingsRequest {
            node_addresses: Some(Vec::new()),
            ..Default::default()
        })
        .await
        .unwrap();
    assert!(
        AowManager::persistent(directory.path())
            .unwrap()
            .settings()
            .unwrap()
            .node_addresses
            .is_empty()
    );
}

