impl AowManager {
    pub(in crate::aow) async fn inspect_worktree_removal(
        &self,
        id: &str,
        requested_path: &str,
    ) -> Result<WorktreeRemovalInspection, AowError> {
        let (_, _, worktree, _) = self.worktree_removal_target(id, requested_path).await?;
        let status = git_output(
            Path::new(&worktree.path),
            &["status", "--porcelain=v1", "--untracked-files=all"],
        )
        .await?;
        const MAX_REPORTED_CHANGES: usize = 100;
        let mut all_changes = status.lines().map(str::to_owned).collect::<Vec<_>>();
        let change_count = all_changes.len();
        let truncated = change_count > MAX_REPORTED_CHANGES;
        all_changes.truncate(MAX_REPORTED_CHANGES);
        Ok(WorktreeRemovalInspection {
            worktree,
            changes: all_changes,
            change_count,
            truncated,
        })
    }

    #[cfg(test)]
    pub(in crate::aow) async fn remove_worktree(
        &self,
        id: &str,
        requested_path: &str,
        force: bool,
    ) -> Result<Project, AowError> {
        self.remove_worktree_files(id, requested_path, force)
            .await?;
        self.project(id).await
    }

    pub(in crate::aow) async fn remove_worktree_files(
        &self,
        id: &str,
        requested_path: &str,
        force: bool,
    ) -> Result<(), AowError> {
        let (stored, _, worktree, git_cwd) =
            self.worktree_removal_target(id, requested_path).await?;
        let status = git_output(
            Path::new(&worktree.path),
            &["status", "--porcelain=v1", "--untracked-files=all"],
        )
        .await?;
        let dirty_count = status.lines().count();
        if dirty_count > 0 && !force {
            return Err(AowError::DirtyWorktree(dirty_count));
        }

        let (previous_registered_path, previous_color, previous_icon) = {
            let mut state = self.lock()?;
            let index = state
                .projects
                .iter()
                .position(|project| project.id == id)
                .ok_or_else(|| AowError::ProjectNotFound(id.to_owned()))?;
            let previous_registered_path =
                (Path::new(&stored.registered_path) == Path::new(&worktree.path)).then(|| {
                    std::mem::replace(
                        &mut state.projects[index].registered_path,
                        git_cwd.to_string_lossy().into_owned(),
                    )
                });
            let previous_color = state.projects[index].worktree_colors.remove(&worktree.path);
            let previous_icon = state.projects[index].worktree_icons.remove(&worktree.path);
            if previous_registered_path.is_some()
                || previous_color.is_some()
                || previous_icon.is_some()
            {
                if let Err(error) = self.persist_projects(&state.projects) {
                    if let Some(previous) = previous_registered_path {
                        state.projects[index].registered_path = previous;
                    }
                    if let Some(color) = previous_color {
                        state.projects[index]
                            .worktree_colors
                            .insert(worktree.path.clone(), color);
                    }
                    if let Some(icon) = previous_icon {
                        state.projects[index]
                            .worktree_icons
                            .insert(worktree.path.clone(), icon);
                    }
                    return Err(error);
                }
            }
            (previous_registered_path, previous_color, previous_icon)
        };

        let path = worktree.path.as_str();
        let mut args = vec!["worktree", "remove"];
        if force {
            args.push("--force");
        }
        args.extend(["--", path]);
        if let Err(error) = git_output(&git_cwd, &args).await {
            if previous_registered_path.is_some()
                || previous_color.is_some()
                || previous_icon.is_some()
            {
                let mut state = self.lock()?;
                if let Some(project) = state.projects.iter_mut().find(|project| project.id == id) {
                    if let Some(previous) = previous_registered_path {
                        project.registered_path = previous;
                    }
                    if let Some(color) = previous_color {
                        project.worktree_colors.insert(worktree.path.clone(), color);
                    }
                    if let Some(icon) = previous_icon {
                        project.worktree_icons.insert(worktree.path.clone(), icon);
                    }
                    self.persist_projects(&state.projects)?;
                }
            }
            return Err(error);
        }
        Ok(())
    }

    async fn worktree_removal_target(
        &self,
        id: &str,
        requested_path: &str,
    ) -> Result<(StoredProject, Project, Worktree, PathBuf), AowError> {
        let requested_path = requested_path.trim();
        if requested_path.is_empty()
            || requested_path.len() > 4096
            || requested_path.contains('\0')
            || !Path::new(requested_path).is_absolute()
        {
            return Err(AowError::Invalid(
                "worktree path must be an absolute path".to_owned(),
            ));
        }
        let stored = self
            .lock()?
            .projects
            .iter()
            .find(|project| project.id == id)
            .cloned()
            .ok_or_else(|| AowError::ProjectNotFound(id.to_owned()))?;
        let project = super::projects::project_from_stored_strict(stored.clone()).await?;
        let worktree = project
            .worktrees
            .iter()
            .find(|worktree| worktree.path == requested_path)
            .cloned()
            .ok_or_else(|| {
                AowError::Invalid(format!(
                    "path is not a worktree in project {}: {requested_path}",
                    project.name
                ))
            })?;
        if worktree.is_main {
            return Err(AowError::Invalid(
                "the main worktree cannot be removed".to_owned(),
            ));
        }
        if worktree.locked {
            return Err(AowError::Invalid(
                "locked worktrees must be unlocked before removal".to_owned(),
            ));
        }
        let git_cwd = project
            .worktrees
            .iter()
            .find(|candidate| candidate.is_main)
            .map(|candidate| PathBuf::from(&candidate.path))
            .ok_or_else(|| AowError::Git("project has no main worktree".to_owned()))?;
        Ok((stored, project, worktree, git_cwd))
    }
}

//! Authentication event construction and delivery to operation and security logs.

use aow_im::{Field, Message};
use aow_operation_log::{Level, Outcome, Record};
use axum::http::StatusCode;

use super::{Evidence, clean};
use crate::AppState;

pub(in crate::auth) struct Event {
    pub(in crate::auth) evidence: Evidence,
    pub(in crate::auth) kind: &'static str,
    pub(in crate::auth) event: &'static str,
    pub(in crate::auth) title: &'static str,
    pub(in crate::auth) status: StatusCode,
    pub(in crate::auth) reason: String,
    pub(in crate::auth) login_method: Option<String>,
    pub(in crate::auth) claimed_username: Option<String>,
    pub(in crate::auth) subject: Option<String>,
}

impl Event {
    pub(in crate::auth) async fn publish(self, state: &AppState) {
        let success = self.event == "login_succeeded";
        let details = serde_json::json!({
            "request": self.evidence,
            "status": self.status.as_u16(),
            "duration_ms": self.evidence.started.elapsed().as_millis(),
            "reason": self.reason,
            "login_method": self.login_method.as_deref().map(|s| clean(s, 64)),
            "claimed_username": self.claimed_username.as_deref().map(|s| clean(s, 256)),
            "subject": self.subject.as_deref().map(|s| clean(s, 256)),
        });
        let record = Record {
            timestamp: self.evidence.timestamp.clone(),
            operation_id: self.evidence.event_id.clone(),
            boot_id: String::new(),
            kind: self.kind.into(),
            source: "auth".into(),
            title: self.title.into(),
            event: self.event.into(),
            level: if success { Level::Info } else { Level::Warn },
            message: details.to_string(),
            project_id: None,
            resource: Some(self.evidence.path.clone()),
            outcome: Some(if success {
                Outcome::Succeeded
            } else {
                Outcome::Failed
            }),
            completed: None,
            total: None,
        };
        tracing::info!(event_id = %record.operation_id, event = self.event, evidence = %record.message, "authentication audit");
        state.operations.record(record.clone()).await;
        // Anonymous access retains its evidence but never enters the IM queue.
        if self.kind != "auth.login" {
            return;
        }
        let field = |label: &str, value: String| Field {
            label: label.into(),
            value,
            url: None,
        };
        let message = Message {
            title: format!("AoW · {}", self.title),
            fields: vec![
                field("时间", self.evidence.timestamp),
                field("事件 ID", self.evidence.event_id),
                field(
                    "连接来源 IP",
                    self.evidence.peer_ip.unwrap_or_else(|| "未知".into()),
                ),
                field(
                    "请求",
                    format!("{} {}", self.evidence.method, self.evidence.path),
                ),
                field(
                    "账号（提交值）",
                    self.claimed_username
                        .as_deref()
                        .map(|s| clean(s, 256))
                        .unwrap_or_else(|| "未提供".into()),
                ),
            ],
            body_label: "审计详情".into(),
            body: format!(
                "HTTP {} · {}\nUser-Agent: {}\n转发 IP（未验证）: {}",
                self.status.as_u16(),
                self.reason,
                self.evidence.user_agent.as_deref().unwrap_or("未知"),
                self.evidence
                    .x_forwarded_for_unverified
                    .as_deref()
                    .unwrap_or("无")
            ),
            markdown: false,
            error: !success,
        };
        state
            .aow
            .notifications()
            .notify_security(message, record, state.operations.clone())
            .await;
    }

    pub(in crate::auth) fn access(
        evidence: Evidence,
        status: StatusCode,
        reason: &str,
        page: bool,
    ) -> Self {
        Self {
            evidence,
            kind: "auth.access",
            event: if page {
                "anonymous_page_access"
            } else {
                "access_denied"
            },
            title: if page {
                "未登录访问页面"
            } else {
                "未登录访问被拒绝"
            },
            status,
            reason: reason.into(),
            login_method: None,
            claimed_username: None,
            subject: None,
        }
    }
}

//! Request evidence captured and sanitized for authentication auditing.

use std::{convert::Infallible, net::SocketAddr};

use axum::{
    extract::{ConnectInfo, FromRequestParts, Request},
    http::{Extensions, HeaderMap, Method, Uri, Version, request::Parts},
};
use serde::Serialize;

use crate::{AppState, auth::http};

#[derive(Clone, Serialize)]
pub(in crate::auth) struct Evidence {
    pub event_id: String,
    pub timestamp: String,
    #[serde(skip)]
    pub started: std::time::Instant,
    pub method: String,
    pub path: String,
    pub http_version: String,
    pub peer_ip: Option<String>,
    pub peer_port: Option<u16>,
    pub host_unverified: Option<String>,
    pub user_agent: Option<String>,
    pub origin_unverified: Option<String>,
    pub referer_unverified: Option<String>,
    pub x_forwarded_for_unverified: Option<String>,
    pub x_real_ip_unverified: Option<String>,
    pub forwarded_unverified: Option<String>,
    pub session_cookie_present: bool,
}

impl Evidence {
    pub(in crate::auth) fn from_request(state: &AppState, request: &Request) -> Self {
        Self::new(
            state,
            request.method(),
            request.uri(),
            request.version(),
            request.headers(),
            request.extensions(),
        )
    }

    fn new(
        state: &AppState,
        method: &Method,
        uri: &Uri,
        version: Version,
        headers: &HeaderMap,
        extensions: &Extensions,
    ) -> Self {
        let peer = extensions
            .get::<ConnectInfo<SocketAddr>>()
            .map(|info| info.0);
        let header = |name: &str, limit| {
            headers
                .get(name)
                .and_then(|h| h.to_str().ok())
                .map(|s| clean(s, limit))
        };
        let url_header = |name: &str| {
            headers
                .get(name)
                .and_then(|h| h.to_str().ok())
                .and_then(safe_url)
        };
        Self {
            event_id: uuid::Uuid::new_v4().to_string(),
            timestamp: chrono::Utc::now().to_rfc3339(),
            started: std::time::Instant::now(),
            method: clean(method.as_str(), 32),
            path: safe_path(&state.base_path.url(uri.path())),
            http_version: format!("{version:?}"),
            peer_ip: peer.map(|peer| peer.ip().to_string()),
            peer_port: peer.map(|peer| peer.port()),
            host_unverified: header("host", 256),
            user_agent: header("user-agent", 512),
            origin_unverified: url_header("origin"),
            referer_unverified: url_header("referer"),
            x_forwarded_for_unverified: header("x-forwarded-for", 512),
            x_real_ip_unverified: header("x-real-ip", 128),
            forwarded_unverified: header("forwarded", 512),
            session_cookie_present: http::session_token(headers, &state.base_path.cookie_name())
                .is_some(),
        }
    }
}

impl FromRequestParts<AppState> for Evidence {
    type Rejection = Infallible;

    async fn from_request_parts(
        parts: &mut Parts,
        state: &AppState,
    ) -> Result<Self, Self::Rejection> {
        Ok(Self::new(
            state,
            &parts.method,
            &parts.uri,
            parts.version,
            &parts.headers,
            &parts.extensions,
        ))
    }
}

pub(in crate::auth) fn clean(value: &str, max: usize) -> String {
    let mut result: String = value
        .chars()
        .take(max)
        .map(|c| if c.is_control() { '�' } else { c })
        .collect();
    if value.chars().nth(max).is_some() {
        result.push('…');
    }
    result
}

pub(super) fn safe_path(path: &str) -> String {
    // Share URLs contain bearer secrets in their path, including referrers and
    // attempts to use an unsupported verb on the public endpoint.
    let mut redact_next = false;
    let path = path
        .split('/')
        .map(|part| {
            let redact = redact_next;
            redact_next = matches!(part, "share" | "session-shares");
            if redact { "[redacted]" } else { part }
        })
        .collect::<Vec<_>>()
        .join("/");
    clean(&path, 2048)
}

pub(super) fn safe_url(value: &str) -> Option<String> {
    let url = reqwest::Url::parse(value).ok()?;
    if !matches!(url.scheme(), "http" | "https") {
        return None;
    }
    Some(clean(
        &format!(
            "{}{}",
            url.origin().ascii_serialization(),
            safe_path(url.path())
        ),
        1024,
    ))
}

