use axum::{
    body::Body,
    extract::{Request, State},
    middleware::Next,
    response::{IntoResponse, Response},
};

use super::audit;
use super::http::{LOGIN_PATH, LOGOUT_PATH, STATUS_PATH, session_token};
use crate::AppState;
use futures_util::StreamExt;

/// All login methods share this access policy. Only the exact registered
/// read-only share endpoint accepts anonymous API requests with a share token.
pub(crate) async fn require_auth(
    State(state): State<AppState>,
    mut request: Request,
    next: Next,
) -> Response {
    let path = request.uri().path();
    let public_share = matches!(
        *request.method(),
        axum::http::Method::GET | axum::http::Method::HEAD
    ) && request
        .extensions()
        .get::<axum::extract::MatchedPath>()
        .is_some_and(|path| path.as_str() == crate::session_shares::PUBLIC_API_PATH);
    let protected = (path.starts_with("/api/")
        && !public_share
        && !matches!(path, "/api/health" | STATUS_PATH | LOGIN_PATH | LOGOUT_PATH))
        || path == "/fs"
        || path.starts_with("/fs/")
        || path == "/help";
    let access = if protected {
        match state.auth.access(session_token(
            request.headers(),
            &state.base_path.cookie_name(),
        )) {
            Ok(access) => access,
            Err(error) => {
                audit::Event::access(
                    audit::Evidence::from_request(&state, &request),
                    error.status,
                    &error.body.code,
                    false,
                )
                .publish(&state)
                .await;
                return error.into_response();
            }
        }
    } else {
        None
    };
    // The SPA shell stays public so it can display the login form. Navigating
    // directly to a workspace page still counts as anonymous access.
    let public_page = request
        .extensions()
        .get::<axum::extract::MatchedPath>()
        .is_some_and(|path| matches!(path.as_str(), "/share/{token}" | "/share/{token}/"));
    let static_asset = path.starts_with("/assets/")
        || path.starts_with("/third-party/")
        || matches!(path, "/workspace-icon.svg" | "/favicon.ico");
    let anonymous_page = !state.auth.disabled
        && !protected
        && !path.starts_with("/api/")
        && !public_page
        && !static_asset
        && matches!(
            *request.method(),
            axum::http::Method::GET | axum::http::Method::HEAD
        )
        && state
            .auth
            .check(
                session_token(request.headers(), &state.base_path.cookie_name()),
                false,
            )
            .is_err();
    let evidence = anonymous_page.then(|| audit::Evidence::from_request(&state, &request));
    if let Some(access) = &access {
        request.extensions_mut().insert(access.clone());
    }
    let response = next.run(request).await;
    if let Some(evidence) = evidence {
        audit::Event::access(evidence, response.status(), "authentication_required", true)
            .publish(&state)
            .await;
    }
    // A long-lived event stream must stop when its originating session ends.
    if let Some(access) = access
        && response
            .headers()
            .get("content-type")
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| value.starts_with("text/event-stream"))
    {
        let (parts, body) = response.into_parts();
        let stream = futures_util::stream::unfold(
            (body.into_data_stream(), access),
            |(mut stream, access)| async move {
                if access.validate(false).is_err() {
                    return None;
                }
                tokio::select! {
                    biased;
                    _ = access.revoked() => None,
                    chunk = stream.next() => chunk.map(|chunk| (chunk, (stream, access))),
                }
            },
        );
        return Response::from_parts(parts, Body::from_stream(stream));
    }
    response
}

use axum::{
    Json, Router,
    extract::{State, rejection::JsonRejection},
    http::{
        HeaderMap, HeaderValue, StatusCode,
        header::{CACHE_CONTROL, COOKIE, SET_COOKIE},
    },
    response::{IntoResponse, Response},
    routing::{get, post},
};
use serde::Deserialize;
use serde_json::Value;

use super::{AuthStatus, audit, password};
use crate::{AppState, HttpError};

pub(super) const STATUS_PATH: &str = "/api/auth/status";
pub(super) const LOGIN_PATH: &str = "/api/auth/login";
pub(super) const LOGOUT_PATH: &str = "/api/auth/logout";

pub(crate) fn routes() -> Router<AppState> {
    Router::new()
        .route(STATUS_PATH, get(status))
        .route(LOGIN_PATH, post(login))
        .route(LOGOUT_PATH, post(logout))
        .layer(axum::middleware::map_response(no_store))
}

async fn no_store(mut response: Response) -> Response {
    response
        .headers_mut()
        .insert(CACHE_CONTROL, HeaderValue::from_static("no-store"));
    response
}

#[derive(Deserialize)]
struct LoginRequest {
    // Existing clients that omit the method continue to use account/password.
    #[serde(default = "default_method")]
    method: String,
    #[serde(flatten)]
    credentials: Value,
}

fn default_method() -> String {
    password::METHOD.into()
}

async fn status(State(state): State<AppState>, headers: HeaderMap) -> Json<AuthStatus> {
    Json(
        state
            .auth
            .status(session_token(&headers, &state.base_path.cookie_name())),
    )
}

async fn login(
    State(state): State<AppState>,
    evidence: audit::Evidence,
    headers: HeaderMap,
    request: Result<Json<LoginRequest>, JsonRejection>,
) -> Result<Response, HttpError> {
    let mut event = audit::Event {
        evidence,
        kind: "auth.login",
        event: "login_failed",
        title: "登录失败",
        status: StatusCode::BAD_REQUEST,
        reason: String::new(),
        login_method: request
            .as_ref()
            .ok()
            .map(|Json(r)| audit::clean(&r.method, 64)),
        claimed_username: request
            .as_ref()
            .ok()
            .and_then(|Json(r)| r.credentials["username"].as_str())
            .map(|s| audit::clean(s, 256)),
        subject: None,
    };
    // Rejections from JSON extraction (including oversized bodies), origin
    // checks and admission limits are login failures too.
    let admission = check_origin(&headers)
        .and_then(|()| {
            request.map_err(|error| {
                HttpError::new(
                    error.status(),
                    "invalid_login_request",
                    "登录请求格式无效",
                    None,
                )
            })
        })
        .and_then(|Json(request)| state.auth.limiter.begin().map(|attempt| (request, attempt)));
    let (request, attempt) = match admission {
        Ok(admitted) => admitted,
        Err(error) => {
            event.status = error.status;
            event.reason = error.body.code.clone();
            event.publish(&state).await;
            return Err(error);
        }
    };
    // Only admitted attempts create a background task (at most two). Keep the
    // permit until auditing is queued, even when the HTTP caller disconnects.
    tokio::spawn(async move {
        let auth = state.auth.clone();
        let verified = tokio::task::spawn_blocking(move || {
            let result = auth.login_with_attempt(&request.method, request.credentials, &attempt);
            (result, attempt)
        })
        .await;
        let (result, _attempt) = match verified {
            Ok((result, attempt)) => (result, Some(attempt)),
            Err(_) => (Err(HttpError::internal("登录验证失败")), None),
        };
        let result = result.and_then(|token| {
            event.subject = state
                .auth
                .sessions
                .get(&token, false)?
                .map(|session| session.identity.subject);
            login_response(&state, &headers, &token)
        });
        match &result {
            Ok(response) => {
                event.event = "login_succeeded";
                event.title = "登录成功";
                event.status = response.status();
                event.reason = "login_succeeded".into();
            }
            Err(error) => {
                event.status = error.status;
                event.reason = error.body.code.clone();
            }
        }
        event.publish(&state).await;
        result
    })
    .await
    .map_err(|_| HttpError::internal("登录处理失败"))?
}

fn login_response(
    state: &AppState,
    headers: &HeaderMap,
    token: &str,
) -> Result<Response, HttpError> {
    if let Some(previous) = session_token(&headers, &state.base_path.cookie_name()) {
        state.auth.sessions.revoke(previous)?;
    }
    let mut response = Json(state.auth.status(Some(token))).into_response();
    response
        .headers_mut()
        .insert(SET_COOKIE, cookie(state, token, false));
    Ok(response)
}

async fn logout(State(state): State<AppState>, headers: HeaderMap) -> Result<Response, HttpError> {
    check_origin(&headers)?;
    if let Some(token) = session_token(&headers, &state.base_path.cookie_name()) {
        state.auth.sessions.revoke(token)?;
    }
    let mut response = StatusCode::NO_CONTENT.into_response();
    response
        .headers_mut()
        .insert(SET_COOKIE, cookie(&state, "", true));
    Ok(response)
}

fn cookie(state: &AppState, token: &str, clear: bool) -> HeaderValue {
    HeaderValue::from_str(&format!(
        "{}={token}; Path={}; HttpOnly; SameSite=Strict{}{}",
        state.base_path.cookie_name(),
        state.base_path.url("/"),
        if state.auth.secure_cookies {
            "; Secure"
        } else {
            ""
        },
        if clear { "; Max-Age=0" } else { "" },
    ))
    .expect("validated cookie components")
}

// Browser requests must originate from this authority. Do not trust forwarded
// headers supplied by clients, and keep non-browser clients without Origin usable.
fn check_origin(headers: &HeaderMap) -> Result<(), HttpError> {
    if let Some(origin) = headers.get("origin") {
        let valid = origin
            .to_str()
            .ok()
            .and_then(|value| value.parse::<axum::http::Uri>().ok())
            .is_some_and(|origin| {
                matches!(origin.scheme_str(), Some("http" | "https"))
                    && origin.path() == "/"
                    && origin.query().is_none()
                    && origin.authority().is_some_and(|authority| {
                        headers
                            .get("host")
                            .and_then(|host| host.to_str().ok())
                            .is_some_and(|host| host.eq_ignore_ascii_case(authority.as_str()))
                    })
            });
        if !valid {
            return Err(HttpError::new(
                StatusCode::FORBIDDEN,
                "invalid_origin",
                "登录请求来源无效",
                None,
            ));
        }
    }
    Ok(())
}

pub(super) fn session_token<'a>(headers: &'a HeaderMap, name: &str) -> Option<&'a str> {
    headers
        .get(COOKIE)
        .and_then(|value| value.to_str().ok())
        .and_then(|cookie| {
            cookie
                .split(';')
                .map(str::trim)
                .find_map(|entry| entry.strip_prefix(&format!("{name}=")))
        })
}

//! Bound anonymous work before submitting password verification to the blocking pool.
//! A single local account uses a shared budget; client-supplied usernames and
//! forwarded IP headers cannot create new buckets or bypass the limit.
use crate::HttpError;
use axum::http::{HeaderValue, StatusCode, header::RETRY_AFTER};
use std::{
    sync::{Arc, Mutex},
    time::{Duration, Instant},
};

const BURST: f64 = 10.0;
const REFILL_SECONDS: f64 = 6.0;
const MAX_CONCURRENT: usize = 2;

#[derive(Clone)]
pub(super) struct LoginLimiter(Arc<Mutex<State>>);
struct State {
    active: usize,
    tokens: f64,
    updated: Instant,
    failures: u32,
    blocked_until: Instant,
}

impl Default for LoginLimiter {
    fn default() -> Self {
        let now = Instant::now();
        Self(Arc::new(Mutex::new(State {
            active: 0,
            tokens: BURST,
            updated: now,
            failures: 0,
            blocked_until: now,
        })))
    }
}

pub(super) struct Attempt {
    limiter: LoginLimiter,
}

impl LoginLimiter {
    pub fn begin(&self) -> Result<Attempt, HttpError> {
        self.begin_at(Instant::now())
    }

    fn begin_at(&self, now: Instant) -> Result<Attempt, HttpError> {
        let mut state = self
            .0
            .lock()
            .map_err(|_| HttpError::internal("登录限流不可用"))?;
        state.tokens = (state.tokens
            + now.duration_since(state.updated).as_secs_f64() / REFILL_SECONDS)
            .min(BURST);
        state.updated = now;
        let wait = if now < state.blocked_until {
            (state.blocked_until - now).as_secs_f64()
        } else if state.active >= MAX_CONCURRENT {
            1.0
        } else if state.tokens < 1.0 {
            (1.0 - state.tokens) * REFILL_SECONDS
        } else {
            0.0
        };
        if wait > 0.0 {
            return Err(limited(wait.ceil() as u64));
        }
        state.tokens -= 1.0;
        state.active += 1;
        Ok(Attempt {
            limiter: self.clone(),
        })
    }
}

impl Attempt {
    pub fn finish(&self, success: bool, bad_credentials: bool) {
        self.finish_at(success, bad_credentials, Instant::now());
    }
    fn finish_at(&self, success: bool, bad_credentials: bool, now: Instant) {
        if let Ok(mut state) = self.limiter.0.lock() {
            if success {
                state.failures = 0;
                state.blocked_until = now;
            } else if bad_credentials {
                state.failures = state.failures.saturating_add(1);
                if state.failures >= 5 {
                    state.blocked_until =
                        now + Duration::from_secs((1_u64 << (state.failures - 5).min(6)).min(60));
                }
            }
        }
    }
}
impl Drop for Attempt {
    fn drop(&mut self) {
        if let Ok(mut state) = self.limiter.0.lock() {
            state.active -= 1;
        }
    }
}
fn limited(seconds: u64) -> HttpError {
    let mut error = HttpError::new(
        StatusCode::TOO_MANY_REQUESTS,
        "login_rate_limited",
        "登录尝试过于频繁，请稍后重试",
        None,
    );
    error.extra_headers.insert(
        RETRY_AFTER,
        HeaderValue::from_str(&seconds.max(1).to_string()).unwrap(),
    );
    error
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn concurrency_and_rate_budgets_recover_without_an_unbounded_queue() {
        let limiter = LoginLimiter::default();
        let now = Instant::now();
        let first = limiter.begin_at(now).unwrap();
        let second = limiter.begin_at(now).unwrap();
        assert_eq!(
            limiter.begin_at(now).err().unwrap().status,
            StatusCode::TOO_MANY_REQUESTS
        );
        drop(first);
        drop(second);
        for _ in 2..10 {
            drop(limiter.begin_at(now).unwrap());
        }
        let error = limiter.begin_at(now).err().unwrap();
        assert_eq!(error.status, StatusCode::TOO_MANY_REQUESTS);
        assert_eq!(error.extra_headers[RETRY_AFTER], "6");
        drop(limiter.begin_at(now + Duration::from_secs(6)).unwrap());
    }
    #[test]
    fn repeated_failures_back_off_and_rejections_do_not_extend_lockout() {
        let limiter = LoginLimiter::default();
        let now = Instant::now();
        for _ in 0..5 {
            let attempt = limiter.begin_at(now).unwrap();
            attempt.finish_at(false, true, now);
        }
        assert_eq!(
            limiter.begin_at(now).err().unwrap().extra_headers[RETRY_AFTER],
            "1"
        );
        let later = now + Duration::from_secs(1);
        let attempt = limiter.begin_at(later).unwrap();
        attempt.finish_at(false, true, later);
        drop(attempt);
        assert_eq!(
            limiter.begin_at(later).err().unwrap().extra_headers[RETRY_AFTER],
            "2"
        );
        let later = later + Duration::from_secs(2);
        let attempt = limiter.begin_at(later).unwrap();
        attempt.finish_at(true, false, later);
        drop(attempt);
        assert!(limiter.begin_at(later).is_ok());
    }
}

