        "https://example.com/bad%2fpath",
        "https://example.com/?x=1",
        "https://example.com/#x",
    ] {
        assert!(
            manager.update(update(invalid)).is_err(),
            "accepted {invalid}"
        );
    }
    manager
        .update(preferences(true, vec![Channel::Page]))
