pub(crate) struct Spec {
    pub id: String,
    pub kind: &'static str,
    pub source: &'static str,
    pub title: String,
    pub project_id: Option<String>,
    pub resource: Option<String>,
    pub total: Option<usize>,
}

#[derive(Clone, Default, Serialize)]
pub(crate) struct Snapshot {
    pub boot_id: String,
    pub revision: u64,
    pub operations: Vec<Operation>,
    pub log_error: Option<String>,
}

struct Entry {
    operation: Operation,
    finished: Option<Instant>,
}
struct Runtime {
    boot_id: String,
    revision: u64,
    entries: Vec<Entry>,
    log_error: Option<String>,
}

impl Runtime {
    fn snapshot(&mut self) -> Snapshot {
        self.entries
            .retain(|entry| entry.finished.is_none_or(|at| at.elapsed() < RECENT_TTL));
        // Retain by completion time, not creation order: a long-running task
        // must still publish its result after many newer tasks have completed.
        while self
            .entries
            .iter()
            .filter(|entry| entry.finished.is_some())
            .count()
            > RECENT_LIMIT
        {
            let oldest = self
                .entries
                .iter()
                .enumerate()
                .filter_map(|(index, entry)| entry.finished.map(|at| (index, at)))
                .min_by_key(|(_, at)| *at)
                .unwrap()
                .0;
            self.entries.remove(oldest);
        }
        Snapshot {
            boot_id: self.boot_id.clone(),
            revision: self.revision,
            operations: self
                .entries
                .iter()
                .map(|entry| entry.operation.clone())
                .collect(),
            log_error: self.log_error.clone(),
        }
    }
}

struct LogWorker {
    sender: Option<mpsc::Sender<LogEntry>>,
    thread: Option<std::thread::JoinHandle<()>>,
}

struct LogEntry {
    record: Record,
    persisted: Option<oneshot::Sender<bool>>,
}
impl Drop for LogWorker {
    fn drop(&mut self) {
        self.sender.take();
        if let Some(thread) = self.thread.take() {
            let _ = thread.join();
        }
    }
}

struct Inner {
    runtime: Arc<Mutex<Runtime>>,
    changes: watch::Sender<Snapshot>,
    worker: Option<LogWorker>,
    reader: Option<Reader>,
    reads: Arc<tokio::sync::Semaphore>,
}

#[derive(Clone)]
pub(crate) struct OperationService {
    inner: Arc<Inner>,
}

use std::{
    path::Path,
    sync::{Arc, Mutex},
    time::Instant,
};

use aow_operation_log::{Level, Outcome, Reader, Record, Writer};
use tokio::sync::{mpsc, oneshot, watch};

use super::{
    Entry, Handle, Inner, LogEntry, LogWorker, Operation, OperationService, Runtime, Snapshot, Spec,
};

impl OperationService {
    pub(crate) fn in_memory() -> Self {
        Self::new(None).expect("in-memory operation service")
    }

    pub(crate) fn persistent(directory: &Path) -> Result<Self, aow_operation_log::Error> {
        Self::new(Some(directory))
    }

    fn new(directory: Option<&Path>) -> Result<Self, aow_operation_log::Error> {
        let mut runtime = Runtime {
            boot_id: uuid::Uuid::new_v4().to_string(),
            revision: 0,
            entries: Vec::new(),
            log_error: None,
        };
        let (changes, _) = watch::channel(runtime.snapshot());
        let runtime = Arc::new(Mutex::new(runtime));
        let worker = if let Some(directory) = directory {
            let writer = Writer::open(directory, 24 * 30)?;
            let (sender, mut receiver) = mpsc::channel::<LogEntry>(1024);
            let runtime = runtime.clone();
            let changes = changes.clone();
            let thread = std::thread::Builder::new()
                .name("operation-log".into())
                .spawn(move || {
                    while let Some(entry) = receiver.blocking_recv() {
                        let result = writer.append(&entry.record);
                        let persisted = result.is_ok();
                        if let Err(error) = result {
                            tracing::error!(%error, "operation log write failed");
                            let mut state =
                                runtime.lock().unwrap_or_else(|error| error.into_inner());
                            state.log_error = Some("操作日志写入失败，部分记录可能不完整".into());
                            state.revision += 1;
                            changes.send_replace(state.snapshot());
                        }
                        if let Some(reply) = entry.persisted {
                            let _ = reply.send(persisted);
                        }
                    }
                })?;
            Some(LogWorker {
                sender: Some(sender),
                thread: Some(thread),
            })
        } else {
            None
        };
        Ok(Self {
            inner: Arc::new(Inner {
                runtime,
                changes,
                worker,
                reader: directory.map(Reader::new),
                reads: Arc::new(tokio::sync::Semaphore::new(2)),
            }),
        })
    }

    pub(crate) fn snapshot(&self) -> Snapshot {
        self.inner
            .runtime
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .snapshot()
    }

    /// Standalone audit events do not create live progress operations. Wait for
    /// the bounded queue and disk write instead of dropping events under load.
    pub(crate) async fn record(&self, mut record: Record) {
        record.boot_id = self.inner.runtime.lock().unwrap().boot_id.clone();
        let Some(worker) = &self.inner.worker else {
            return;
        };
        let (reply, persisted) = oneshot::channel();
        let event_id = record.operation_id.clone();
        if worker
            .sender
            .as_ref()
            .unwrap()
            .send(LogEntry {
                record,
                persisted: Some(reply),
            })
            .await
            .is_err()
            || !persisted.await.unwrap_or(false)
        {
            tracing::error!(%event_id, "audit log persistence failed");
            let mut state = self.inner.runtime.lock().unwrap();
            state.log_error = Some("审计日志写入失败，部分记录可能不完整".into());
            state.revision += 1;
            self.inner.changes.send_replace(state.snapshot());
        } else {
            let mut state = self.inner.runtime.lock().unwrap();
            state.revision += 1;
            self.inner.changes.send_replace(state.snapshot());
        }
    }

    pub(crate) fn begin(&self, spec: Spec) -> Handle {
        let operation = Operation {
            id: spec.id.clone(),
            kind: spec.kind.into(),
            source: spec.source.into(),
            title: bounded(&spec.title, 256),
            project_id: spec.project_id.map(|value| bounded(&value, 256)),
            resource: spec.resource.map(|value| bounded(&value, 4096)),
            created_at: chrono::Utc::now().to_rfc3339(),
            message: "排队中".into(),
            completed: 0,
            total: spec.total,
            outcome: None,
        };
        {
            let mut state = self
                .inner
                .runtime
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            state.entries.push(Entry {
                operation,
                finished: None,
            });
        }
        self.update(
            &spec.id,
            "started",
            Level::Info,
            "操作已接受".into(),
            None,
            None,
            None,
        );
        Handle::new(self.clone(), spec.id)
    }

    pub(super) fn update(
        &self,
        id: &str,
        event: &str,
        level: Level,
        message: String,
        completed: Option<usize>,
        outcome: Option<Outcome>,
        resource: Option<String>,
    ) {
        let mut state = self
            .inner
            .runtime
            .lock()
            .unwrap_or_else(|error| error.into_inner());
        let boot_id = state.boot_id.clone();
        let Some(entry) = state
            .entries
            .iter_mut()
            .find(|entry| entry.operation.id == id)
        else {
            return;
        };
        // A terminal outcome is immutable; late worker callbacks cannot revive it.
        if entry.finished.is_some() {
            return;
        }
        let operation = &mut entry.operation;
        operation.message = bounded(&message, 8192);
        if let Some(completed) = completed {
            operation.completed = completed;
        }
        if let Some(resource) = resource {
            operation.resource = Some(bounded(&resource, 4096));
        }
        operation.outcome = outcome;
        if outcome.is_some() {
            entry.finished = Some(Instant::now());
        }
        let record = Record {
            timestamp: chrono::Utc::now().to_rfc3339(),
            operation_id: id.into(),
            boot_id,
            kind: operation.kind.clone(),
            source: operation.source.clone(),
            title: operation.title.clone(),
            event: event.into(),
            level,
            message: operation.message.clone(),
            project_id: operation.project_id.clone(),
            resource: operation.resource.clone(),
            outcome,
            completed: Some(operation.completed),
            total: operation.total,
        };
        if let Some(worker) = &self.inner.worker
            && worker
                .sender
                .as_ref()
                .unwrap()
                .try_send(LogEntry {
                    record,
                    persisted: None,
                })
                .is_err()
        {
            state.log_error = Some("操作日志队列已满或不可用，部分记录可能不完整".into());
            tracing::error!(operation_id = id, "operation log queue unavailable");
        }
        state.revision += 1;
        self.inner.changes.send_replace(state.snapshot());
    }
}

fn bounded(value: &str, max: usize) -> String {
    if value.len() <= max {
        return value.into();
    }
    let mut end = max;
    while !value.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}…", &value[..end])
}

use super::*;
use crate::AppState;
use aow_operation_log::{Level, Page, ReadOptions, Reader};
use axum::{
    body::{Body, to_bytes},
    http::{Request, StatusCode},
};
use std::time::Duration;
use tower::ServiceExt;

fn spec(id: &str) -> Spec {
    Spec {
        id: id.into(),
        kind: "example.run",
        source: "cli",
        title: "示例操作".into(),
        project_id: Some("project".into()),
        resource: None,
        total: Some(2),
    }
}

#[test]
fn live_handles_finish_once_and_dropped_workers_are_interrupted() {
    let service = OperationService::in_memory();
    let operation = service.begin(spec("first"));
    operation.progress("第一步", Some(1));
    let observer = operation.clone();
    drop(operation);
    assert_eq!(service.snapshot().operations[0].outcome, None);
    observer.finish(Outcome::Succeeded, "完成");
    observer.progress("late callback", Some(0));
    drop(observer);
    let snapshot = service.snapshot();
    assert_eq!(snapshot.operations[0].outcome, Some(Outcome::Succeeded));
    assert_eq!(snapshot.operations[0].completed, 1);
    assert_eq!(snapshot.operations[0].message, "完成");
    drop(service.begin(spec("second")));
    assert_eq!(
        service.snapshot().operations[1].outcome,
        Some(Outcome::Interrupted)
    );
}

#[test]
fn recently_finished_long_operations_survive_the_completed_cache_limit() {
    let service = OperationService::in_memory();
    let long = service.begin(spec("long"));
    for index in 0..RECENT_LIMIT + 10 {
        service
            .begin(spec(&format!("short-{index}")))
            .finish(Outcome::Succeeded, "完成");
    }
    assert_eq!(service.snapshot().operations.len(), RECENT_LIMIT + 1);
    long.finish(Outcome::Succeeded, "长任务完成");
    let snapshot = service.snapshot();
    assert_eq!(snapshot.operations.len(), RECENT_LIMIT);
    assert!(
        snapshot.operations.iter().any(
            |operation| operation.id == "long" && operation.outcome == Some(Outcome::Succeeded)
        )
    );
}

#[test]
fn history_survives_restart_without_restoring_live_operations() {
    let dir = tempfile::tempdir().unwrap();
    let service = OperationService::persistent(dir.path()).unwrap();
    let operation = service.begin(spec("test"));
    operation.event(Level::Info, "步骤已完成", Some(2));
    operation.finish(Outcome::Succeeded, "完成");
    drop(operation);
    drop(service); // drains the logging worker
    let page = Reader::new(dir.path())
        .read(&ReadOptions::default())
        .unwrap();
    assert_eq!(page.items.len(), 3);
    assert_eq!(page.items[0].outcome, Some(Outcome::Succeeded));
    assert_eq!(page.items[2].event, "started");
    let restarted = OperationService::persistent(dir.path()).unwrap();
    assert!(restarted.snapshot().operations.is_empty());
    assert_ne!(restarted.snapshot().boot_id, page.items[0].boot_id);
}

#[tokio::test]
async fn history_api_filters_pages_validates_cursors_and_uses_authentication() {
    let dir = tempfile::tempdir().unwrap();
    let service = OperationService::persistent(dir.path()).unwrap();
    let operation = service.begin(spec("op-one"));
    operation.finish(Outcome::Succeeded, "完成");
    drop(operation);
    drop(service);
    let mut state = AppState::new(Default::default());
    state.operations = OperationService::persistent(dir.path()).unwrap();
    let router = crate::build_router(state.clone());
    let response = router
        .clone()
        .oneshot(
            Request::get("/api/operation-logs?operation_id=op-one&limit=1")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::OK);
    let page: Page =
        serde_json::from_slice(&to_bytes(response.into_body(), 100_000).await.unwrap()).unwrap();
    assert_eq!(page.items.len(), 1);
    assert_eq!(page.items[0].event, "finished");
    let cursor = serde_json::to_string(&page.next_cursor.unwrap()).unwrap();
    let query: String = reqwest::Url::parse_with_params(
        "http://localhost/api/operation-logs",
        &[("cursor", cursor)],
    )
    .unwrap()
    .query()
    .unwrap()
    .into();
    let response = router
        .clone()
        .oneshot(
            Request::get(format!("/api/operation-logs?{query}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let page: Page =
        serde_json::from_slice(&to_bytes(response.into_body(), 100_000).await.unwrap()).unwrap();
    assert_eq!(page.items[0].event, "started");
    for path in [
        "/api/operation-logs?limit=0",
        "/api/operation-logs?cursor=garbage",
    ] {
        assert_eq!(
            router
                .clone()
                .oneshot(Request::get(path).body(Body::empty()).unwrap())
                .await
                .unwrap()
                .status(),
            StatusCode::BAD_REQUEST
        );
    }
    state.auth = crate::auth::AuthService::persistent(dir.path());
    let protected = crate::build_router(state);
    for path in [
        "/api/operation-logs",
        "/api/operations/active",
        "/api/operations/stream",
    ] {
        assert!(
            !protected
                .clone()
                .oneshot(Request::get(path).body(Body::empty()).unwrap())
                .await
                .unwrap()
                .status()
                .is_success()
        );
    }
}

#[tokio::test]
async fn reconnect_stream_starts_with_current_snapshot() {
    use futures_util::StreamExt;
    let state = AppState::new(Default::default());
    let operation = state.operations.begin(spec("live"));
    operation.progress("正在执行", Some(1));
    let response = crate::build_router(state.clone())
        .oneshot(
            Request::get("/api/operations/stream")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let mut stream = response.into_body().into_data_stream();
    let first = tokio::time::timeout(Duration::from_secs(1), stream.next())
        .await
        .unwrap()
        .unwrap()
        .unwrap();
    let text = String::from_utf8(first.to_vec()).unwrap();
    assert!(text.contains("event: operations"));
    assert!(text.contains("正在执行"));
    operation.finish(Outcome::Succeeded, "完成");
    let second = tokio::time::timeout(Duration::from_secs(1), stream.next())
        .await
        .unwrap()
        .unwrap()
        .unwrap();
    assert!(
        String::from_utf8(second.to_vec())
            .unwrap()
            .contains("succeeded")
    );
}

use std::{ffi::OsString, path::PathBuf};

use anyhow::{Context, Result};
use aow_server::default_terminal_state_dir;
use aow_terminald_client::TerminaldClient;

pub(super) struct Options {
    pub(super) host: String,
    pub(super) port: u16,
    pub(super) frontend: PathBuf,
    pub(super) secure_cookies: bool,
    pub(super) base_path: OsString,
    pub(super) state_dir: PathBuf,
    pub(super) terminald_socket: PathBuf,
    pub(super) initialize_only: bool,
    pub(super) initialize_if_missing: bool,
}

pub(super) fn parse() -> Result<Option<Options>> {
    let mut host = "127.0.0.1".to_owned();
    let mut port = 8282_u16;
    let mut frontend = PathBuf::from("frontend/dist");
    let mut secure_cookies = match std::env::var("AOW_AUTH_SECURE_COOKIE") {
        Ok(value) if !value.is_empty() => value
            .parse::<bool>()
            .context("AOW_AUTH_SECURE_COOKIE must be true or false")?,
        Ok(_) | Err(std::env::VarError::NotPresent) => false,
        Err(error) => return Err(error).context("invalid AOW_AUTH_SECURE_COOKIE"),
    };
    let mut base_path = std::env::var_os("AOW_BASE_PATH").unwrap_or_default();
    let mut state_dir = default_terminal_state_dir();
    let mut terminald_socket = TerminaldClient::default_socket_path();
    let mut initialize_only = false;
    let mut initialize_if_missing = false;
    let mut arguments = std::env::args().skip(1);
    while let Some(argument) = arguments.next() {
        match argument.as_str() {
            "--base-path" => {
                base_path = arguments
                    .next()
                    .context("--base-path requires a value")?
                    .into()
            }
            "--secure-cookies" => secure_cookies = true,
            "--initialize-state" => initialize_only = true,
            "--initialize-state-if-missing" => {
                initialize_only = true;
                initialize_if_missing = true;
            }
            "--host" => host = arguments.next().context("--host requires a value")?,
            "--port" => {
                port = arguments
                    .next()
                    .context("--port requires a value")?
                    .parse()
                    .context("invalid --port")?;
            }
            "--frontend" => {
                frontend = PathBuf::from(arguments.next().context("--frontend requires a value")?);
            }
            "--state-dir" => {
                state_dir =
                    PathBuf::from(arguments.next().context("--state-dir requires a value")?);
            }
            "--terminald-socket" => {
                terminald_socket = PathBuf::from(
                    arguments
                        .next()
                        .context("--terminald-socket requires a value")?,
                );
            }
            "-h" | "--help" => {
                print_help();
                return Ok(None);
            }
            other => anyhow::bail!("unknown argument: {other}"),
        }
    }

    Ok(Some(Options {
        host,
        port,
        frontend,
        secure_cookies,
        base_path,
        state_dir,
        terminald_socket,
        initialize_only,
        initialize_if_missing,
    }))
}

fn print_help() {
    println!(
        "Usage: aow-server [--host 127.0.0.1] [--port 8282] [--base-path PATH] [--secure-cookies] [--frontend frontend/dist] [--state-dir PATH] [--terminald-socket PATH] [--initialize-state | --initialize-state-if-missing]\nHost: IPv4 or IPv6 address (for example 127.0.0.1 or ::1); default 127.0.0.1\nBase path: --base-path overrides AOW_BASE_PATH; default /\nHTTPS: --secure-cookies or AOW_AUTH_SECURE_COOKIE=true marks session cookies Secure"
    );
}

use crate::aow::resolve_executable;
use serde_json::Value;
use std::{
    path::{Path, PathBuf},
    process::Stdio,
    time::Duration,
};
use tokio::{
    io::{AsyncRead, AsyncReadExt, AsyncWriteExt},
    process::Command,
    time::timeout,
};

use super::{Provider, PullRequestError, Result, invalid_json};

pub(super) const OUTPUT_LIMIT: usize = 16 * 1024 * 1024;
const COMMAND_TIMEOUT: Duration = Duration::from_secs(60);

pub(super) async fn git(repo: &str, args: &[&str], paths: &[PathBuf]) -> Result<String> {
    let executable = resolve_executable("git", paths).ok_or_else(|| {
        PullRequestError::Unavailable("找不到 git，请检查 Settings → Environment。".into())
    })?;
    let mut command = Command::new(executable);
    command.args(args).current_dir(repo);
    for key in [
        "GIT_DIR",
        "GIT_WORK_TREE",
        "GIT_COMMON_DIR",
        "GIT_INDEX_FILE",
    ] {
        command.env_remove(key);
    }
    String::from_utf8(run_command(command, &[], paths, COMMAND_TIMEOUT).await?)
        .map_err(invalid_json)
}
pub(super) async fn run_adapter(
    provider: &Provider,
    request: Value,
    cwd: Option<&Path>,
    paths: &[PathBuf],
    script_path: Option<&Path>,
) -> Result<Value> {
    let executable = resolve_executable("python3", paths).ok_or_else(|| {
        PullRequestError::Unavailable("找不到 python3，请检查 Settings → Environment。".into())
    })?;
    let mut command = Command::new(executable);
    // Draft tests and in-memory embeddings use a temporary file. Saved providers
    // execute their immutable managed file directly.
    let draft;
    let path = match script_path {
        Some(path) => path,
        None => {
            use std::io::Write;
            let mut file = tempfile::NamedTempFile::new()?;
            file.write_all(provider.script.as_bytes())?;
            draft = file;
            draft.path()
        }
    };
    command.arg(path);
    if let Some(cwd) = cwd {
        command.current_dir(cwd);
    }
    let bytes = run_command(
        command,
        &serde_json::to_vec(&request).unwrap(),
        paths,
        COMMAND_TIMEOUT,
    )
    .await?;
    let value: Value = serde_json::from_slice(&bytes).map_err(invalid_json)?;
    if value.get("version").and_then(Value::as_u64) != Some(2) {
        return Err(invalid_json(
            "expected version: 2; update the Provider script to the current PR protocol",
        ));
    }
    match (value.get("result"), value.get("error")) {
        (Some(result), None) if result.is_object() => Ok(result.clone()),
        (None, Some(error)) if error["code"].is_string() && error["message"].is_string() => {
            Err(PullRequestError::Command(format!(
                "{}: {}",
                error["code"].as_str().unwrap(),
                error["message"].as_str().unwrap()
            )))
        }
        _ => Err(invalid_json(
            "expected either result object or error {code, message}",
        )),
    }
}
pub(super) async fn read_limited(reader: impl AsyncRead + Unpin, limit: usize) -> Result<Vec<u8>> {
    let mut bytes = Vec::new();
    reader
        .take((limit + 1) as u64)
        .read_to_end(&mut bytes)
        .await?;
    if bytes.len() > limit {
        return Err(invalid_json("process output exceeded limit"));
    }
    Ok(bytes)
}
pub(super) async fn run_command(
    mut command: Command,
    input: &[u8],
    paths: &[PathBuf],
    deadline: Duration,
) -> Result<Vec<u8>> {
    command
        .env("PATH", std::env::join_paths(paths).map_err(invalid_json)?)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .kill_on_drop(true);
    #[cfg(unix)]
    command.process_group(0);
    let mut child = command.spawn()?;
    // Kill the entire process group even on cancellation/timeout (scripts often
    // spawn CLI children which inherit stdout and would otherwise outlive them).
    struct Group(Option<u32>);
    impl Drop for Group {
        fn drop(&mut self) {
            #[cfg(unix)]
            if let Some(pid) = self.0 {
                unsafe {
                    libc::kill(-(pid as i32), libc::SIGKILL);
                }
            }
        }
    }
    let _group = Group(child.id());
    let mut stdin = child.stdin.take().unwrap();
    let stdout = child.stdout.take().unwrap();
    let stderr = child.stderr.take().unwrap();
    timeout(deadline, async {
        let (_, out, err, status) = tokio::try_join!(
            async {
                if let Err(error) = stdin.write_all(input).await {
                    if error.kind() != std::io::ErrorKind::BrokenPipe {
                        return Err(error.into());
                    }
                }
                drop(stdin);
                Ok::<_, PullRequestError>(())
            },
            read_limited(stdout, OUTPUT_LIMIT),
            read_limited(stderr, 64 * 1024),
            async { Ok::<_, PullRequestError>(child.wait().await?) }
        )?;
        if !status.success() {
            return Err(PullRequestError::Command(format!(
                "Provider process exited {status}: {}",
                String::from_utf8_lossy(&err).trim()
            )));
        }
        Ok(out)
    })
    .await
    .map_err(|_| PullRequestError::Timeout)?
}

use axum::{
    Json,
    extract::{Path as AxumPath, Query, State},
};

use super::{DiffQuery, PullRequestError, PullRequestListQuery, ReviewQuery, positive, safe_path};
use crate::{AppState, HttpError};

pub(crate) async fn my_pull_requests(
    State(state): State<AppState>,
    Query(query): Query<PullRequestListQuery>,
) -> Result<Json<serde_json::Value>, HttpError> {
    let params = match query.state {
        Some(state) => serde_json::json!({ "state": state }),
        None => serde_json::json!({}),
    };
    Ok(Json(
        state
            .review_providers
            .call(
                &query.target,
                "list",
                params,
                &state
                    .aow
                    .execution_path()
                    .await
                    .map_err(|e| PullRequestError::Command(e.to_string()))?,
            )
            .await?,
    ))
}

pub(crate) async fn my_pull_request_detail(
    State(state): State<AppState>,
    AxumPath(number): AxumPath<u64>,
    Query(query): Query<ReviewQuery>,
) -> Result<Json<serde_json::Value>, HttpError> {
    positive(number)?;
    Ok(Json(
        state
            .review_providers
            .call(
                &query,
                "detail",
                serde_json::json!({"number":number}),
                &state
                    .aow
                    .execution_path()
                    .await
                    .map_err(|e| PullRequestError::Command(e.to_string()))?,
            )
            .await?,
    ))
}

pub(crate) async fn my_pull_request_diff(
    State(state): State<AppState>,
    AxumPath(number): AxumPath<u64>,
    Query(query): Query<DiffQuery>,
) -> Result<Json<serde_json::Value>, HttpError> {
    positive(number)?;
    safe_path(&query.path)?;
    Ok(Json(state.review_providers.call(&query.target, "diff", serde_json::json!({"number":number,"path":query.path,"patch_only":query.patch_only}), &state.aow.execution_path().await.map_err(|e| PullRequestError::Command(e.to_string()))?).await?))
}

use axum::http::StatusCode;

use crate::HttpError;

pub(super) type Result<T> = std::result::Result<T, PullRequestError>;
#[derive(Debug, thiserror::Error)]
pub enum PullRequestError {
    #[error("{0}")]
    Invalid(String),
    #[error("配置已更新，请重新加载后保存。")]
    Conflict,
    #[error("{0}")]
    Unavailable(String),
    #[error("Provider 脚本执行超时")]
    Timeout,
    #[error("{0}")]
    Command(String),
    #[error("Provider 返回数据不符合协议：{0}")]
    InvalidJson(String),
    #[error(transparent)]
    Io(#[from] std::io::Error),
}
impl From<PullRequestError> for HttpError {
    fn from(error: PullRequestError) -> Self {
        let (status, code) = match &error {
            PullRequestError::Invalid(_) => (StatusCode::BAD_REQUEST, "review_provider_invalid"),
            PullRequestError::Conflict => (StatusCode::CONFLICT, "review_provider_conflict"),
            PullRequestError::Unavailable(_) => (
                StatusCode::SERVICE_UNAVAILABLE,
                "review_provider_unavailable",
            ),
            PullRequestError::Timeout => (StatusCode::GATEWAY_TIMEOUT, "review_provider_timeout"),
            PullRequestError::InvalidJson(_) => {
                (StatusCode::BAD_GATEWAY, "review_provider_invalid_response")
            }
            _ => (StatusCode::BAD_GATEWAY, "review_provider_failed"),
        };
        Self::new(status, code, error.to_string(), None)
    }
}

use aow_protocol::{MyPullRequests, PullRequestDetail, PullRequestDiff};
use serde_json::{Value, json};
use std::{
    collections::HashSet,
    path::{Path, PathBuf},
};

use super::{
    CommitLinks, Provider, ProviderManager, PullRequestError, Result, ReviewQuery, Target,
    absolute, decode, git, invalid_json, parse_remote, positive, run_adapter, safe_path, web_link,
};

impl ProviderManager {
    pub async fn targets(&self, repo: &str, paths: &[PathBuf]) -> Result<Vec<Target>> {
        let providers = self.settings()?.providers;
        Self::targets_for(repo, paths, &providers).await
    }

    pub async fn commit_links(
        &self,
        repo: &str,
        remote: &str,
        commit: &str,
        paths: &[PathBuf],
    ) -> Result<Option<CommitLinks>> {
        let settings = self.settings()?;
        let Some(target) = Self::targets_for(repo, paths, &settings.providers)
            .await?
            .into_iter()
            .find(|target| target.remote == remote)
        else {
            return Ok(None);
        };
        let provider = settings
            .providers
            .iter()
            .find(|p| p.id == target.provider)
            .unwrap();
        let description = self
            .run_provider(
                provider,
                json!({"version":2,"operation":"describe","repository":null,"params":{}}),
                None,
                paths,
            )
            .await?;
        let operations = description
            .get("operations")
            .and_then(Value::as_array)
            .ok_or_else(|| invalid_json("describe requires operations"))?;
        if !operations
            .iter()
            .any(|op| op.as_str() == Some("commit_links"))
        {
            return Ok(None);
        }
        let result = self.run_provider(
            provider,
            json!({"version":2,"operation":"commit_links",
                "repository":{"root":repo,"host":target.host,"path":target.repository,"remote":target.remote},
                "params":{"commit":commit}}),
            Some(Path::new(repo)),
            paths,
        ).await?;
        Ok(Some(CommitLinks {
            remote_url: web_link(&result, "remote_url")?,
            commit_url: web_link(&result, "commit_url")?,
        }))
    }

    pub(super) async fn run_provider(
        &self,
        provider: &Provider,
        request: Value,
        cwd: Option<&Path>,
        paths: &[PathBuf],
    ) -> Result<Value> {
        let script_path = self.config.as_ref().map(|c| {
            c.directory().join(format!(
                "review-providers/{:x}.py",
                md5::compute(provider.script.as_bytes())
            ))
        });
        run_adapter(provider, request, cwd, paths, script_path.as_deref()).await
    }

    pub(super) async fn targets_for(
        repo: &str,
        paths: &[PathBuf],
        providers: &[Provider],
    ) -> Result<Vec<Target>> {
        absolute(repo)?;
        let names = git(repo, &["remote"], paths).await?;
        let mut targets: Vec<Target> = Vec::new();
        for remote in names.lines().filter(|s| !s.is_empty()) {
            let url = git(repo, &["remote", "get-url", "--", remote], paths).await?;
            let Some((host, repository)) = parse_remote(url.trim()) else {
                continue;
            };
            let Some(provider) = providers
                .iter()
                .find(|p| p.enabled && p.hosts.contains(&host))
            else {
                continue;
            };
            targets.push(Target {
                remote: remote.into(),
                host,
                repository,
                provider: provider.id.clone(),
                provider_name: provider.name.clone(),
            });
        }
        Ok(targets)
    }
    pub async fn call(
        &self,
        query: &ReviewQuery,
        operation: &str,
        params: Value,
        paths: &[PathBuf],
    ) -> Result<Value> {
        let settings = self.settings()?;
        let targets = Self::targets_for(&query.repo, paths, &settings.providers).await?;
        let mut matches: Vec<_> = targets
            .into_iter()
            .filter(|t| {
                query
                    .provider
                    .as_deref()
                    .filter(|p| *p != "auto")
                    .is_none_or(|p| t.provider == p)
                    && query.remote.as_ref().is_none_or(|r| &t.remote == r)
            })
            .collect();
        // Two remote aliases for the same repository do not create ambiguity.
        let mut seen = HashSet::new();
        matches.retain(|t| seen.insert((t.provider.clone(), t.host.clone(), t.repository.clone())));
        let target = match matches.len() {
            0 => return Err(PullRequestError::Unavailable(
                "未找到匹配的 PR Provider，请在 Settings → Pull Requests 配置 remote 域名和脚本。"
                    .into(),
            )),
            1 => matches.remove(0),
            _ => {
                return Err(PullRequestError::Invalid(
                    "多个 remote 匹配 PR Provider，请先选择 remote。".into(),
                ));
            }
        };
        let provider = settings
            .providers
            .into_iter()
            .find(|p| p.id == target.provider && p.enabled)
            .ok_or_else(|| PullRequestError::Unavailable("Provider 已停用，请刷新。".into()))?;
        let request = json!({"version":2,"operation":operation,
            "repository":{"root":query.repo,"host":target.host,"path":target.repository,"remote":target.remote},"params":params});
        let result = self
            .run_provider(&provider, request, Some(Path::new(&query.repo)), paths)
            .await?;
        let mut result = match operation {
            "list" => {
                let mut data: MyPullRequests = decode(result)?;
                data.repository = query.repo.clone();
                for pr in &data.pull_requests {
                    positive(pr.number).map_err(invalid_json)?;
                }
                serde_json::to_value(data).unwrap()
            }
            "detail" => {
                let data: PullRequestDetail = decode(result)?;
                if Some(data.summary.number) != params["number"].as_u64() {
                    return Err(invalid_json("detail number differs from request"));
                }
                for file in &data.files {
                    safe_path(&file.path).map_err(invalid_json)?;
                }
                serde_json::to_value(data).unwrap()
            }
            "diff" => {
                let mut data: PullRequestDiff = decode(result)?;
                if Some(data.number) != params["number"].as_u64()
                    || Some(data.path.as_str()) != params["path"].as_str()
                {
                    return Err(invalid_json("diff identity differs from request"));
                }
                if let Some(path) = &data.original_path {
                    safe_path(path).map_err(invalid_json)?;
                }
                data.repository = query.repo.clone();
                serde_json::to_value(data).unwrap()
            }
            _ => return Err(PullRequestError::Invalid("unknown operation".into())),
        };
        let attach = |value: &mut Value| {
            value["provider"] = json!(target.provider);
            value["provider_name"] = json!(target.provider_name);
            value["remote"] = json!(target.remote);
        };
        attach(&mut result);
        if let Some(items) = result
            .get_mut("pull_requests")
            .and_then(Value::as_array_mut)
        {
            for item in items {
                attach(item);
            }
        }
        Ok(result)
    }
}

