    title: String,
    cwd: PathBuf,
    transcript_path: PathBuf,
    trusted_root: PathBuf,
    created_at: String,
}

#[derive(Serialize, Deserialize)]
struct SharesDocument {
    version: u32,
    shares: Vec<StoredShare>,
}

impl StoredShare {
    fn info(&self) -> ShareInfo {
        ShareInfo {
            id: self.id.clone(),
            path: format!("/share/{}", self.token),
            created_at: self.created_at.clone(),
        }
    }

    fn locator(&self) -> Result<AgentSessionLocator, HttpError> {
        let agent = aow_agents::Agent::from_id(&self.agent)
            .filter(|agent| agent.sessions().is_some())
            .ok_or_else(unavailable)?;
        Ok(AgentSessionLocator {
            agent: agent.id(),
            session_id: self.session_id.clone(),
            title: self.title.clone(),
            cwd: self.cwd.clone(),
            transcript_path: self.transcript_path.clone(),
            trusted_root: self.trusted_root.clone(),
        })
    }
}

impl SessionShares {
    pub(crate) fn in_memory() -> Self {
        Self {
            path: None,
            entries: Arc::new(Mutex::new(BTreeMap::new())),
        }
    }

    pub(crate) fn persistent(state_dir: &Path) -> anyhow::Result<Self> {
        let path = state_dir.join(SHARES_FILE);
        let records = match std::fs::read(&path) {
            Ok(bytes) => {
                let document: SharesDocument = serde_json::from_slice(&bytes)?;
                anyhow::ensure!(document.version == 1, "unsupported session shares version");
                document.shares
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Vec::new(),
            Err(error) => return Err(error.into()),
        };
        let entries = records
            .into_iter()
            .map(|record| {
                (
                    record.token.clone(),
                    Arc::new(LiveShare {
                        record,
                        snapshot: tokio::sync::Mutex::new(None),
                    }),
                )
            })
            .collect();
        Ok(Self {
            path: Some(path),
            entries: Arc::new(Mutex::new(entries)),
        })
    }

    fn persist(&self, entries: &BTreeMap<String, Arc<LiveShare>>) -> Result<(), HttpError> {
        if let Some(path) = &self.path {
            aow::atomic_save_document(
                path,
                &SharesDocument {
                    version: 1,
                    shares: entries.values().map(|entry| entry.record.clone()).collect(),
                },
            )
            .map_err(|_| HttpError::internal("无法保存会话分享设置"))?;
        }
        Ok(())
    }

    pub(super) fn find(
        &self,
        agent: &str,
        session_id: &str,
    ) -> Result<Option<ShareInfo>, HttpError> {
        let entries = self.entries.lock().map_err(|_| lock_error())?;
        Ok(entries
            .values()
            .find(|entry| entry.record.agent == agent && entry.record.session_id == session_id)
            .map(|entry| entry.record.info()))
    }

    pub(super) fn create(&self, locator: AgentSessionLocator) -> Result<ShareInfo, HttpError> {
        let mut entries = self.entries.lock().map_err(|_| lock_error())?;
        if let Some(entry) = entries.values().find(|entry| {
            entry.record.agent == locator.agent && entry.record.session_id == locator.session_id
        }) {
            return Ok(entry.record.info());
        }
        let record = StoredShare {
            id: Uuid::new_v4().simple().to_string(),
            token: Uuid::new_v4().simple().to_string(),
            agent: locator.agent.to_owned(),
            session_id: locator.session_id,
            title: locator.title,
            cwd: locator.cwd,
            transcript_path: locator.transcript_path,
            trusted_root: locator.trusted_root,
            created_at: chrono::Utc::now().to_rfc3339(),
        };
        let info = record.info();
        let mut updated = entries.clone();
        updated.insert(
            record.token.clone(),
            Arc::new(LiveShare {
                record,
                snapshot: tokio::sync::Mutex::new(None),
            }),
        );
        self.persist(&updated)?;
        *entries = updated;
        Ok(info)
    }

    pub(super) fn revoke(&self, id: &str) -> Result<(), HttpError> {
        let mut entries = self.entries.lock().map_err(|_| lock_error())?;
        let mut updated = entries.clone();
        updated.retain(|_, entry| entry.record.id != id);
        if updated.len() != entries.len() {
            self.persist(&updated)?;
            *entries = updated;
        }
        Ok(())
    }

    pub(super) fn lookup(&self, token: &str) -> Result<Arc<LiveShare>, HttpError> {
        self.entries
            .lock()
            .map_err(|_| lock_error())?
            .get(token)
            .cloned()
            .ok_or_else(invalid_share)
    }

    pub(super) async fn read(&self, token: &str) -> Result<AgentSessionSnapshot, HttpError> {
        let entry = self.lookup(token)?;
        let mut cached = entry.snapshot.lock().await;
        // Cancellation may happen while waiting for another reader.
        self.lookup(token)?;
        let snapshot = if let Some((captured, snapshot)) = &*cached
            && captured.elapsed() < CACHE_TTL
        {
            snapshot.clone()
        } else {
            let locator = entry.record.locator()?;
            let snapshot = read_snapshot(locator).await?;
            *cached = Some((Instant::now(), snapshot.clone()));
            snapshot
        };
        // Never serve an in-flight parse result after its share was revoked.
        self.lookup(token)?;
        Ok(snapshot)
    }
}

pub(super) fn lock_error() -> HttpError {
    HttpError::internal("会话分享设置暂不可用")
}

fn invalid_share() -> HttpError {
    HttpError::new(
        StatusCode::NOT_FOUND,
        "session_share_not_found",
        "分享链接无效或已取消",
        None,
    )
}

fn unavailable() -> HttpError {
    HttpError::new(
        StatusCode::GONE,
        "shared_session_unavailable",
        "会话记录已不可用",
        None,
    )
}

pub(super) async fn read_snapshot(
    locator: AgentSessionLocator,
) -> Result<AgentSessionSnapshot, HttpError> {
    tokio::task::spawn_blocking(move || snapshot::read(locator))
        .await
        .map_err(|_| HttpError::internal("读取会话失败，请稍后重试"))?
        .map_err(|error| match error {
            snapshot::SnapshotError::NotFound | snapshot::SnapshotError::Invalid(_) => {
                unavailable()
            }
            snapshot::SnapshotError::Io(error) if error.kind() == std::io::ErrorKind::NotFound => {
                unavailable()
            }
            _ => HttpError::internal("读取会话失败，请稍后重试"),
        })
}

use super::*;
use aow_agents::sessions::AgentSession;
use axum::{
    body::{Body, to_bytes},
    http::{
        Request,
        header::{COOKIE, SET_COOKIE},
    },
};
use serde_json::{Value, json};
use tower::ServiceExt;

const FIRST_TURN: &str = "{\"type\":\"event_msg\",\"payload\":{\"type\":\"user_message\",\"message\":\"first question\"}}\n{\"type\":\"event_msg\",\"payload\":{\"type\":\"task_complete\",\"last_agent_message\":\"first answer\"}}\n";

fn state(root: &Path) -> AppState {
    let mut state = AppState::new(root.join("frontend"));
    state.auth = crate::auth::AuthService::persistent(root);
    state.session_shares = SessionShares::persistent(root).unwrap();
    state
}

fn locator(root: &Path) -> AgentSessionLocator {
    AgentSessionLocator {
        agent: "codex",
        session_id: "test-session".into(),
        title: "Shared conversation".into(),
        cwd: root.to_owned(),
        transcript_path: root.join("session.jsonl"),
        trusted_root: root.to_owned(),
    }
}

fn cache_locator(state: &AppState, locator: AgentSessionLocator) {
    let session = AgentSession::new(locator.clone(), chrono::Utc::now(), chrono::Utc::now());
    state
        .aow
        .cache_session_locator(&locator.cwd, &session)
        .unwrap();
}

async fn body(response: Response) -> Value {
    serde_json::from_slice(&to_bytes(response.into_body(), usize::MAX).await.unwrap()).unwrap()
}

async fn request(
    app: &Router,
    method: &str,
    path: &str,
    cookie: Option<&str>,
    payload: Value,
) -> Response {
    let mut request = Request::builder().method(method).uri(path);
    if let Some(cookie) = cookie {
        request = request.header(COOKIE, cookie);
    }
    app.clone()
        .oneshot(
            request
                .header("content-type", "application/json")
                .body(Body::from(payload.to_string()))
                .unwrap(),
        )
        .await
        .unwrap()
}

#[tokio::test]
async fn share_links_follow_the_current_mount_after_restart() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().canonicalize().unwrap();
    std::fs::write(root.join("session.jsonl"), FIRST_TURN).unwrap();
    crate::auth::write_credentials(&root, "admin", "test-password");
    let initial = state(&root).with_base_path(crate::BasePath::parse("/tools/aow").unwrap());
    cache_locator(&initial, locator(&root));
    let cookie = format!(
        "{}={}",
        initial.base_path.cookie_name(),
        initial
            .auth
            .login(
                "password",
                serde_json::json!({"username": "admin", "password": "test-password"})
            )
            .unwrap()
    );
    let app = crate::build_router(initial);
    let share = body(
        request(
            &app,
            "POST",
            "/tools/aow/api/aow/agent-sessions/test-session/share",
            Some(&cookie),
            json!({"agent":"codex", "worktree_path":root}),
        )
        .await,
    )
    .await;
    let token = share["path"]
        .as_str()
        .unwrap()
        .strip_prefix("/tools/aow/share/")
        .unwrap();
    assert_eq!(
        request(
            &app,
            "GET",
            &format!("/tools/aow/api/public/session-shares/{token}"),
            None,
            Value::Null
        )
        .await
        .status(),
        StatusCode::OK
    );

    let restored = state(&root).with_base_path(crate::BasePath::parse("/other").unwrap());
    let cookie = format!(
        "{}={}",
        restored.base_path.cookie_name(),
        restored
            .auth
            .login(
                "password",
                serde_json::json!({"username": "admin", "password": "test-password"})
            )
            .unwrap()
    );
    let app = crate::build_router(restored);
    let info = body(
        request(
            &app,
            "GET",
            "/other/api/aow/agent-sessions/test-session/share?agent=codex",
            Some(&cookie),
            Value::Null,
        )
        .await,
    )
    .await;
    assert_eq!(info["path"], format!("/other/share/{token}"));
    assert_eq!(
        request(
            &app,
            "GET",
            &format!("/other/api/public/session-shares/{token}"),
            None,
            Value::Null
        )
        .await
        .status(),
        StatusCode::OK
    );
}

#[tokio::test]
async fn sharing_requires_login_but_live_reading_survives_restart_and_revocation() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().canonicalize().unwrap();
    std::fs::create_dir(root.join("frontend")).unwrap();
    std::fs::write(root.join("frontend/index.html"), "<div id=root></div>").unwrap();
    crate::auth::write_credentials(&root, "admin", "test-password");
    std::fs::write(root.join("session.jsonl"), FIRST_TURN).unwrap();
    let initial = state(&root);
    let cookie = format!(
        "aow_session={}",
        initial
            .auth
            .login(
                "password",
                serde_json::json!({"username": "admin", "password": "test-password"})
            )
            .unwrap()
    );
    cache_locator(&initial, locator(&root));
    let app = crate::build_router(initial);
    let create_path = "/api/aow/agent-sessions/test-session/share";
    let payload = json!({"agent":"codex", "worktree_path":root});
    assert_eq!(
        request(&app, "POST", create_path, None, payload.clone())
            .await
            .status(),
        StatusCode::UNAUTHORIZED
    );
    let created = request(&app, "POST", create_path, Some(&cookie), payload.clone()).await;
    assert_eq!(created.status(), StatusCode::OK);
    let share = body(created).await;
    assert_eq!(
        body(request(&app, "POST", create_path, Some(&cookie), payload.clone()).await).await,
        share
    );
    assert_eq!(
        body(
            request(
                &app,
                "GET",
                &format!("{create_path}?agent=codex"),
                Some(&cookie),
                Value::Null
            )
            .await
        )
        .await,
        share
    );
    let token = share["path"]
        .as_str()
        .unwrap()
        .strip_prefix("/share/")
        .unwrap();
    let public_path = format!("/api/public/session-shares/{token}");
    let read = request(&app, "GET", &public_path, None, Value::Null).await;
    assert_eq!(read.status(), StatusCode::OK);
    assert!(!read.headers().contains_key(SET_COOKIE));
    assert_eq!(read.headers()[CACHE_CONTROL], "no-store");
    assert_eq!(
        body(read).await["turns"][0]["final"]["text"],
        "first answer"
    );
    let page = request(
        &app,
        "GET",
        share["path"].as_str().unwrap(),
        None,
        Value::Null,
    )
    .await;
    assert_eq!(page.status(), StatusCode::OK);
    assert_eq!(page.headers()["referrer-policy"], "no-referrer");
    assert_eq!(page.headers()["x-robots-tag"], "noindex, nofollow");

    for path in [
        "/api/fs/tree",
        "/api/aow/agent-sessions",
        "/api/terminal/tabs",
        create_path,
    ] {
        let forged_cookie = format!("aow_session={token}");
        assert_eq!(
            request(&app, "GET", path, Some(&forged_cookie), Value::Null)
                .await
                .status(),
            StatusCode::UNAUTHORIZED,
            "{path}"
        );
    }
    assert_eq!(
        request(&app, "DELETE", &public_path, None, Value::Null)
            .await
            .status(),
        StatusCode::UNAUTHORIZED
    );
    assert_eq!(
        request(
            &app,
            "GET",
            &format!("{public_path}/extra"),
            None,
            Value::Null
        )
        .await
        .status(),
        StatusCode::UNAUTHORIZED
    );
    assert_eq!(
        request(
            &app,
            "GET",
            "/api/public/session-shares/unknown",
            None,
            Value::Null
        )
        .await
        .status(),
        StatusCode::NOT_FOUND
    );
    let mut untrusted_payload = payload.clone();
    untrusted_payload["transcript_path"] = json!("/etc/passwd");
    assert_eq!(
        request(&app, "POST", create_path, Some(&cookie), untrusted_payload)
            .await
            .status(),
        StatusCode::UNPROCESSABLE_ENTITY
    );
    assert_eq!(
        request(
            &app,
            "POST",
            "/api/aow/agent-sessions/unscanned/share",
            Some(&cookie),
            payload.clone()
        )
        .await
        .status(),
        StatusCode::BAD_REQUEST
    );

    // Fresh login state and no in-memory locator cache: the public link still works.
    let restarted = state(&root);
    let new_cookie = format!(
        "aow_session={}",
        restarted
            .auth
            .login(
                "password",
                serde_json::json!({"username": "admin", "password": "test-password"})
            )
            .unwrap()
    );
    let app = crate::build_router(restarted.clone());
    assert_eq!(
        request(&app, "GET", &public_path, None, Value::Null)
            .await
            .status(),
        StatusCode::OK
    );
    assert_eq!(
        request(&app, "GET", "/api/fs/tree", Some(&cookie), Value::Null)
            .await
            .status(),
        StatusCode::UNAUTHORIZED
    );
    std::fs::write(
        root.join("session.jsonl"),
        format!("{FIRST_TURN}{FIRST_TURN}"),
    )
    .unwrap();
    tokio::time::sleep(CACHE_TTL + Duration::from_millis(20)).await;
    assert_eq!(
        body(request(&app, "GET", &public_path, None, Value::Null).await).await["turns"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    let revoke_path = format!("/api/aow/session-shares/{}", share["id"].as_str().unwrap());
    assert_eq!(
        request(&app, "DELETE", &revoke_path, None, Value::Null)
            .await
            .status(),
        StatusCode::UNAUTHORIZED
    );
    assert_eq!(
        request(&app, "DELETE", &revoke_path, Some(&new_cookie), Value::Null)
            .await
            .status(),
        StatusCode::NO_CONTENT
    );
    // Cached content is unavailable immediately after revocation, including after restart.
    assert_eq!(
        request(&app, "GET", &public_path, None, Value::Null)
            .await
            .status(),
        StatusCode::NOT_FOUND
    );
    assert!(state(&root).session_shares.lookup(token).is_err());
    cache_locator(&restarted, locator(&root));
    let next_share =
        body(request(&app, "POST", create_path, Some(&new_cookie), payload).await).await;
    assert_ne!(next_share["path"], share["path"]);
}

#[tokio::test]
async fn shared_transcripts_keep_trusted_root_checks_and_hide_internal_paths() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    let shares = SessionShares::in_memory();
    let info = shares.create(locator(root)).unwrap();
    let token = info.path.strip_prefix("/share/").unwrap();
    let error = shares.read(token).await.err().unwrap().into_response();
    assert_eq!(error.status(), StatusCode::GONE);
    assert!(
        !body(error)
            .await
            .to_string()
            .contains(root.to_str().unwrap())
    );

    let outside = tempfile::tempdir().unwrap();
    std::fs::write(outside.path().join("outside.jsonl"), FIRST_TURN).unwrap();
    std::os::unix::fs::symlink(
        outside.path().join("outside.jsonl"),
        root.join("session.jsonl"),
    )
    .unwrap();
    assert_eq!(
        shares
            .read(token)
            .await
            .err()
            .unwrap()
            .into_response()
            .status(),
        StatusCode::GONE
    );
}

#[tokio::test]
async fn a_revoked_share_waiting_for_another_reader_cannot_return_cached_content() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("session.jsonl"), FIRST_TURN).unwrap();
    let shares = SessionShares::in_memory();
    let info = shares.create(locator(dir.path())).unwrap();
    let token = info.path.strip_prefix("/share/").unwrap();
    shares.read(token).await.unwrap();
    let entry = shares.lookup(token).unwrap();
    let guard = entry.snapshot.lock().await;
    let read = shares.read(token);
    tokio::pin!(read);
    tokio::select! {
        _ = &mut read => panic!("read should wait for the cache lock"),
        _ = tokio::task::yield_now() => {}
    }
    shares.revoke(&info.id).unwrap();
    drop(guard);
    assert_eq!(
        read.await.err().unwrap().into_response().status(),
        StatusCode::NOT_FOUND
    );
}

#[test]
fn a_failed_save_does_not_publish_a_share() {
    let dir = tempfile::tempdir().unwrap();
    let shares = SessionShares::persistent(dir.path()).unwrap();
    std::fs::create_dir(dir.path().join(SHARES_FILE)).unwrap();
    assert!(shares.create(locator(dir.path())).is_err());
    assert!(shares.find("codex", "test-session").unwrap().is_none());
}

use std::path::{Path, PathBuf};

use aow_terminald_client::TerminaldClient;

use crate::{
    BasePath, TerminalError, aow, auth, automations, operations, pull_requests, session_shares,
    terminal, workspace_events,
};

#[derive(Clone)]
pub struct AppState {
    pub(crate) base_path: BasePath,
    pub(crate) frontend_dist: PathBuf,
    pub(crate) auth: auth::AuthService,
    pub(crate) session_shares: session_shares::SessionShares,
    pub(crate) terminals: terminal::TerminalManager,
    pub(crate) aow: aow::AowManager,
    pub(crate) automations: Option<automations::AutomationManager>,
    pub(crate) operations: operations::OperationService,
    pub(crate) workspace_events: workspace_events::WorkspaceEvents,
    pub(crate) review_providers: pull_requests::ProviderManager,
}

impl AppState {
    /// Creates an application state with in-memory terminal metadata. This is
    /// useful for embedding and tests; the server binary uses `with_state_dir`.
    pub fn new(frontend_dist: PathBuf) -> Self {
        Self::with_terminald_socket(frontend_dist, TerminaldClient::default_socket_path())
    }

    pub fn with_terminald_socket(frontend_dist: PathBuf, terminald_socket: PathBuf) -> Self {
        Self {
            base_path: BasePath::default(),
            frontend_dist,
            auth: auth::AuthService::disabled(),
            session_shares: session_shares::SessionShares::in_memory(),
            terminals: terminal::TerminalManager::in_memory(TerminaldClient::new(terminald_socket)),
            aow: aow::AowManager::in_memory(),
            automations: None,
            review_providers: pull_requests::ProviderManager::default(),
            operations: operations::OperationService::in_memory(),
            workspace_events: workspace_events::WorkspaceEvents::new(),
        }
    }

    pub fn with_state_dir(
        frontend_dist: PathBuf,
        state_dir: PathBuf,
        terminald_socket: PathBuf,
    ) -> Result<Self, TerminalError> {
        Self::with_runtime_options(frontend_dist, state_dir, terminald_socket)
    }

    pub fn with_runtime_options(
        frontend_dist: PathBuf,
        state_dir: PathBuf,
        terminald_socket: PathBuf,
    ) -> Result<Self, TerminalError> {
        let aow = aow::AowManager::persistent(&state_dir).map_err(|error| {
            TerminalError::Invalid(format!("failed to initialize aow: {error}"))
        })?;
        Ok(Self {
            workspace_events: workspace_events::WorkspaceEvents::new(),
            review_providers: pull_requests::ProviderManager::persistent(&state_dir)
                .map_err(|e| TerminalError::Invalid(e.to_string()))?,
            base_path: BasePath::default(),
            frontend_dist,
            operations: operations::OperationService::persistent(&state_dir.join("operation-logs"))
                .map_err(|error| TerminalError::Invalid(error.to_string()))?,
            auth: auth::AuthService::persistent(&state_dir),
            session_shares: session_shares::SessionShares::persistent(&state_dir).map_err(
                |error| {
                    TerminalError::Invalid(format!("failed to initialize session shares: {error}"))
                },
            )?,
            automations: Some(
                automations::AutomationManager::new(state_dir.clone(), aow.notifications().clone())
                    .map_err(|error| {
                        TerminalError::Invalid(format!("failed to initialize automations: {error}"))
                    })?,
            ),
            terminals: terminal::TerminalManager::persistent(
                state_dir.clone(),
                TerminaldClient::new(terminald_socket),
            )?,
            aow,
        })
    }

    pub fn with_base_path(mut self, base_path: BasePath) -> Self {
        self.base_path = base_path;
        self
    }

    pub fn with_secure_cookies(mut self, enabled: bool) -> Self {
        self.auth.secure_cookies = enabled;
        self
    }

    /// Reconciles durable terminal tabs with the external terminal daemon.
    /// A later terminal request retries this operation if startup happens
    /// while the daemon is unavailable.
    pub async fn reconcile_terminals(&self) -> Result<(), TerminalError> {
        self.terminals.reconcile().await
    }

    pub fn start_agent_notifications(&self) {
        self.terminals.start_agent_notifications(self.aow.clone());
    }

    pub async fn initialize_global_workspace(&self) -> anyhow::Result<()> {
        self.aow.initialize_global().await?;
        Ok(())
    }
}

pub async fn initialize_aow_state(path: &Path) -> anyhow::Result<()> {
    pull_requests::ProviderManager::persistent(path)?;
    aow::AowManager::persistent(path)?
        .initialize_global()
        .await?;
    Ok(())
}

use super::super::*;
use super::{COLS, ROWS, connection::AgentConnection, model::info};
use crate::operations::{Handle, Spec};
use aow_agents::Agent;
use aow_operation_log::Outcome;
use aow_protocol::{
    AgentTerminalCreate, AgentTerminalInfo, AgentTerminalPhase, AgentTerminalState,
    AgentTerminalSubmit,
};

const MAX_TASK_BYTES: usize = 128 * 1024;

pub(crate) async fn create(
    State(state): State<AppState>,
    Json(request): Json<AgentTerminalCreate>,
) -> Result<Json<AgentTerminalInfo>, HttpError> {
    tokio::spawn(async move {
        let log = state.operations.begin(Spec {
            id: Uuid::new_v4().to_string(),
            kind: "agent.create",
            source: "cli",
            title: format!("创建 Agent · {}", request.agent),
            project_id: Some(request.project_id.clone()),
            resource: Some(request.cwd.clone()),
            total: None,
        });
        let result = create_inner(state, request, &log).await;
        match &result {
            Ok(info) if info.state.phase == AgentTerminalPhase::Ready => {
                log.finish(
                    Outcome::Succeeded,
                    if info.state.task_submitted {
                        "Agent 已就绪，初始任务已提交"
                    } else {
                        "Agent 已就绪"
                    },
                );
            }
            Ok(info) => log.finish(
                Outcome::Failed,
                info.state
                    .error
                    .clone()
                    .unwrap_or_else(|| "Agent 初始化失败".into()),
            ),
            Err(error) => log.finish(Outcome::Failed, error.body.message.clone()),
        }
        result
    })
    .await
    .map_err(|error| HttpError::internal(error.to_string()))?
}

async fn create_inner(
    state: AppState,
    request: AgentTerminalCreate,
    log: &Handle,
) -> Result<Json<AgentTerminalInfo>, HttpError> {
    log.progress("检查 Agent 配置和工作目录", None);
    let adapter = Agent::from_id(&request.agent)
        .and_then(Agent::interactive)
        .ok_or_else(|| {
            terminal_http_error(TerminalError::Invalid(format!(
                "interactive startup is not supported for agent {}",
                request.agent
            )))
        })?;
    if !(1..=600).contains(&request.timeout_seconds) {
        return Err(terminal_http_error(TerminalError::Invalid(
            "timeout_seconds must be 1-600".into(),
        )));
    }
    if let Some(task) = &request.task {
        validate_task(task).map_err(terminal_http_error)?;
    }
    validate_directory(&request.cwd)
        .await
        .map_err(terminal_http_error)?;
    let cwd = state
        .aow
        .agent_worktree_path(&request.project_id, &request.cwd)
        .await
        .map_err(crate::aow::aow_http_error)?;
    let launch = state
        .aow
        .resolve_agent_launch(&request.agent, &cwd)
        .await
        .map_err(crate::aow::aow_http_error)?;
    log.progress("创建 Terminal 并启动 Agent", None);
    let tab = state
        .terminals
        .create_agent_with_state(
            CreateTerminalRequest {
                name: None,
                cwd: Some(cwd.clone()),
                workspace_root: Some(cwd),
                shell: None,
                agent_id: Some(request.agent),
                resume_session_id: None,
                rows: Some(ROWS),
                cols: Some(COLS),
            },
            launch,
            Some(AgentTerminalState {
                phase: AgentTerminalPhase::Starting,
                error: None,
                task_submitted: false,
            }),
        )
        .await
        .map_err(terminal_http_error)?;
    state.workspace_events.terminals_changed();
    let manager = state.terminals;
    log.resource(format!("/aow/tabs/terminal/{}", tab.id));
    let pane_id = tab.panes[0].id.clone();
    let log = log.clone();
    // Own the lifecycle independently of the HTTP client. A disconnected CLI
    // must not leave a pane permanently in Starting with no initializer.
    let events = state.workspace_events;
    let result = tokio::spawn(async move {
        manager
            .initialize_agent_lifecycle(
                &pane_id,
                adapter,
                request.task.as_deref(),
                Duration::from_secs(request.timeout_seconds),
                Some(&log),
            )
            .await?;
        manager.cli_agent(&pane_id)
    })
    .await
    .map_err(|error| HttpError::internal(error.to_string()))?
    .map(Json)
    .map_err(terminal_http_error);
    events.terminals_changed();
    result
}

pub(crate) async fn get(
    State(state): State<AppState>,
    AxumPath(pane_id): AxumPath<String>,
) -> Result<Json<AgentTerminalInfo>, HttpError> {
    state
        .terminals
        .reconcile()
        .await
        .map_err(terminal_http_error)?;
    state
        .terminals
        .cli_agent(&pane_id)
        .map(Json)
        .map_err(terminal_http_error)
}

pub(crate) async fn list(
    State(state): State<AppState>,
) -> Result<Json<serde_json::Value>, HttpError> {
    let tabs = state
        .terminals
        .list(None)
        .await
        .map_err(terminal_http_error)?;
    let items: Vec<_> = tabs
        .tabs
        .iter()
        .flat_map(|tab| tab.panes.iter().map(move |pane| (tab, pane)))
        .filter_map(|(tab, pane)| info(tab, pane))
        .collect();
    Ok(Json(serde_json::json!({"items": items})))
}

pub(crate) async fn submit(
    State(state): State<AppState>,
    AxumPath(pane_id): AxumPath<String>,
    Json(request): Json<AgentTerminalSubmit>,
) -> Result<Json<AgentTerminalInfo>, HttpError> {
    validate_task(&request.task).map_err(terminal_http_error)?;
    // This operation also survives HTTP cancellation once started. Retrying a
    // timed-out submission is not automatic: its delivery may be ambiguous.
    tokio::spawn(async move {
        let manager = state.terminals;
        let operation = manager.agent_operation(&pane_id)?;
        let _lease = operation.try_write_owned().map_err(|_| {
            TerminalError::Conflict(
                "pane is initializing, submitting, or controlled by a user".into(),
            )
        })?;
        let mut current = manager.cli_agent(&pane_id)?;
        if current.state.phase != AgentTerminalPhase::Ready
            || current.status != TerminalPaneStatus::Running
        {
            return Err(TerminalError::Conflict("agent is not ready".into()));
        }
        tokio::time::timeout(Duration::from_secs(15), async {
            let mut connection = AgentConnection::claim(&manager.inner.terminald, &pane_id).await?;
            connection.submit(&request.task).await?;
            connection.finish().await
        })
        .await
        .map_err(|_| {
            TerminalError::Conflict(
                "submission timed out; delivery is unknown, do not retry blindly".into(),
            )
        })??;
        current.state.task_submitted = true;
        manager.set_agent_state(&pane_id, current.state)?;
        manager.cli_agent(&pane_id)
    })
    .await
    .map_err(|error| HttpError::internal(error.to_string()))?
    .map(Json)
    .map_err(terminal_http_error)
}

fn validate_task(task: &str) -> Result<(), TerminalError> {
    if task.trim().is_empty()
        || task.len() > MAX_TASK_BYTES
        || task
            .chars()
            .any(|ch| ch.is_control() && !matches!(ch, '\n' | '\r' | '\t'))
    {
        return Err(TerminalError::Invalid(
            "task must contain 1-131072 bytes of text without terminal control characters".into(),
        ));
    }
    Ok(())
}

use super::super::*;
use aow_protocol::{
    TerminalAttachClientMessage, TerminalAttachServerMessage, TerminalControlState,
};
use tokio_tungstenite::tungstenite;

pub(super) struct AgentConnection {
    pub(super) socket: TerminaldAttachStream,
}

impl AgentConnection {
    pub(super) async fn claim(
        client: &TerminaldClient,
        pane_id: &str,
    ) -> Result<Self, TerminalError> {
        let socket = client
            .attach_controlled_with_resume(pane_id, None, None)
            .await
            .map_err(map_client_error)?;
        let mut connection = Self { socket };
        connection
            .send(TerminalAttachClientMessage::Claim { force: false })
            .await?;
        loop {
            match Self::check(connection.socket.next().await)? {
                Some(TerminalAttachServerMessage::Control {
                    state: TerminalControlState::Claimed,
                }) => return Ok(connection),
                Some(TerminalAttachServerMessage::Control { .. }) => {
                    return Err(TerminalError::Conflict(
                        "pane is controlled by another client".into(),
                    ));
                }
                _ => {}
            }
        }
    }

    pub(super) fn check(
        message: Option<Result<tungstenite::Message, tungstenite::Error>>,
    ) -> Result<Option<TerminalAttachServerMessage>, TerminalError> {
        match message {
            Some(Ok(tungstenite::Message::Text(text))) => {
                let message = serde_json::from_str(&text)?;
                match message {
                    TerminalAttachServerMessage::Error { message, .. } => {
                        Err(TerminalError::Conflict(message))
                    }
                    TerminalAttachServerMessage::Status { status, .. }
                        if status != TerminalPaneStatus::Running =>
                    {
                        Err(TerminalError::Conflict("agent exited".into()))
                    }
                    message => Ok(Some(message)),
                }
            }
            None | Some(Ok(tungstenite::Message::Close(_))) => {
                Err(TerminalError::Conflict("terminal connection closed".into()))
            }
            Some(Err(error)) => Err(TerminalError::Daemon(error.to_string())),
            _ => Ok(None),
        }
    }

    pub(super) async fn send(
        &mut self,
        message: TerminalAttachClientMessage,
    ) -> Result<(), TerminalError> {
        self.socket
            .send(tungstenite::Message::Text(
                serde_json::to_string(&message)?.into(),
            ))
            .await
            .map_err(|error| TerminalError::Daemon(error.to_string()))
    }

    pub(super) async fn write(&mut self, data: String) -> Result<(), TerminalError> {
        let request_id = Uuid::new_v4().to_string();
        self.send(TerminalAttachClientMessage::Write {
            request_id: request_id.clone(),
            data,
        })
        .await?;
        loop {
            if matches!(Self::check(self.socket.next().await)?, Some(TerminalAttachServerMessage::Written { request_id: id }) if id == request_id)
            {
                return Ok(());
            }
        }
    }

    pub(super) async fn submit(&mut self, task: &str) -> Result<(), TerminalError> {
        self.write(format!("\x1b[200~{task}\x1b[201~")).await?;
        // Give the TUI's paste/input event a separate iteration before Enter.
        tokio::time::sleep(Duration::from_millis(150)).await;
        self.write("\r".into()).await
    }

    pub(super) async fn finish(&mut self) -> Result<(), TerminalError> {
        self.socket
            .close(None)
            .await
            .map_err(|error| TerminalError::Daemon(error.to_string()))?;
        // terminald releases the controller before completing the close handshake.
        while let Some(message) = self.socket.next().await {
            match message {
                Ok(tungstenite::Message::Close(_)) => break,
                other => {
                    Self::check(Some(other))?;
                }
            }
        }
        Ok(())
    }
}

use super::super::*;
use super::{connection::AgentConnection, model::info};
use crate::operations::Handle;
use aow_agents::interactive::AgentInteractive;
use aow_protocol::{AgentTerminalInfo, AgentTerminalPhase, AgentTerminalState, TerminalScreen};

impl TerminalManager {
    pub(in crate::terminal) fn cli_agent(
        &self,
        pane_id: &str,
    ) -> Result<AgentTerminalInfo, TerminalError> {
        let state = self.lock_state()?;
        let (tab, pane) = find_pane(&state.tabs, pane_id)
            .ok_or_else(|| TerminalError::PaneNotFound(pane_id.into()))?;
        info(&state.tabs[tab], &state.tabs[tab].panes[pane])
            .ok_or_else(|| TerminalError::Invalid("pane was not created by agent create".into()))
    }

    pub(in crate::terminal) fn agent_operation(
        &self,
        pane_id: &str,
    ) -> Result<Arc<tokio::sync::RwLock<()>>, TerminalError> {
        let mut operations = self
            .inner
            .agent_operations
            .lock()
            .map_err(|_| TerminalError::Poisoned)?;
        operations.retain(|_, operation| operation.strong_count() > 0);
        if let Some(operation) = operations.get(pane_id).and_then(std::sync::Weak::upgrade) {
            return Ok(operation);
        }
        let operation = Arc::new(tokio::sync::RwLock::new(()));
        operations.insert(pane_id.into(), Arc::downgrade(&operation));
        Ok(operation)
    }

    pub(super) fn set_agent_state(
        &self,
        pane_id: &str,
        agent: AgentTerminalState,
    ) -> Result<(), TerminalError> {
        let mut state = self.lock_state()?;
        let (tab, pane) = find_pane(&state.tabs, pane_id)
            .ok_or_else(|| TerminalError::PaneNotFound(pane_id.into()))?;
        let old = state.tabs[tab].clone();
        state.tabs[tab].panes[pane].agent_terminal = Some(agent);
        touch_tab(&mut state.tabs[tab]);
        if let Err(error) = self.persist_locked(&state) {
            state.tabs[tab] = old;
            return Err(error);
        }
        Ok(())
    }

    pub(in crate::terminal) async fn initialize_agent_lifecycle(
        &self,
        pane_id: &str,
        adapter: impl AgentInteractive,
        task: Option<&str>,
        timeout: Duration,
        log: Option<&Handle>,
    ) -> Result<(), TerminalError> {
        let operation = self.agent_operation(pane_id)?;
        let _lease = operation.write_owned().await;
        if let Some(log) = log {
            log.progress("等待 Agent 就绪", None);
        }
        let result =
            tokio::time::timeout(timeout, self.initialize_agent(pane_id, adapter, task, log)).await;
        let progress = match result {
            Ok(Ok(())) => AgentTerminalState {
                phase: AgentTerminalPhase::Ready,
                error: None,
                task_submitted: task.is_some(),
            },
            outcome => {
                let error = match outcome {
                    Ok(Err(error)) => error.to_string(),
                    _ => "agent startup timed out; inspect the pane read-only (startup may require login or trust confirmation)".into(),
                };
                let mut progress = self.cli_agent(pane_id)?.state;
                progress.phase = AgentTerminalPhase::Failed;
                progress.error = Some(error);
                progress
            }
        };
        self.set_agent_state(pane_id, progress)
    }

    pub(super) async fn initialize_agent(
        &self,
        pane_id: &str,
        adapter: impl AgentInteractive,
        task: Option<&str>,
        log: Option<&Handle>,
    ) -> Result<(), TerminalError> {
        let mut connection = AgentConnection::claim(&self.inner.terminald, pane_id).await?;
        self.wait_screen(pane_id, &mut connection, |screen| {
            adapter.input_ready(&screen.lines)
        })
        .await?;
        if let Some(log) = log {
            log.progress("Agent 终端已就绪", None);
        }
        if let Some(task) = task {
            if let Some(log) = log {
                log.progress("提交初始任务", None);
            }
            connection.submit(task).await?;
            let mut progress = self.cli_agent(pane_id)?.state;
            progress.task_submitted = true;
            self.set_agent_state(pane_id, progress)?;
        }
        connection.finish().await
    }

    async fn wait_screen(
        &self,
        pane_id: &str,
        connection: &mut AgentConnection,
        predicate: impl Fn(&TerminalScreen) -> bool,
    ) -> Result<TerminalScreen, TerminalError> {
        let mut interval = tokio::time::interval(Duration::from_millis(150));
        loop {
            tokio::select! {
                message = connection.socket.next() => { AgentConnection::check(message)?; }
                _ = interval.tick() => {
                    if let Some(screen) = self.inner.terminald.screen(pane_id).await.map_err(map_client_error)? {
                        if predicate(&screen) { return Ok(screen); }
                    }
                    let runtime = self.inner.terminald.get(pane_id).await.map_err(map_client_error)?;
                    if runtime.is_none_or(|runtime| runtime.status != TerminalPaneStatus::Running) {
                        return Err(TerminalError::Conflict("agent exited before becoming ready".into()));
                    }
                }
            }
        }
    }
}

