use super::*;

pub(super) fn map_client_error(error: TerminaldClientError) -> TerminalError {
    match &error {
        TerminaldClientError::Io(_)
        | TerminaldClientError::Hyper(_)
        | TerminaldClientError::WebSocket(_) => TerminalError::DaemonUnavailable(error.to_string()),
        TerminaldClientError::HttpStatus { status, .. } if *status == StatusCode::CONFLICT => {
            TerminalError::Conflict(error.to_string())
        }
        _ => TerminalError::Daemon(error.to_string()),
    }
}

pub(super) fn map_create_error(error: TerminaldClientError) -> TerminalError {
    match map_client_error(error) {
        TerminalError::Daemon(message) => TerminalError::RuntimeCreate(message),
        error => error,
    }
}

pub(super) fn client_error_is_not_found(error: &TerminaldClientError) -> bool {
    matches!(
        error,
        TerminaldClientError::HttpStatus { status, .. } if *status == StatusCode::NOT_FOUND
    ) || matches!(
        error,
        TerminaldClientError::WebSocket(tungstenite::Error::Http(response))
            if response.status() == StatusCode::NOT_FOUND
    )
}

pub(super) fn runtime_spec(pane: &TerminalPane) -> TerminalRuntimeSpec {
    TerminalRuntimeSpec {
        cwd: pane.cwd.clone(),
        shell: pane.shell.clone(),
        arguments: pane.arguments.clone(),
        environment: Default::default(),
        rows: pane.rows,
        cols: pane.cols,
    }
}

pub(super) fn apply_runtime(pane: &mut TerminalPane, runtime: &TerminalRuntime) -> bool {
    if pane.status == runtime.status
        && pane.exit_code == runtime.exit_code
        && pane.rows == runtime.rows
        && pane.cols == runtime.cols
    {
        return false;
    }
    pane.status = runtime.status;
    pane.exit_code = runtime.exit_code;
    pane.rows = runtime.rows;
    pane.cols = runtime.cols;
    pane.updated_at = timestamp();
    true
}

//! Display titles for agents whose CLI does not publish session titles via OSC.

use aow_agents::{
    Agent,
    sessions::{titles::AgentSessionTitleProvider, tracking::LiveSessionContext},
};
use aow_protocol::{TerminalAgentList, TerminalAgentProcess};

use super::sessions;

pub(super) async fn enrich(detected: &mut TerminalAgentList) {
    for (pane, agent) in &detected.agents {
        let Some(provider) = agent
            .as_deref()
            .and_then(Agent::from_id)
            .and_then(Agent::session_titles)
        else {
            continue;
        };
        let Some(process) = detected.processes.get(pane) else {
            continue;
        };
        let terminal_title = detected.titles.get(pane).map_or("", String::as_str);
        if let Some(title) = native_title(&provider, process.clone(), terminal_title).await {
            detected.titles.insert(pane.clone(), title);
        }
    }
}

async fn native_title(
    provider: &impl AgentSessionTitleProvider,
    process: TerminalAgentProcess,
    terminal_title: &str,
) -> Option<String> {
    let identity = process.clone();
    let environment = tokio::task::spawn_blocking(move || sessions::process_environment(&identity))
        .await
        .ok()??;
    let title = provider
        .session_title(LiveSessionContext {
            pid: Some(process.pid),
            cwd: &process.cwd,
            title: terminal_title,
            environment: &environment,
        })
        .await?;
    sessions::same_process(&process).then_some(title)
}

