    }
    axum::response::Html(format!(
        "<!doctype html><meta charset=utf-8><title>AoW API</title><h1>AoW API</h1><pre>{}</pre>",
        escape_html(&serde_json::to_string_pretty(&schema).unwrap())
    ))
}

pub(crate) async fn spa_or_asset(
    State(state): State<AppState>,
    uri: axum::http::Uri,
) -> Result<Response, HttpError> {
    let requested = uri.path().trim_start_matches('/');
    if requested == "index.html" {
        return serve_spa_index(&state).await;
    }
    let safe_asset = !requested.is_empty()
        && Path::new(requested)
            .components()
            .all(|component| matches!(component, std::path::Component::Normal(_)));
    let candidate = state.frontend_dist.join(requested);
    if !safe_asset || !candidate.is_file() {
        return Err(HttpError::new(
            StatusCode::NOT_FOUND,
            "route_not_found",
            "route not found",
            Some(uri.path().to_owned()),
        ));
    }
    let path = candidate;
    let bytes = tokio::fs::read(&path).await.map_err(|error| {
        HttpError::new(
            StatusCode::SERVICE_UNAVAILABLE,
            "frontend_not_built",
            format!("frontend asset unavailable at {}: {error}", path.display()),
            None,
        )
    })?;
    let content_type = mime_guess::from_path(&path).first_or_octet_stream();
    let cache_control = if requested.starts_with("assets/") {
        "public, max-age=31536000, immutable"
    } else {
        "no-cache"
    };
    Ok((
        [
            (CONTENT_TYPE, content_type.as_ref()),
            (CACHE_CONTROL, cache_control),
        ],
        bytes,
    )
        .into_response())
}

pub(crate) async fn serve_spa_index(state: &AppState) -> Result<Response, HttpError> {
    let path = state.frontend_dist.join("index.html");
    let html = tokio::fs::read_to_string(&path).await.map_err(|error| {
        HttpError::new(
            StatusCode::SERVICE_UNAVAILABLE,
            "frontend_not_built",
            format!("frontend asset unavailable at {}: {error}", path.display()),
            None,
        )
    })?;
    Ok((
        [
            (CONTENT_TYPE, "text/html; charset=utf-8"),
            (CACHE_CONTROL, "no-cache"),
        ],
        state.base_path.inject_html(&html),
    )
        .into_response())
}

//! Bridges registered project roots and Git changes to the workspace SSE stream.

use std::{
    collections::BTreeMap,
    convert::Infallible,
    path::Path,
    sync::{Arc, Mutex},
};

use aow_git_service::{GitChanges, GitWatcher};
use axum::{
    Router,
    extract::State,
    response::sse::{Event, KeepAlive, Sse},
    routing::get,
};
use serde::Serialize;
use tokio::sync::{Notify, watch};

use crate::{AppState, aow::AowManager};

#[derive(Clone, Debug, Serialize)]
struct Snapshot {
    boot_id: String,
    revision: u64,
    projects: u64,
    terminals: u64,
    repositories: BTreeMap<String, u64>,
}

struct Inner {
    changes: watch::Sender<Snapshot>,
    reconcile: Arc<Notify>,
    task: Mutex<Option<tokio::task::JoinHandle<()>>>,
}

impl Drop for Inner {
    fn drop(&mut self) {
        if let Some(task) = self.task.get_mut().unwrap().take() {
            task.abort();
        }
    }
}

#[derive(Clone)]
pub(crate) struct WorkspaceEvents(Arc<Inner>);

impl WorkspaceEvents {
    pub(crate) fn new() -> Self {
        Self(Arc::new(Inner {
            changes: watch::channel(Snapshot {
                boot_id: uuid::Uuid::new_v4().to_string(),
                revision: 0,
                projects: 0,
                terminals: 0,
                repositories: BTreeMap::new(),
            })
            .0,
            reconcile: Arc::new(Notify::new()),
            task: Mutex::new(None),
        }))
    }

    pub(crate) fn projects_changed(&self) {
        self.0.changes.send_modify(|snapshot| {
            snapshot.revision += 1;
            snapshot.projects = snapshot.revision;
        });
        self.reconcile();
    }

    pub(crate) fn terminals_changed(&self) {
        self.0.changes.send_modify(|snapshot| {
            snapshot.revision += 1;
            snapshot.terminals = snapshot.revision;
        });
        // A CLI may have prepared a worktree just before creating the pane.
        self.reconcile();
    }

    fn reconcile(&self) {
        self.0.reconcile.notify_one();
    }

    pub(crate) fn start(&self, aow: AowManager) {
        let mut task = self.0.task.lock().unwrap();
        if task.is_none() {
            *task = Some(tokio::spawn(run(
                aow,
                self.0.changes.clone(),
                self.0.reconcile.clone(),
            )));
        }
    }
}

async fn run(aow: AowManager, changes: watch::Sender<Snapshot>, reconcile: Arc<Notify>) {
    let roots = match aow.repository_roots() {
        Ok(roots) => roots,
        Err(error) => {
            tracing::warn!(%error, "Could not load repositories for Git watching");
            return;
        }
    };
    let watcher = match GitWatcher::new(roots) {
        Ok(watcher) => watcher,
        Err(error) => {
            tracing::warn!(%error, "Could not start Git watching");
            return;
        }
    };
    let mut receiver = watcher.subscribe();
    let mut previous = GitChanges::default();
    loop {
        tokio::select! {
            _ = reconcile.notified() => {
                if let Ok(roots) = aow.repository_roots()
                    && let Err(error) = watcher.set_repositories(roots) {
                    tracing::warn!(%error, "Could not update Git watch roots");
                }
            },
            changed = receiver.changed() => {
                if changed.is_err() { return; }
                let next = receiver.borrow_and_update().clone();
                changes.send_modify(|snapshot| {
                    snapshot.revision += 1;
                    if previous.worktrees != next.worktrees {
                        snapshot.projects = snapshot.revision;
                    }
                    snapshot.repositories.retain(|root, _| next.repositories.contains_key(Path::new(root)));
                    for (root, revision) in &next.repositories {
                        if previous.repositories.get(root) != Some(revision) {
                            snapshot.repositories.insert(root.to_string_lossy().into_owned(), snapshot.revision);
                        }
                    }
                });
                previous = next;
            },
        }
    }
}

pub(crate) fn routes() -> Router<AppState> {
    Router::new().route("/api/workspace/events", get(stream))
}

async fn stream(
    State(state): State<AppState>,
) -> Sse<impl futures_util::Stream<Item = Result<Event, Infallible>>> {
    let stream = futures_util::stream::unfold(
        (state.workspace_events.0.changes.subscribe(), true),
        |(mut receiver, initial)| async move {
            if !initial && receiver.changed().await.is_err() {
                return None;
            }
            let snapshot = receiver.borrow_and_update().clone();
            let event = Event::default()
                .event("workspace")
                .json_data(snapshot)
                .expect("serializable snapshot");
            Some((Ok(event), (receiver, false)))
        },
    );
    Sse::new(stream).keep_alive(KeepAlive::default())
}

#[cfg(test)]
mod tests;

use super::*;
use axum::{
    body::{Body, to_bytes},
    http::{Request, StatusCode},
};
use std::time::Duration;
use tower::ServiceExt;

async fn register(state: &AppState, root: &Path) -> String {
    let notes = tempfile::tempdir().unwrap();
    let response = crate::build_router(state.clone())
        .oneshot(
            Request::post("/api/aow/projects")
                .header("content-type", "application/json")
                .body(Body::from(
                    serde_json::json!({"path": root, "notes_path": notes.path()}).to_string(),
                ))
                .unwrap(),
        )
        .await
        .unwrap();
    let status = response.status();
    let body = to_bytes(response.into_body(), 1024 * 1024).await.unwrap();
    assert_eq!(
        status,
        StatusCode::CREATED,
        "{}",
        String::from_utf8_lossy(&body)
    );
    serde_json::from_slice::<serde_json::Value>(&body).unwrap()["id"]
        .as_str()
        .unwrap()
        .to_owned()
}

async fn git(root: &Path, args: &[&str]) -> String {
    let output = tokio::process::Command::new("git")
        .arg("-C")
        .arg(root)
        .args([
            "-c",
            "user.name=Watch Test",
            "-c",
            "user.email=watch@example.invalid",
        ])
        .args(args)
        .output()
        .await
        .unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8(output.stdout).unwrap()
}

async fn repository() -> tempfile::TempDir {
    let directory = tempfile::tempdir().unwrap();
    git(directory.path(), &["init", "-b", "main"]).await;
    git(
        directory.path(),
        &["commit", "--allow-empty", "-m", "initial"],
    )
    .await;
    directory
}

async fn changed(receiver: &mut watch::Receiver<Snapshot>, root: &Path, after: u64) -> Snapshot {
    tokio::time::timeout(Duration::from_secs(10), async {
        loop {
            let snapshot = receiver.borrow_and_update().clone();
            if snapshot
                .repositories
                .get(root.to_str().unwrap())
                .is_some_and(|revision| *revision > after)
            {
                return snapshot;
            }
            receiver.changed().await.unwrap();
        }
    })
    .await
    .expect("native Git metadata event was not delivered")
}

#[tokio::test]
async fn registered_projects_are_watched_without_clients_and_removal_releases_them() {
    let first = repository().await;
    let second = repository().await;
    let state = AppState::new(first.path().to_owned());
    let first_id = register(&state, first.path()).await;
    let mut receiver = state.workspace_events.0.changes.subscribe();
    changed(&mut receiver, first.path(), 0).await;
    register(&state, second.path()).await;
    let before = changed(&mut receiver, second.path(), 0).await;
    git(
        first.path(),
        &["commit", "--allow-empty", "-m", "first only"],
    )
    .await;
    let after = changed(&mut receiver, first.path(), before.revision).await;
    assert_eq!(before.projects, after.projects);
    assert_eq!(
        before.repositories[second.path().to_str().unwrap()],
        after.repositories[second.path().to_str().unwrap()]
    );
    let response = crate::build_router(state.clone())
        .oneshot(
            Request::delete(format!("/api/aow/projects/{first_id}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::NO_CONTENT);
    tokio::time::timeout(Duration::from_secs(5), async {
        loop {
            if !receiver
                .borrow_and_update()
                .repositories
                .contains_key(first.path().to_str().unwrap())
            {
                break;
            }
            receiver.changed().await.unwrap();
        }
    })
    .await
    .unwrap();
}

#[tokio::test]
async fn stream_starts_with_a_snapshot_and_delivers_terminal_changes_without_git_changes() {
    use futures_util::StreamExt;

    let directory = tempfile::tempdir().unwrap();
    let state = AppState::new(directory.path().to_owned());
    let app = routes().with_state(state.clone());
    let response = app
        .oneshot(
            Request::get("/api/workspace/events")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(response.headers()["content-type"], "text/event-stream");
    let mut stream = response.into_body().into_data_stream();
    let first = tokio::time::timeout(Duration::from_secs(1), stream.next())
        .await
        .unwrap()
        .unwrap()
        .unwrap();
    let first = String::from_utf8(first.to_vec()).unwrap();
    assert!(first.contains("event: workspace"));
    assert!(first.contains("\"terminals\":0"));
    state.workspace_events.terminals_changed();
    let next = tokio::time::timeout(Duration::from_secs(1), stream.next())
        .await
        .unwrap()
        .unwrap()
        .unwrap();
    assert!(
        String::from_utf8(next.to_vec())
            .unwrap()
            .contains("\"terminals\":1")
    );
}

