  const createExplorerEntry = async (source: 'project' | 'notes', parent: string, name: string, kind: 'file' | 'directory') => {
    setOperationError('');
    const created = await filesApi.createEntry(parent, name, kind);
    if (source === 'notes') onNotesChanged(parent);
    else {
