import { useEffect, useRef, type RefObject } from 'react';

const hideDelay = 200;
const overlaySelector = '[role="menu"],[role="dialog"]:not([data-floating-workspace]),[role="alertdialog"],dialog[open],.project-aow-new-menu,.layout-menu,.monaco-menu-container';

function hasOpenOverlay() {
  return [...document.querySelectorAll<HTMLElement>(overlaySelector)].some(element =>
    element.getClientRects().length > 0 && getComputedStyle(element).visibility === 'visible');
}

export function useFloatingAutoHide(panel: RefObject<HTMLDivElement | null>, {
  open, pinned, autoHidden, showRequest, setAutoHidden,
}: {
  open: boolean;
  pinned: boolean;
  autoHidden: boolean;
  showRequest: number;
  setAutoHidden: (hidden: boolean) => void;
}) {
  const hidden = useRef(autoHidden);
  hidden.current = autoHidden;

  useEffect(() => {
    const element = panel.current;
    if (!open || pinned || !element) return;
    // Opening from the launcher or another workspace gives the user time to enter.
    let entered = element.matches(':hover');
    let point: { x: number; y: number } | undefined;
    let pressed = false;
    let dragging = false;
    let timer: number | undefined;
    const clear = () => { window.clearTimeout(timer); timer = undefined; };
    const schedule = () => {
      if (timer !== undefined) return;
      timer = window.setTimeout(() => { timer = undefined; check(true); }, hideDelay);
    };
    const check = (elapsed = false) => {
      if (pressed || dragging) { clear(); return; }
      const bounds = element.getBoundingClientRect();
      const inside = point && point.x >= bounds.left && point.x < bounds.right && point.y >= bounds.top && point.y < bounds.bottom;
      // The launcher remains an explicit toggle even if it overlaps the window.
      if (point && document.elementFromPoint(point.x, point.y)?.closest('.floating-workspace-trigger')) { clear(); return; }
      if (inside && !hidden.current) { entered = true; clear(); return; }
      if (!inside && (!entered || hidden.current)) { clear(); return; }
      // Menus can be portals outside the panel; native pickers can take browser focus.
      // Retry only while an overlay blocks hiding/revealing, including after Escape.
      if (!document.hasFocus() || hasOpenOverlay()
        || document.activeElement?.matches('.project-aow-tab-rename-input')) { schedule(); return; }
      if (inside) {
        entered = true;
        clear();
        hidden.current = false;
        setAutoHidden(false);
      } else if (elapsed) {
        hidden.current = true;
        setAutoHidden(true);
      } else schedule();
    };
    const move = (event: PointerEvent) => {
      if (event.pointerType !== 'mouse') return;
      point = { x: event.clientX, y: event.clientY };
      pressed = event.buttons !== 0;
      check();
    };
    const leave = (event: PointerEvent) => {
      if (event.pointerType !== 'mouse') return;
      point = undefined;
      check();
    };
    const startDrag = () => { dragging = true; clear(); };
    const endDrag = (event: DragEvent) => {
      dragging = false;
      pressed = false;
      point = { x: event.clientX, y: event.clientY };
      check();
    };
    const cancelPointer = () => { pressed = false; check(); };
    const focus = () => check();
    window.addEventListener('pointermove', move, true);
    window.addEventListener('pointerout', move, true);
    window.addEventListener('pointerdown', move, true);
    window.addEventListener('pointerup', move, true);
    window.addEventListener('pointercancel', cancelPointer, true);
    document.documentElement.addEventListener('pointerleave', leave);
    window.addEventListener('dragstart', startDrag, true);
    window.addEventListener('dragend', endDrag, true);
    window.addEventListener('drop', endDrag, true);
    window.addEventListener('focus', focus);
    return () => {
      clear();
      window.removeEventListener('pointermove', move, true);
      window.removeEventListener('pointerout', move, true);
      window.removeEventListener('pointerdown', move, true);
      window.removeEventListener('pointerup', move, true);
      window.removeEventListener('pointercancel', cancelPointer, true);
      document.documentElement.removeEventListener('pointerleave', leave);
      window.removeEventListener('dragstart', startDrag, true);
      window.removeEventListener('dragend', endDrag, true);
      window.removeEventListener('drop', endDrag, true);
      window.removeEventListener('focus', focus);
    };
  }, [open, pinned, showRequest, setAutoHidden, panel]);
}

import { appLocalStorage } from '../lib/basePath';
import { useCallback, useEffect, useRef, useState, type SetStateAction } from 'react';
import { aowApi } from './aowApi';
import type { PinnedWorktrees } from './types';

const legacyStorageKey = 'aow-pinned-worktrees';
const migratedStorageKey = 'aow-pinned-worktrees-migrated';

function legacyPins() {
  try {
    if (appLocalStorage.getItem(migratedStorageKey) === '1') return [];
    const value: unknown = JSON.parse(appLocalStorage.getItem(legacyStorageKey) ?? '[]');
    return Array.isArray(value) ? value.filter((path): path is string => typeof path === 'string' && path.startsWith('/') && !path.includes('\0')) : [];
  } catch { return []; }
}

export function usePinnedWorktrees() {
  const [pinned, setPinned] = useState(new Set<string>());
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const current = useRef(new Set<string>());
  const pending = useRef(0);
  const foregroundPending = useRef(0);
  const queue = useRef(Promise.resolve());
  const accept = useCallback((result: PinnedWorktrees) => {
    const next = new Set(result.paths);
    const paths = [...next];
    if (current.current.size === next.size
      && [...current.current].every((path, index) => path === paths[index])) return;
    current.current = next;
    setPinned(next);
  }, []);
  const run = useCallback((task: () => Promise<void>, background = false) => {
    pending.current += 1;
    if (!background) {
      foregroundPending.current += 1;
      setLoading(true);
    }
    queue.current = queue.current.then(async () => {
      await task();
      setError('');
    }).catch((reason: unknown) => {
      setError(`置顶同步失败：${reason instanceof Error ? reason.message : String(reason)}`);
    }).finally(() => {
      pending.current -= 1;
      if (!background) {
        foregroundPending.current -= 1;
        setLoading(foregroundPending.current > 0);
      }
    });
  }, []);
  const load = useCallback((background = false) => {
    if (pending.current > 0) return;
    run(async () => {
      accept(await aowApi.pinnedWorktrees());
      const legacy = legacyPins();
      if (legacy.length) {
        accept(await aowApi.updatePinnedWorktrees({ add: legacy }));
        try {
          appLocalStorage.setItem(migratedStorageKey, '1');
          appLocalStorage.removeItem(legacyStorageKey);
        } catch { /* Server persistence succeeded even if browser cleanup is unavailable. */ }
      }
    }, background);
  }, [accept, run]);
  const reload = useCallback(() => load(), [load]);
  useEffect(() => {
    load();
    const refresh = () => { if (document.visibilityState === 'visible') load(true); };
    const timer = window.setInterval(refresh, 10000);
    document.addEventListener('visibilitychange', refresh);
    window.addEventListener('focus', refresh);
    return () => {
      clearInterval(timer);
      document.removeEventListener('visibilitychange', refresh);
      window.removeEventListener('focus', refresh);
    };
  }, [load]);
  const update = useCallback((action: SetStateAction<Set<string>>) => {
    run(async () => {
      const before = current.current;
      const next = typeof action === 'function' ? action(new Set(before)) : action;
      const add = [...next].filter((path) => !before.has(path));
      const remove = [...before].filter((path) => !next.has(path));
      const order = !add.length && !remove.length ? [...next] : undefined;
      accept(await aowApi.updatePinnedWorktrees({ add, remove, order }));
    });
  }, [accept, run]);
  return [pinned, update, { loading, error, reload }] as const;
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { aowApi } from './aowApi';
import type { WorktreeRemovalItem, WorktreeRemovalJob } from './types';
import { operationsChangedEvent } from '../features/operations/operations';

export const removalActive = (item: WorktreeRemovalItem) => item.status === 'queued' || item.status === 'running';
export const removalStatusLabel: Record<WorktreeRemovalItem['status'], string> = {
  queued: '排队中', running: '删除中', succeeded: '已删除', failed: '删除失败', interrupted: '已中断',
};

export function useWorktreeRemovals() {
  const [jobs, setJobs] = useState<WorktreeRemovalJob[]>([]);
  const [error, setError] = useState('');
  const mounted = useRef(false);
  const generation = useRef(0);
  const pending = useRef(false);
  const tracked = useRef(new Set<string>());
  const refresh = useCallback(async () => {
    if (pending.current) return;
    pending.current = true;
    const version = generation.current;
    try {
      const result = await aowApi.worktreeRemovals();
      if (mounted.current && generation.current === version) {
        const current = result.filter(job => tracked.current.has(job.id) || job.items.some(removalActive));
        tracked.current = new Set(current.map(job => job.id));
        setJobs(current);
        setError('');
      }
    } catch (reason) {
      if (mounted.current) setError(`无法更新清理进度：${reason instanceof Error ? reason.message : String(reason)}`);
    } finally { pending.current = false; }
  }, []);
  const submitted = useCallback((job: WorktreeRemovalJob) => {
    generation.current += 1;
    tracked.current.add(job.id);
    setJobs(current => [...current.filter(item => item.id !== job.id), job]);
    setError('');
  }, []);
  const dismiss = useCallback((projectId: string) => {
    generation.current += 1;
    setJobs(current => {
      const next = current.filter(job => job.project_id !== projectId || job.items.some(removalActive));
      tracked.current = new Set(next.map(job => job.id));
      return next;
    });
  }, []);
  const active = jobs.some(job => job.items.some(removalActive));
  useEffect(() => {
    mounted.current = true;
    void refresh();
    const onVisible = () => { if (document.visibilityState === 'visible') void refresh(); };
    document.addEventListener('visibilitychange', onVisible);
    window.addEventListener('focus', onVisible);
    window.addEventListener(operationsChangedEvent, onVisible);
    return () => {
      mounted.current = false;
      document.removeEventListener('visibilitychange', onVisible);
      window.removeEventListener('focus', onVisible);
      window.removeEventListener(operationsChangedEvent, onVisible);
    };
  }, [refresh]);
  useEffect(() => {
    // Also retry a failed initial request, and discover tasks from other tabs.
    const timer = window.setInterval(() => { if (document.visibilityState === 'visible') void refresh(); }, active || error ? 1500 : 15000);
    return () => window.clearInterval(timer);
  }, [active, error, refresh]);
  return { jobs, error, refresh, submitted, dismiss };
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { readStored } from './floatingWorkspaceState';
import { terminalApi } from '../features/terminals/terminalApi';
import type { AowProject } from './types';
import { isWorktreeUnallocated, type WorktreeResourceState } from './worktreeResources';
import { subscribeWorkspaceChanges } from '../lib/workspaceEvents';

interface StoredResources {
  documents?: unknown[];
  sessions?: unknown[];
  pullRequests?: unknown[];
  tasks?: unknown[];
}

// Inspect unmounted workspaces without restoring editors or attaching to terminals.
export function useWorktreeResources(projects: AowProject[], externalTabWorkspaces: ReadonlySet<string>) {
  const pathsKey = JSON.stringify(projects.flatMap(project => project.worktrees.map(worktree => worktree.path)).sort());
  const stored = useMemo(() => new Map((JSON.parse(pathsKey) as string[]).map(path => [
    path, readStored<StoredResources>(`aow-workspace-tabs:${path}`, {}),
  ])), [pathsKey]);
  const [terminalSnapshot, setTerminalSnapshot] = useState<{ pathsKey: string; paths: Set<string> }>();
  const [liveResources, setLiveResources] = useState<Map<string, WorktreeResourceState>>(() => new Map());
  const needsInventory = [...stored.keys()].some(path => !liveResources.has(path));

  useEffect(() => {
    if (!needsInventory) return;
    const controller = new AbortController();
    let pending = false;
    const refresh = async () => {
      if (pending || document.visibilityState !== 'visible') return;
      pending = true;
      try {
        const tabs = await terminalApi.list(undefined, controller.signal);
        if (controller.signal.aborted) return;
        const paths = new Set<string>();
        for (const tab of tabs) {
          if (stored.has(tab.workspace_root)) paths.add(tab.workspace_root);
        }
        setTerminalSnapshot(current => current?.pathsKey === pathsKey && current.paths.size === paths.size
          && [...paths].every(path => current.paths.has(path)) ? current : { pathsKey, paths });
      } catch {
        if (!controller.signal.aborted) setTerminalSnapshot(undefined);
      } finally {
        pending = false;
      }
    };
    void refresh();
    // Mounted workspaces already report their inventories through useTerminals.
    const timer = window.setInterval(() => void refresh(), 3000);
    const unsubscribe = subscribeWorkspaceChanges(change => { if (change.reset || change.terminals) void refresh(); });
    document.addEventListener('visibilitychange', refresh);
    return () => {
      controller.abort();
      unsubscribe();
      window.clearInterval(timer);
      document.removeEventListener('visibilitychange', refresh);
    };
  }, [pathsKey, stored, needsInventory]);

  const reportResources = useCallback((path: string, resources?: WorktreeResourceState) => {
    setLiveResources(current => {
      const previous = current.get(path);
      if (previous === resources || (previous && resources
        && previous.hasFrontendTabs === resources.hasFrontendTabs
        && previous.hasTerminalInstances === resources.hasTerminalInstances)) return current;
      const next = new Map(current);
      if (resources === undefined) next.delete(path);
      else next.set(path, resources);
      return next;
    });
  }, []);

  const isUnallocated = useCallback((path: string) => {
    const saved = stored.get(path);
    const resources = liveResources.get(path) ?? {
      hasFrontendTabs: [saved?.documents, saved?.sessions, saved?.pullRequests, saved?.tasks]
        .some(items => Array.isArray(items) && items.length > 0),
      hasTerminalInstances: terminalSnapshot?.pathsKey === pathsKey ? terminalSnapshot.paths.has(path) : undefined,
    };
    return isWorktreeUnallocated({
      ...resources,
      hasFrontendTabs: externalTabWorkspaces.has(path) ? true : resources.hasFrontendTabs,
    });
  }, [liveResources, stored, terminalSnapshot, pathsKey, externalTabWorkspaces]);

  return { isUnallocated, reportResources };
}

export interface WorktreeResourceState {
  // Includes owned, floating, and hosted tabs. Undefined means restoration is incomplete.
  hasFrontendTabs: boolean | undefined;
  // All backend terminal instances count, regardless of origin, visibility, or process status.
  // Undefined means the terminal inventory is not yet known.
  hasTerminalInstances: boolean | undefined;
}

/** Unallocated requires both inventories to be confirmed empty; unknown is not empty. */
export function isWorktreeUnallocated(resources: WorktreeResourceState): boolean {
  return resources.hasFrontendTabs === false && resources.hasTerminalInstances === false;
}

import type { ComponentPropsWithRef } from 'react';
import './aow-icon-button.css';

export function AowIconButton({ className = '', type = 'button', ...props }: ComponentPropsWithRef<'button'>) {
  return <button {...props} type={type} className={`aow-icon-button ${className}`} />;
}

import { useRef, type ReactNode } from 'react';
import { MoreHorizontal } from 'lucide-react';
import { useListRowMenu } from './ListRowMenuContext';
import { AowIconButton } from './AowIconButton';
import './aow-list-row.css';

export function AowListRow({ className, openClassName = '', icon, title, tooltip, children, role, menuLabel,
  menuExpanded, onMenu, onOpen }: {
  className: string;
  openClassName?: string;
  icon?: ReactNode;
  title: string;
  tooltip?: string;
  children: ReactNode;
  role?: 'listitem';
  menuLabel: string;
  menuExpanded?: boolean;
  onMenu?: (x: number, y: number) => void;
  onOpen: () => void;
}) {
  const openButton = useRef<HTMLButtonElement>(null);
  const workspaceMenu = useListRowMenu();
  const openMenu = (x: number, y: number) => {
    if (onMenu) onMenu(x, y);
    else if (openButton.current) workspaceMenu?.open(openButton.current, x, y);
  };

  return <div className={`aow-list-row ${className}`} role={role} onContextMenu={event => {
    event.preventDefault(); event.stopPropagation();
    const bounds = event.currentTarget.getBoundingClientRect();
    openMenu(event.clientX || bounds.x, event.clientY || bounds.bottom);
  }}>
    <button ref={openButton} type="button" data-workspace-open={onMenu ? undefined : true}
      className={`aow-list-row-open ${openClassName}`} title={tooltip} onClick={onOpen}>
      {icon}
      <span className="aow-list-row-content">
        <strong className="aow-list-row-title">{title}</strong>
        {children}
      </span>
    </button>
    <AowIconButton className="aow-list-row-menu" title={menuLabel} aria-label={`${title} ${menuLabel}`}
      aria-haspopup="menu" aria-expanded={menuExpanded ?? (workspaceMenu?.target === openButton.current)}
      onClick={event => {
        event.stopPropagation();
        const bounds = event.currentTarget.getBoundingClientRect();
        openMenu(bounds.right, bounds.bottom);
      }}><MoreHorizontal /></AowIconButton>
  </div>;
}

import { createContext, useCallback, useContext, useId, useLayoutEffect, useRef, useState, type HTMLAttributes, type ReactNode } from 'react';
import { AowPanelHeader, type AowPanelHeaderProps } from './AowPanelHeader';
import './aow-panel.css';

const PanelStackContext = createContext<((anchor: HTMLElement) => void) | undefined>(undefined);

function panelAnchors(viewport: HTMLElement) {
  return [...viewport.querySelectorAll<HTMLElement>('[data-panel-anchor]')]
    .filter(anchor => anchor.closest('.aow-panel-viewport') === viewport && anchor.getClientRects().length && anchor.offsetHeight > 0);
}

// Keep the real header and its placeholder. Docked headers use the stack as
// their fixed-position containing block, so the browser holds them still even
// when scrolling is composited before JavaScript can update the layout.
export function AowPanelStack({ children, className = '', ...props }: HTMLAttributes<HTMLDivElement>) {
  const viewport = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const [overflowPanels, setOverflowPanels] = useState<{ id: string; title: string }[]>([]);
  const crowded = useRef(false);
  const navigate = useCallback((anchor: HTMLElement) => {
    requestAnimationFrame(() => {
      const scroller = viewport.current;
      if (!scroller || !anchor.isConnected) return;
      const anchors = panelAnchors(scroller);
      const previous = crowded.current ? 0 : anchors.slice(0, anchors.indexOf(anchor)).reduce((sum, item) => sum + item.offsetHeight, 0);
      const top = scroller.scrollTop + anchor.getBoundingClientRect().top - scroller.getBoundingClientRect().top - previous;
      scroller.scrollTo({ top: Math.max(0, top), behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' });
    });
  }, []);

  useLayoutEffect(() => {
    const scroller = viewport.current!;
    let frame = 0;
    let disposed = false;
    const measure = () => {
      frame = 0;
      if (!scroller.clientHeight) return;
      const anchors = panelAnchors(scroller);
      const bounds = scroller.getBoundingClientRect();
      const heights = anchors.map(anchor => anchor.offsetHeight);
      const positions = anchors.map(anchor => anchor.getBoundingClientRect().top - bounds.top);
      const total = heights.reduce((sum, height) => sum + height, 0);
      // Many projects or a short window must still leave room to read content.
      // Use one compact jump list when all the docked bars would fill the view.
      crowded.current = total > scroller.clientHeight - Math.min(100, scroller.clientHeight / 2);
      const next = crowded.current ? anchors.map(anchor => ({ id: anchor.id, title: anchor.dataset.panelTitle! })) : [];
      setOverflowPanels(previous => JSON.stringify(previous) === JSON.stringify(next) ? previous : next);
      scroller.style.setProperty('--panel-viewport-top', `${scroller.offsetTop}px`);
      scroller.style.setProperty('--panel-viewport-left', `${scroller.offsetLeft}px`);
      scroller.style.setProperty('--panel-viewport-width', `${scroller.clientWidth}px`);
      let preceding = 0;
      let topInset = 0;
      let bottomInset = 0;
      for (const [index, anchor] of anchors.entries()) {
        const header = anchor.firstElementChild as HTMLElement;
        header.style.removeProperty('transform');
        const naturalTop = positions[index];
        const bottom = scroller.clientHeight - total + preceding;
        const dock = crowded.current ? '' : naturalTop < preceding ? 'top' : naturalTop > bottom ? 'bottom' : '';
        if (header.dataset.docked !== dock) header.dataset.docked = dock;
        if (dock) {
          const offset = `${dock === 'top' ? preceding : bottom}px`;
          if (header.style.getPropertyValue('--panel-dock-offset') !== offset) header.style.setProperty('--panel-dock-offset', offset);
        }
        if (dock === 'top') topInset = preceding + heights[index];
        if (dock === 'bottom') bottomInset = Math.max(bottomInset, total - preceding);
        preceding += heights[index];
      }
      scroller.style.setProperty('--panel-scroll-top', `${topInset}px`);
      scroller.style.setProperty('--panel-scroll-bottom', `${bottomInset}px`);
      scroller.dispatchEvent(new Event('aow-panel-layout'));
    };
    const schedule = () => { if (!disposed && !frame) frame = requestAnimationFrame(measure); };
    const resize = new ResizeObserver(schedule);
    resize.observe(scroller);
    resize.observe(content.current!);
    const mutations = new MutationObserver(schedule);
    mutations.observe(content.current!, { childList: true, subtree: true, attributes: true, attributeFilter: ['hidden', 'class', 'data-panel-title'] });
    scroller.addEventListener('scroll', schedule, { passive: true });
    measure();
    return () => {
      disposed = true;
      cancelAnimationFrame(frame);
      resize.disconnect(); mutations.disconnect();
      scroller.removeEventListener('scroll', schedule);
    };
  }, []);

  return <PanelStackContext.Provider value={navigate}>
    <div {...props} className={`aow-panel-stack ${className}`}>
      {overflowPanels.length ? <select className="aow-panel-jump" aria-label="快速定位面板" value="" onChange={event => {
        const anchor = document.getElementById(event.target.value);
        anchor?.querySelector<HTMLButtonElement>('.aow-panel-header-title')?.click();
      }}><option value="" disabled>快速定位面板</option>{overflowPanels.map(panel => <option key={panel.id} value={panel.id}>{panel.title}</option>)}</select> : null}
      <div ref={viewport} className="aow-panel-viewport">
        <div ref={content} className="aow-panel-content">{children}</div>
      </div>
    </div>
  </PanelStackContext.Provider>;
}

interface Props extends Omit<AowPanelHeaderProps, 'onToggle' | 'onNavigate' | 'children' | 'className'> {
  children: ReactNode;
  className?: string;
  headerClassName?: string;
  bodyClassName?: string;
  bodyRole?: 'list';
  empty?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
}

export function usePanelCollapsed(empty: boolean, controlled?: boolean, onChange?: (collapsed: boolean) => void) {
  const [override, setOverride] = useState<boolean>();
  const collapsed = controlled ?? override ?? empty;
  const change = (next: boolean) => { setOverride(next); onChange?.(next); };
  return [collapsed, change] as const;
}

export function AowPanel({ children, className = '', headerClassName, bodyClassName, bodyRole, empty = false,
  collapsed: controlled, onCollapsedChange, controlsId, ...header }: Props) {
  const id = useId();
  const anchor = useRef<HTMLDivElement>(null);
  const navigate = useContext(PanelStackContext);
  const [collapsed, change] = usePanelCollapsed(empty, controlled, onCollapsedChange);
  useLayoutEffect(() => {
    const header = anchor.current!.firstElementChild as HTMLElement;
    const scroller = header.closest<HTMLElement>('.aow-panel-viewport');
    if (!scroller) return;
    // Fixed headers are outside the native scroll chain. Forward gestures only
    // on the header, leaving content scrolling on the browser's compositor.
    const wheel = (event: WheelEvent) => {
      if (event.defaultPrevented || event.ctrlKey || !header.dataset.docked) return;
      const unit = event.deltaMode === WheelEvent.DOM_DELTA_LINE ? parseFloat(getComputedStyle(scroller).lineHeight) || 16
        : event.deltaMode === WheelEvent.DOM_DELTA_PAGE ? scroller.clientHeight : 1;
      event.preventDefault();
      scroller.scrollBy({ top: event.deltaY * unit, left: event.deltaX * unit, behavior: 'instant' });
    };
    header.addEventListener('wheel', wheel, { passive: false });
    return () => header.removeEventListener('wheel', wheel);
  }, []);
  const bodyId = controlsId ?? `${id}-body`;
  return <section className={`aow-panel ${className}`} aria-label={header.title} data-collapsed={collapsed || undefined}>
    <div ref={anchor} id={`${id}-anchor`} data-panel-anchor data-panel-title={header.title}>
      <AowPanelHeader {...header} className={headerClassName} collapsed={collapsed} controlsId={bodyId}
        onToggle={() => change(!collapsed)} onNavigate={() => { if (collapsed) change(false); if (anchor.current) navigate?.(anchor.current); }} />
    </div>
    <div id={bodyId} className={`aow-panel-body ${bodyClassName ?? ''}`} role={bodyRole} hidden={collapsed}>{children}</div>
  </section>;
}

// Virtual lists in a panel share the stack's scroll position instead of adding
// an inner scrollbar. Re-measure when another panel changes height above them.
export function usePanelListViewport(count: number, rowHeight: number, active = true) {
  const host = useRef<HTMLDivElement>(null);
  const [range, setRange] = useState({ start: 0, end: 0 });
  useLayoutEffect(() => {
    const element = host.current;
    const viewport = element?.closest<HTMLElement>('.aow-panel-viewport');
    if (!element || !viewport || !active) return;
    const measure = () => {
      const box = viewport.getBoundingClientRect(), list = element.getBoundingClientRect();
      const visible = viewport.clientHeight > 0 && list.bottom > box.top && list.top < box.bottom;
      const start = visible ? Math.max(0, Math.floor((box.top - list.top) / rowHeight) - 8) : 0;
      const end = visible ? Math.min(count, Math.ceil((box.bottom - list.top) / rowHeight) + 8) : 0;
      setRange(previous => previous.start === start && previous.end === end ? previous : { start, end });
    };
    viewport.addEventListener('scroll', measure, { passive: true });
    viewport.addEventListener('aow-panel-layout', measure);
    measure();
    return () => { viewport.removeEventListener('scroll', measure); viewport.removeEventListener('aow-panel-layout', measure); };
  }, [count, rowHeight, active]);
  const reveal = useCallback((index: number) => {
    const element = host.current, viewport = element?.closest<HTMLElement>('.aow-panel-viewport');
    if (!element || !viewport) return;
    const box = viewport.getBoundingClientRect(), style = getComputedStyle(viewport);
    const top = element.getBoundingClientRect().top + index * rowHeight;
    const start = box.top + parseFloat(style.getPropertyValue('--panel-scroll-top') || '0');
    const end = box.bottom - parseFloat(style.getPropertyValue('--panel-scroll-bottom') || '0');
    if (top < start) viewport.scrollTop += top - start;
    else if (top + rowHeight > end) viewport.scrollTop += top + rowHeight - end;
  }, [rowHeight]);
  return { host, ...range, reveal };
}

import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState, type HTMLAttributes, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { ChevronRight } from 'lucide-react';
import { AowIconButton } from './AowIconButton';

export interface AowPanelHeaderProps {
  title: string;
  tooltip?: ReactNode;
  icon?: ReactNode;
  className?: string;
  collapsed?: boolean;
  controlsId?: string;
  onToggle?: () => void;
  onNavigate?: () => void;
  details?: ReactNode;
  actions?: ReactNode;
  children?: ReactNode;
}

function PanelHeaderTooltip({ id, anchor, children, onClose }: {
  id: string; anchor: HTMLElement; children: ReactNode; onClose: () => void;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ left: 0, top: 0 });
  useLayoutEffect(() => {
    const bounds = ref.current?.getBoundingClientRect();
    if (!bounds) return;
    const rect = anchor.getBoundingClientRect();
    setPosition({
      left: Math.max(8, Math.min(rect.left, window.innerWidth - bounds.width - 8)),
      top: Math.max(0, rect.top - bounds.height - 4),
    });
  }, [anchor, children]);
  useEffect(() => {
    const keydown = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); };
    window.addEventListener('keydown', keydown);
    window.addEventListener('scroll', onClose, true);
    window.addEventListener('resize', onClose);
    return () => {
      window.removeEventListener('keydown', keydown);
      window.removeEventListener('scroll', onClose, true);
      window.removeEventListener('resize', onClose);
    };
  }, [onClose]);
  return createPortal(<div ref={ref} id={id} role="tooltip" className="aow-panel-header-tooltip" style={position}>
    {children}
  </div>, document.body);
}

export function AowPanelHeader({ title, tooltip, icon, className, collapsed = false, controlsId, onToggle, onNavigate, details, actions, children }: AowPanelHeaderProps) {
  const tooltipId = useId();
  const [anchor, setAnchor] = useState<HTMLElement | null>(null);
  const closeTooltip = useCallback(() => setAnchor(null), []);
  const tooltipProps: HTMLAttributes<HTMLElement> = tooltip ? {
    'aria-describedby': anchor ? tooltipId : undefined,
    onPointerEnter: event => { if (event.pointerType !== 'touch') setAnchor(event.currentTarget); },
    onPointerLeave: closeTooltip,
    onPointerDown: closeTooltip,
    onFocus: event => { if (event.currentTarget.matches(':focus-visible')) setAnchor(event.currentTarget); },
    onBlur: closeTooltip,
  } : {};
  const content = <>{onToggle && !onNavigate ? <ChevronRight className={collapsed ? undefined : 'expanded'} /> : null}{icon}<strong>{title}</strong>{details}</>;

  return <header className={`side-title aow-panel-header${className ? ` ${className}` : ''}`}>
    {onNavigate && onToggle ? <AowIconButton className="aow-panel-toggle" aria-label={`${collapsed ? '展开' : '收起'} ${title}`} aria-expanded={!collapsed} aria-controls={controlsId}
      onClick={() => { closeTooltip(); onToggle(); }}><ChevronRight className={collapsed ? undefined : 'expanded'} /></AowIconButton> : null}
    {onNavigate
      ? <button className="aow-panel-header-title" type="button" aria-label={`定位 ${title}`} {...tooltipProps} onClick={() => { closeTooltip(); onNavigate(); }}>{content}</button>
      : onToggle
      ? <button className="aow-panel-header-title" type="button" aria-expanded={!collapsed} aria-controls={controlsId}
        {...tooltipProps} onClick={() => { closeTooltip(); onToggle(); }}>{content}</button>
      : <span className="aow-panel-header-title" {...tooltipProps} tabIndex={tooltip ? 0 : undefined}>{content}</span>}
    {actions ? <span className="aow-panel-header-actions">{actions}</span> : null}
    {children}
    {tooltip && anchor ? <PanelHeaderTooltip id={tooltipId} anchor={anchor} onClose={closeTooltip}>{tooltip}</PanelHeaderTooltip> : null}
  </header>;
}

import { useCallback, useEffect, useId, useRef, useState, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { TriangleAlert, X } from 'lucide-react';

interface ConfirmationItem {
  id: string;
  label: string;
  detail?: string;
  icon?: ReactNode;
}

export interface ConfirmationOptions {
  title: string;
  description: string;
  items?: ConfirmationItem[];
  warning?: string;
  confirmLabel?: string;
  danger?: boolean;
}

export function ConfirmationDialog({ title, description, items, warning, confirmLabel = '确认', danger = false, onResult }: ConfirmationOptions & {
  onResult: (confirmed: boolean) => void;
}) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const cancelRef = useRef<HTMLButtonElement>(null);
  const backdropPointerRef = useRef(false);
  const id = useId();

  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;
    // A modal dialog contains keyboard focus and makes the workspace inert,
    // including terminals that finish restoring while confirmation is open.
    dialog.showModal();
    cancelRef.current?.focus();
    return () => { dialog.close(); };
  }, []);

  const outsideDialog = (event: React.PointerEvent<HTMLDialogElement> | React.MouseEvent<HTMLDialogElement>) => {
    const bounds = event.currentTarget.getBoundingClientRect();
    return event.target === event.currentTarget
      && (event.clientX < bounds.left || event.clientX > bounds.right
        || event.clientY < bounds.top || event.clientY > bounds.bottom);
  };

  return createPortal(
    <dialog
      ref={dialogRef}
      className="project-aow-modal confirmation-dialog"
      role="alertdialog"
      aria-modal="true"
      aria-labelledby={`${id}-title`}
      aria-describedby={`${id}-description${warning ? ` ${id}-warning` : ''}`}
      onCancel={(event) => { event.preventDefault(); onResult(false); }}
      onPointerDown={(event) => { backdropPointerRef.current = outsideDialog(event); event.stopPropagation(); }}
      onClick={(event) => {
        if (backdropPointerRef.current && outsideDialog(event)) onResult(false);
        backdropPointerRef.current = false;
        event.stopPropagation();
      }}
      onKeyDown={(event) => {
        event.stopPropagation();
        if (event.key !== 'Tab') return;
        const buttons = Array.from(event.currentTarget.querySelectorAll<HTMLButtonElement>('button:not(:disabled)'));
        const boundary = event.shiftKey ? buttons[0] : buttons.at(-1);
        if (document.activeElement === boundary) {
          event.preventDefault();
          (event.shiftKey ? buttons.at(-1) : buttons[0])?.focus();
        }
      }}
    >
      <header>
        <h2 id={`${id}-title`}>{title}</h2>
        <button type="button" title="关闭对话框" aria-label="关闭对话框" onClick={() => onResult(false)}><X /></button>
      </header>
      <div className="confirmation-body">
        <p id={`${id}-description`}>{description}</p>
        {items?.length ? <ul className="confirmation-items">
          {items.map((item) => <li key={item.id}>
            {item.icon}
            <div><strong>{item.label}</strong>{item.detail ? <span>{item.detail}</span> : null}</div>
          </li>)}
        </ul> : null}
        {warning ? <div className="confirmation-warning" id={`${id}-warning`}><TriangleAlert aria-hidden="true" /><p>{warning}</p></div> : null}
      </div>
      <footer>
        <button ref={cancelRef} type="button" onClick={() => onResult(false)}>取消</button>
        <button type="button" className={danger ? 'danger' : 'primary'} onClick={() => onResult(true)}>{confirmLabel}</button>
      </footer>
    </dialog>,
    document.body,
  );
}

export function useConfirmation() {
  const [options, setOptions] = useState<ConfirmationOptions>();
  const resolveRef = useRef<((confirmed: boolean) => void) | undefined>(undefined);

  const confirm = useCallback((next: ConfirmationOptions): Promise<boolean> => {
    if (resolveRef.current) return Promise.resolve(false);
    return new Promise((resolve) => {
      resolveRef.current = resolve;
      setOptions(next);
    });
  }, []);

  const onResult = useCallback((confirmed: boolean) => {
    const resolve = resolveRef.current;
    resolveRef.current = undefined;
    setOptions(undefined);
    resolve?.(confirmed);
  }, []);

  useEffect(() => () => {
    // Unmounting the owner cancels pending destructive actions.
    resolveRef.current?.(false);
    resolveRef.current = undefined;
  }, []);

  return { confirm, confirmationDialog: options ? <ConfirmationDialog {...options} onResult={onResult} /> : null };
}

import { createContext, useContext } from 'react';

export const ListRowMenuContext = createContext<{
