import { useLayoutEffect, useRef, useState } from 'react';
import { filesApi } from './api';

interface Upload {
  id: number;
  file: File;
  directory: string;
  status: 'waiting' | 'uploading' | 'success' | 'error';
  loaded: number;
  path?: string;
  error?: string;
}

export function useExplorerUploads(root: string, onUploaded: (directory: string, path: string) => Promise<void>) {
  const [uploads, setUploads] = useState<Upload[]>([]);
  const queue = useRef<Upload[]>([]);
  const nextId = useRef(0);
  const epoch = useRef(0);
  const running = useRef(false);
  const controller = useRef<AbortController | undefined>(undefined);
  const completed = useRef(onUploaded);
  useLayoutEffect(() => { completed.current = onUploaded; });
  useLayoutEffect(() => {
    setUploads([]);
    return () => {
      epoch.current += 1;
      queue.current = [];
      controller.current?.abort();
      running.current = false;
    };
  }, [root]);

  const enqueue = (directory: string, files: File[]) => {
    if (!files.length) return;
    const items: Upload[] = files.map((file) => ({ id: ++nextId.current, file, directory, status: 'waiting', loaded: 0 }));
    queue.current.push(...items);
    setUploads((previous) => [...previous, ...items]);
    if (running.current) return;
    running.current = true;
    const generation = epoch.current;
    const update = (id: number, changes: Partial<Upload>) => {
      if (epoch.current === generation) setUploads((previous) => previous.map((item) => item.id === id ? { ...item, ...changes } : item));
    };
    void (async () => {
      try {
        while (queue.current.length && epoch.current === generation) {
          const item = queue.current.shift()!;
          const abort = new AbortController();
          controller.current = abort;
          update(item.id, { status: 'uploading' });
          try {
            if (!item.file.name || item.file.name === '.' || item.file.name === '..' || /[/\\\0]/.test(item.file.name)) {
              throw new Error('文件名无效，请重新选择文件');
            }
            const result = await filesApi.uploadFile(item.directory, item.file, (loaded) => update(item.id, { loaded }), { keepBoth: true, signal: abort.signal });
            if (epoch.current !== generation) return;
            update(item.id, { status: 'success', path: result.path, loaded: item.file.size });
            try { await completed.current(item.directory, result.path); }
            catch (reason) { update(item.id, { error: `文件已上传，目录刷新失败：${reason instanceof Error ? reason.message : String(reason)}` }); }
          } catch (reason) {
            update(item.id, { status: 'error', error: reason instanceof Error ? reason.message : String(reason) });
          }
        }
      } finally {
        if (epoch.current === generation) { running.current = false; controller.current = undefined; }
      }
    })();
  };

  return {
    uploads, enqueue,
    cancel: () => {
      const waiting = new Set(queue.current.map((item) => item.id));
      queue.current = [];
      controller.current?.abort();
      setUploads((previous) => previous.map((item) => waiting.has(item.id) ? { ...item, status: 'error', error: '上传已取消' } : item));
    },
    clear: () => setUploads((previous) => previous.filter((item) => item.status === 'waiting' || item.status === 'uploading')),
    retry: (item: Upload) => {
      setUploads((previous) => previous.filter((previous) => previous.id !== item.id));
      enqueue(item.directory, [item.file]);
    },
  };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { filesApi } from './api';
import type { PinnedDirectories } from './types';

export function usePinnedDirectories() {
  const [paths, setPaths] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [pending, setPending] = useState<Set<string>>(() => new Set());
  const pendingRef = useRef(new Set<string>());
  const revisionRef = useRef(-1);
  const reloadRef = useRef(0);

  const accept = useCallback((result: PinnedDirectories) => {
    if (result.revision < revisionRef.current) return;
    revisionRef.current = result.revision;
    setPaths(result.paths);
  }, []);

  const reload = useCallback(async () => {
    const generation = ++reloadRef.current;
    setLoading(true);
    setError('');
    try {
      const result = await filesApi.pinnedDirectories();
      if (generation === reloadRef.current) accept(result);
    } catch (reason) {
      if (generation === reloadRef.current) setError(`收藏加载失败：${reason instanceof Error ? reason.message : String(reason)}`);
    } finally {
      if (generation === reloadRef.current) setLoading(false);
    }
  }, [accept]);

  useEffect(() => { void reload(); }, [reload]);

  const toggle = useCallback(async (path: string, pinned: boolean) => {
    if (pendingRef.current.has(path)) return;
    pendingRef.current.add(path);
    setPending(new Set(pendingRef.current));
    setError('');
    try {
      accept(await filesApi.updatePinnedDirectories(pinned ? { remove: [path] } : { add: [path] }));
    } catch (reason) {
      setError(`收藏保存失败：${reason instanceof Error ? reason.message : String(reason)}`);
    } finally {
      pendingRef.current.delete(path);
      setPending(new Set(pendingRef.current));
    }
  }, [accept]);

  return { paths, loading, error, pending, reload, toggle };
}

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Check, Copy, ExternalLink, GitCommitHorizontal, LoaderCircle, X } from 'lucide-react';
import type { GitCommit, GitCommitDetail } from './types';

interface Props {
  commit: GitCommit;
  detail?: GitCommitDetail;
  loading: boolean;
  error?: string;
  anchor: HTMLElement;
  pinned: boolean;
  upstream?: string;
  onEnter: () => void;
  onLeave: () => void;
  onClose: () => void;
}

const margin = 8;
const gap = 8;
const desiredWidth = 430;

function relativeTime(value: string) {
  const timestamp = Date.parse(value);
  if (!Number.isFinite(timestamp)) return value;
  const seconds = Math.round((timestamp - Date.now()) / 1000);
  const ranges: [Intl.RelativeTimeFormatUnit, number][] = [
    ['year', 31_536_000], ['month', 2_592_000], ['week', 604_800],
    ['day', 86_400], ['hour', 3_600], ['minute', 60],
  ];
  const formatter = new Intl.RelativeTimeFormat('zh-CN', { numeric: 'auto' });
  for (const [unit, size] of ranges) {
    if (Math.abs(seconds) >= size) return formatter.format(Math.round(seconds / size), unit);
  }
  return formatter.format(seconds, 'second');
}

function absoluteTime(value: string) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return new Intl.DateTimeFormat('zh-CN', { dateStyle: 'medium', timeStyle: 'medium' }).format(date);
}

async function copyText(value: string) {
  if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(value); return; }
  const input = document.createElement('textarea');
  input.value = value; input.style.position = 'fixed'; input.style.opacity = '0';
  document.body.appendChild(input); input.select(); document.execCommand('copy'); input.remove();
}

function shortId(value: string) { return value.slice(0, 8); }

export function CommitDetailPopover({ commit, detail, loading, error, anchor, pinned, upstream, onEnter, onLeave, onClose }: Props) {
  const card = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ left: margin, top: margin, width: desiredWidth });
  const [copied, setCopied] = useState(false);
  const popoverId = `commit-detail-${commit.id}`;

  const updatePosition = () => {
    if (!anchor.isConnected) { onClose(); return; }
    const rect = anchor.getBoundingClientRect();
    if (rect.bottom < 0 || rect.top > window.innerHeight) { onClose(); return; }
    const maximumWidth = Math.max(1, window.innerWidth - margin * 2);
    const width = Math.min(desiredWidth, maximumWidth);
    const right = window.innerWidth - rect.right - gap - margin;
    const left = rect.left - gap - margin;
    let x = right >= Math.min(320, width) ? rect.right + gap : rect.left - gap - width;
    if (right < Math.min(320, width) && left < Math.min(320, width)) x = rect.right + gap;
    x = Math.max(margin, Math.min(x, window.innerWidth - width - margin));
    const height = card.current?.getBoundingClientRect().height ?? 320;
    const y = Math.max(margin, Math.min(rect.top - 6, window.innerHeight - height - margin));
    setPosition({ left: x, top: y, width });
  };

  useLayoutEffect(updatePosition, [anchor, detail, loading, error]);
  useEffect(() => {
    const update = () => updatePosition();
    window.addEventListener('resize', update);
    window.addEventListener('scroll', update, true);
    return () => { window.removeEventListener('resize', update); window.removeEventListener('scroll', update, true); };
  });
  useEffect(() => { setCopied(false); }, [commit.id]);
  useEffect(() => {
    if (pinned) card.current?.focus({ preventScroll: true });
  }, [pinned, commit.id]);

  const identityChanged = detail && (detail.author.name !== detail.committer.name || detail.author.email !== detail.committer.email || detail.author.date !== detail.committer.date);
  const stats = detail?.stats;

  return createPortal(
    <div
      ref={card}
      id={popoverId}
      className={`commit-detail-popover${pinned ? ' pinned' : ''}`}
      role="dialog"
      aria-label={`提交详情：${commit.subject}`}
      tabIndex={-1}
      style={position}
      onPointerEnter={onEnter}
      onPointerLeave={onLeave}
      onFocusCapture={onEnter}
      onBlurCapture={(event) => { if (!event.currentTarget.contains(event.relatedTarget as Node | null)) onLeave(); }}
    >
      {pinned ? <button className="commit-detail-close" title="关闭" onClick={onClose}><X /></button> : null}
      {loading ? <div className="commit-detail-loading"><LoaderCircle className="spinning" />正在加载提交详情…</div> : null}
      {error ? <div className="commit-detail-error">{error}</div> : null}
      {detail ? <>
        <div className="commit-detail-author">
          <span className="commit-avatar">{detail.author.name.trim().charAt(0).toUpperCase() || '?'}</span>
          <div><strong>{detail.author.name}</strong><span>{detail.author.email}</span></div>
          <time title={absoluteTime(detail.author.date)}>{relativeTime(detail.author.date)}</time>
        </div>
        <h4>{detail.subject}</h4>
        {detail.body.trim() ? <pre className="commit-detail-body">{detail.body.trim()}</pre> : null}
        {identityChanged ? <div className="commit-detail-committer">提交者：{detail.committer.name} &lt;{detail.committer.email}&gt; · {absoluteTime(detail.committer.date)}</div> : null}
        {stats ? <div className="commit-detail-stats">
          <span>{stats.files_changed} 个文件变更</span>
          <b>+{stats.insertions}</b><em>-{stats.deletions}</em>
          {stats.binary_files ? <span>{stats.binary_files} 个二进制文件</span> : null}
        </div> : null}
        <div className="commit-detail-meta">
          <span className={`commit-sync-state ${commit.is_pushed ? 'pushed' : 'outgoing'}`}>{commit.is_pushed ? `已推送${upstream ? ` · ${upstream}` : ''}` : '仅本地'}</span>
          {detail.refs.map((ref) => <span className="commit-detail-ref" key={ref}>{ref}</span>)}
        </div>
        {detail.parents.length > 1 ? <div className="commit-detail-parents"><span>Parents</span>{detail.parents.map((parent) => <code key={parent}>{shortId(parent)}</code>)}</div> : null}
        <footer className="commit-detail-footer">
          <GitCommitHorizontal /><code title={detail.id}>{detail.id}</code>
          <button title="复制 commit SHA" onClick={() => { void copyText(detail.id).then(() => { setCopied(true); window.setTimeout(() => setCopied(false), 1200); }); }}>{copied ? <Check /> : <Copy />}</button>
          {detail.commit_url ? <a href={detail.commit_url} target="_blank" rel="noopener noreferrer"><ExternalLink />在 {detail.remote_name ?? '远程仓库'} 中打开</a> : null}
        </footer>
      </> : null}
    </div>,
    document.body,
  );
}

import { GitBranch } from 'lucide-react';
import { gitApi } from './api';
import { filesApi } from '../files/api';
import { FileTypeIcon } from '../files/FileTypeIcon';
import { MobilePageHeader, MobileRefresh, MobileState } from '../../mobile/MobilePrimitives';
import { useMobileResource, useMobileScroll, type MobileRoute } from '../../mobile/mobileState';
import type { MobileNavigate } from '../../mobile/mobileState';

export function MobileGit({ route, visible, navigate, back }: { route: MobileRoute; visible: boolean; navigate: MobileNavigate; back: () => void }) {
  const status = useMobileResource(`git.${route.workspace}`, () => gitApi.gitStatus(route.workspace), visible && !route.diff);
  const scroll = useMobileScroll(`git.${route.workspace}`, !!status.data);
  if (route.diff) return <MobileDiff route={route} back={back} />;
  return <section className="mobile-content-page">
    <MobilePageHeader title="Git 变更" actions={<MobileRefresh reload={status.reload} loading={status.loading} />} />
    <div className="mobile-scroll" ref={scroll}>
      {status.data && <div className="mobile-branch-card"><GitBranch size={23} /><div><strong>{status.data.branch || 'Detached HEAD'}</strong><span>{status.data.files.length} 个变更 · 领先 {status.data.ahead} / 落后 {status.data.behind}</span></div></div>}
      <MobileState loading={status.loading && !status.data} error={status.error} retry={status.reload} empty={status.data?.files.length === 0 ? '工作区干净，暂无文件变更。' : undefined} />
      <div className="mobile-list">{status.data?.files.map((file) => <div key={file.path} className="mobile-git-row">
        <div className="mobile-git-file"><FileTypeIcon path={file.path} /><span>{file.path}</span></div>
        <div className="mobile-git-actions">
          {file.index_status !== ' ' && file.index_status !== '?' && <button onClick={() => navigate({ workspace: route.workspace, view: 'git', diff: file.path, staged: '1' })}><b>{file.index_status}</b>已暂存 · 查看 Diff</button>}
          {file.worktree_status !== ' ' && <button onClick={() => navigate({ workspace: route.workspace, view: 'git', diff: file.path, untracked: file.worktree_status === '?' ? '1' : undefined })}><b>{file.worktree_status}</b>{file.worktree_status === '?' ? '未跟踪' : '工作区'} · 查看 Diff</button>}
        </div>
      </div>)}</div>
    </div>
  </section>;
}

function MobileDiff({ route, back }: { route: MobileRoute; back: () => void }) {
  const repository = route.repository ?? route.workspace;
  const diff = useMobileResource(`diff.${repository}.${route.diff}.${route.staged}.${route.commit}.${route.originalPath}`, async () => {
    const result = route.commit ? await gitApi.gitCommitDiff(repository, route.commit, route.diff!, route.originalPath)
      : await gitApi.gitDiff(repository, route.diff, route.staged === '1');
    if (route.untracked === '1' && !result.patch && result.modified == null) {
      result.patch = (await filesApi.readText(`${repository}/${route.diff}`)).content.split('\n').map(line => '+' + line).join('\n');
    }
    return result;
  });
  const scroll = useMobileScroll(`diff.${route.workspace}.${route.diff}.${route.staged}`, !!diff.data);
  return <section className="mobile-content-page">
    <MobilePageHeader title={route.diff!.split('/').pop()!} subtitle={route.commit ? `Commit ${route.commit.slice(0, 8)}` : route.staged === '1' ? '已暂存变更' : '工作区变更'} back={back} actions={<MobileRefresh reload={diff.reload} loading={diff.loading} />} />
    <div className="mobile-scroll mobile-diff-reader" ref={scroll}>
      <MobileState loading={diff.loading && !diff.data} error={diff.error} retry={diff.reload} empty={diff.data && !diff.data.patch ? '暂无文本差异，文件可能是二进制格式。' : undefined} />
      {diff.data?.truncated && <div className="mobile-inline-error">差异较大，仅展示部分内容。</div>}
      <pre className="mobile-diff">{diff.data?.patch.split('\n').map((line, index) => <span key={index} className={line.startsWith('@@') ? 'hunk' : line.startsWith('+') ? 'added' : line.startsWith('-') ? 'removed' : ''}>{line || ' '}<br /></span>)}</pre>
    </div>
  </section>;
}

import { appLocalStorage } from '../../lib/basePath';
import { Fragment, memo, useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import {
  ArrowDown, ArrowUp, Check, ChevronDown, ChevronRight, Cloud, FileDiff, GitBranch, History, List,
  MoreHorizontal, RefreshCw, TreePine,
} from 'lucide-react';
import { gitApi } from './api';
import { useSourceControlPolling } from './useSourceControlPolling';
import { SourceControlChanges, type ChangeItem } from './SourceControlChanges';
import { buildCommitGraph, type CommitGraphRow } from './commitGraph';
import type { GitCommit, GitCommitDetail, GitCommitFile, GitFileStatus, RepositorySummary } from './types';
import { CommitDetailPopover } from './CommitDetailPopover';
import { AowIconButton } from '../../components/AowIconButton';
import { AowPanel, AowPanelStack } from '../../components/AowPanel';

type Layout = 'list' | 'tree';
type CommitState = 'outgoing' | 'pushed';

interface Props {
  root: string;
  visible: boolean;
  refreshGeneration?: number;
  activeDocumentId?: string;
  onOpenDiff: (repo: string, file: GitFileStatus, staged: boolean) => void;
  onOpenCommitDiff: (repo: string, commit: GitCommit, file: GitCommitFile) => void;
  fixedRepository?: RepositorySummary;
  titleCase?: boolean;
  aowHeader?: boolean;
}
interface CommitPopoverState { commit: GitCommit; anchor: HTMLElement; pinned: boolean }
interface CommitDetailCacheEntry { detail?: GitCommitDetail; loading?: boolean; error?: string }
interface SectionHeaderProps {
  title: string;
  icon: ReactNode;
  aow?: boolean;
  hideLegacyHeader?: boolean;
  collapsed?: boolean;
  controlsId?: string;
  count?: number;
  details?: ReactNode;
  actions?: ReactNode;
  menu?: ReactNode;
  onToggle?: () => void;
  children?: ReactNode;
}

function SourceSection({ title, icon, aow = false, hideLegacyHeader, collapsed = false, controlsId, count, details, actions, menu, onToggle, children }: SectionHeaderProps) {
  const trailing = <>{count !== undefined ? <span className="source-section-count">{count}</span> : null}{details}</>;
  if (aow) return <AowPanel
    headerClassName="source-section-header" title={title} icon={icon} collapsed={collapsed}
    controlsId={controlsId} onCollapsedChange={onToggle} details={trailing} actions={actions}
  >{menu}{children}</AowPanel>;
  if (hideLegacyHeader) return <>{children}</>;
  return <><h3 className="source-section-header"><button className="source-section-toggle" type="button" aria-expanded={!collapsed} aria-controls={controlsId} onClick={onToggle}>
    {collapsed ? <ChevronRight /> : <ChevronDown />}{icon}<span className="source-section-title">{title}</span>{trailing}
  </button></h3>{children}</>;
}

const CommitChanges = memo(function CommitChanges({ repository, commit, files, layout, active, onOpen }: {
  repository: string; commit: GitCommit; files: GitCommitFile[]; layout: Layout; active: boolean; onOpen: Props['onOpenCommitDiff'];
}) {
  const items = useMemo<ChangeItem[]>(() => files.map(file => ({
    id: `${commit.id}:${file.path}`, path: file.path, status: file.status, title: `${file.status} · ${file.path}`,
  })), [commit.id, files]);
  const open = useCallback((item: ChangeItem) => {
    const file = files.find(file => file.path === item.path);
    if (file) onOpen(repository, commit, file);
  }, [repository, commit, files, onOpen]);
  return <SourceControlChanges items={items} layout={layout} active={active} onOpen={open} />;
});

const graphLaneGap = 12;
const graphPadding = 7;
const graphRowHeight = 28;
const graphMiddle = graphRowHeight / 2;
const graphNodeRadius = 4.5;

function graphX(lane: number) { return graphPadding + lane * graphLaneGap; }
function graphWidth(row: CommitGraphRow) { return graphX(row.columns - 1) + graphNodeRadius + 1; }

function laneStyle(color: string) { return { '--lane-color': color } as CSSProperties; }

function CommitGraph({ commit, row, expanded }: { commit: GitCommit; row: CommitGraphRow; expanded: boolean }) {
  const state: CommitState = commit.is_pushed ? 'pushed' : 'outgoing';
  const nodeX = graphX(row.lane);
  const width = graphWidth(row);
  return <span className="commit-graph-layer" style={{ width }} aria-hidden="true">
    <svg width={width} height={graphRowHeight} viewBox={`0 0 ${width} ${graphRowHeight}`}>
      {row.edges.map((edge, index) => {
        const from = graphX(edge.from); const to = graphX(edge.to);
        const startY = edge.startsAtNode ? graphMiddle : 0;
        return <path key={`${edge.from}:${edge.to}:${index}`} className="commit-graph-edge" style={laneStyle(edge.color)} d={`M ${from} ${startY} C ${from} ${graphMiddle}, ${to} ${graphMiddle}, ${to} ${graphRowHeight}`} />;
      })}
      {row.incoming.map(line => <path key={line.lane} className="commit-graph-edge" style={laneStyle(line.color)} d={`M ${graphX(line.lane)} 0 C ${graphX(line.lane)} ${graphMiddle / 2}, ${nodeX} ${graphMiddle / 2}, ${nodeX} ${graphMiddle}`} />)}
      <circle className={`commit-graph-node ${state}`} style={laneStyle(row.color)} cx={nodeX} cy={graphMiddle} r={graphNodeRadius} />
    </svg>
    {expanded ? row.continuing.map((line) => <i key={line.lane} className="commit-graph-continuation" style={{ left: graphX(line.lane), ...laneStyle(line.color) }} />) : null}
  </span>;
}

export const SourceControl = memo(function SourceControl({ root, visible, refreshGeneration = 0, activeDocumentId, onOpenDiff, onOpenCommitDiff, fixedRepository, titleCase = false, aowHeader = false }: Props) {
  const [repositories, setRepositories] = useState<RepositorySummary[]>([]);
  const [selectedRepository, setRepository] = useState('');
  const repository = fixedRepository?.path ?? selectedRepository;
  const [workingFiles, setWorkingFiles] = useState<GitFileStatus[]>([]);
  const [commits, setCommits] = useState<GitCommit[]>([]);
  const [expanded, setExpanded] = useState<Record<string, GitCommitFile[] | null>>({});
  const [branchesCollapsedOverride, setBranchesCollapsed] = useState<boolean>();
  const [changesCollapsedOverride, setChangesCollapsed] = useState<boolean>();
  const [commitsCollapsedOverride, setCommitsCollapsed] = useState<boolean>();
  const [layout, setLayout] = useState<Layout>(() => appLocalStorage.getItem('aow-git-layout') === 'tree' ? 'tree' : 'list');
  const [changesLayout, setChangesLayout] = useState<Layout>(() => {
    const saved = appLocalStorage.getItem('aow-git-changes-layout') ?? appLocalStorage.getItem('aow-git-layout');
    return saved === 'tree' ? 'tree' : 'list';
  });
  const [commitsLayout, setCommitsLayout] = useState<Layout>(() => {
    const saved = appLocalStorage.getItem('aow-git-commits-layout') ?? appLocalStorage.getItem('aow-git-layout');
    return saved === 'tree' ? 'tree' : 'list';
  });
  const [layoutMenu, setLayoutMenu] = useState<'all' | 'changes' | 'commits'>();
  const panelRef = useRef<HTMLElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const [menuPosition, setMenuPosition] = useState({ x: 0, y: 0 });
  const gitCommandRunning = useRef(false);
  const [gitOperation, setGitOperation] = useState<{ repository: string; command: 'pull' | 'push'; state: 'running' | 'success' | 'error'; message?: string }>();
  const [branch, setBranch] = useState('');
  const [upstream, setUpstream] = useState<string>();
  const [upstreamCommit, setUpstreamCommit] = useState<string>();
  const [ahead, setAhead] = useState(0);
  const [behind, setBehind] = useState(0);
  const [error, setError] = useState('');
  const branchesCollapsed = branchesCollapsedOverride ?? (aowHeader && !repository);
  const changesCollapsed = changesCollapsedOverride ?? (aowHeader && !workingFiles.length && !error);
  const commitsCollapsed = commitsCollapsedOverride ?? (aowHeader && !commits.length && !error);
  const [refreshKey, setRefreshKey] = useState(0);
  const repositoryRef = useRef(repository);
  const detailGenerationRef = useRef(0);
  const detailCacheRef = useRef(new Map<string, CommitDetailCacheEntry>());
  const [detailVersion, setDetailVersion] = useState(0);
  const [commitPopover, setCommitPopover] = useState<CommitPopoverState>();
  const hoverTimerRef = useRef<number | undefined>(undefined);
  const closeTimerRef = useRef<number | undefined>(undefined);
  const suppressFocusPreviewRef = useRef(false);
  repositoryRef.current = repository;

  const clearHoverTimer = () => { if (hoverTimerRef.current !== undefined) { window.clearTimeout(hoverTimerRef.current); hoverTimerRef.current = undefined; } };
  const clearCloseTimer = () => { if (closeTimerRef.current !== undefined) { window.clearTimeout(closeTimerRef.current); closeTimerRef.current = undefined; } };
  const closeCommitPopover = () => { clearHoverTimer(); clearCloseTimer(); setCommitPopover(undefined); };
  const detailKey = (commitId: string) => `${repository}\0${commitId}`;
  const loadCommitDetail = (commit: GitCommit) => {
    const key = detailKey(commit.id);
    const requestedRepository = repository;
    const requestedGeneration = detailGenerationRef.current;
    const cached = detailCacheRef.current.get(key);
    if (cached?.loading || cached?.detail) return;
    detailCacheRef.current.set(key, { loading: true });
    setDetailVersion((value) => value + 1);
    void gitApi.gitCommitDetail(repository, commit.id).then((detail) => {
      if (repositoryRef.current !== requestedRepository || detailGenerationRef.current !== requestedGeneration) return;
      detailCacheRef.current.set(key, { detail });
      setDetailVersion((value) => value + 1);
    }).catch((reason) => {
      if (repositoryRef.current !== requestedRepository || detailGenerationRef.current !== requestedGeneration) return;
      detailCacheRef.current.set(key, { error: reason instanceof Error ? reason.message : String(reason) });
      setDetailVersion((value) => value + 1);
    });
  };
  const showCommitPopover = (commit: GitCommit, anchor: HTMLElement, pinned: boolean) => {
    clearHoverTimer(); clearCloseTimer();
    setCommitPopover({ commit, anchor, pinned });
    loadCommitDetail(commit);
  };
  const scheduleCommitPreview = (commit: GitCommit, anchor: HTMLElement) => {
    clearCloseTimer(); clearHoverTimer();
    if (commitPopover?.pinned) return;
    hoverTimerRef.current = window.setTimeout(() => showCommitPopover(commit, anchor, false), 450);
  };
  const schedulePopoverClose = () => {
    clearHoverTimer(); clearCloseTimer();
    if (commitPopover?.pinned) return;
    closeTimerRef.current = window.setTimeout(() => setCommitPopover(undefined), 160);
  };

  useEffect(() => { appLocalStorage.setItem('aow-git-layout', layout); }, [layout]);
  useEffect(() => { appLocalStorage.setItem('aow-git-changes-layout', changesLayout); }, [changesLayout]);
  useEffect(() => { appLocalStorage.setItem('aow-git-commits-layout', commitsLayout); }, [commitsLayout]);
  useEffect(() => {
    if (!visible) { closeCommitPopover(); setLayoutMenu(undefined); }
  }, [visible]);
  useEffect(() => {
    setLayoutMenu(undefined);
    detailGenerationRef.current += 1;
    detailCacheRef.current.clear();
    closeCommitPopover();
  }, [repository]);
  useLayoutEffect(() => {
    if (!layoutMenu) return;
    const trigger = panelRef.current?.querySelector<HTMLButtonElement>(`[data-source-menu="${layoutMenu}"]`);
    const bounds = menuRef.current?.getBoundingClientRect();
    if (!trigger || !bounds) return;
    const anchor = trigger.getBoundingClientRect();
    setMenuPosition({
      x: Math.max(4, Math.min(anchor.right - bounds.width, window.innerWidth - bounds.width - 4)),
      y: Math.max(4, Math.min(anchor.bottom, window.innerHeight - bounds.height - 4)),
    });
  }, [layoutMenu]);
  useEffect(() => {
    if (!layoutMenu) return;
    const trigger = panelRef.current?.querySelector<HTMLButtonElement>(`[data-source-menu="${layoutMenu}"]`);
    const dismiss = () => setLayoutMenu(undefined);
    const onPointerDown = (event: PointerEvent) => {
      const target = event.target as Node;
      if (!menuRef.current?.contains(target) && !trigger?.contains(target)) dismiss();
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      dismiss();
      trigger?.focus({ preventScroll: true });
    };
    document.addEventListener('pointerdown', onPointerDown, true);
    document.addEventListener('keydown', onKeyDown);
    window.addEventListener('blur', dismiss);
    window.addEventListener('resize', dismiss);
    window.addEventListener('scroll', dismiss, true);
    return () => {
      document.removeEventListener('pointerdown', onPointerDown, true);
      document.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('blur', dismiss);
      window.removeEventListener('resize', dismiss);
      window.removeEventListener('scroll', dismiss, true);
    };
  }, [layoutMenu]);
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape' || !commitPopover) return;
      const anchor = commitPopover.anchor;
      closeCommitPopover();
      if (anchor.isConnected) {
        suppressFocusPreviewRef.current = true;
        anchor.focus({ preventScroll: true });
        queueMicrotask(() => { suppressFocusPreviewRef.current = false; });
      }
    };
    const onPointerDown = (event: PointerEvent) => {
      if (!commitPopover?.pinned) return;
      const target = event.target as Node;
      if (commitPopover.anchor.contains(target) || (target instanceof Element && target.closest('.commit-detail-popover'))) return;
      closeCommitPopover();
    };
    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('pointerdown', onPointerDown);
    return () => { document.removeEventListener('keydown', onKeyDown); document.removeEventListener('pointerdown', onPointerDown); };
  }, [commitPopover]);
  useEffect(() => () => { clearHoverTimer(); clearCloseTimer(); }, []);
  useEffect(() => {
    if (fixedRepository) {
      setRepositories([fixedRepository]);
      setRepository(fixedRepository.path);
      return;
    }
    if (!visible) return;
    const controller = new AbortController();
    void gitApi.repositories(root, controller.signal).then((items) => {
      if (controller.signal.aborted) return;
      setRepositories(items);
      setRepository((current) => items.some((item) => item.path === current)
        ? current
        : items[0]?.path ?? '');
    }).catch((reason: Error) => { if (!controller.signal.aborted) setError(reason.message); });
    return () => controller.abort();
  }, [fixedRepository, root, visible, refreshKey]);
  useEffect(() => {
    setWorkingFiles([]); setBranch(''); setAhead(0); setBehind(0);
    setCommits([]); setUpstream(undefined); setUpstreamCommit(undefined);
    setExpanded({}); setError('');
  }, [repository]);
  const refresh = useSourceControlPolling(repository, visible, refreshGeneration, {
    status: (status) => {
      setWorkingFiles((previous) => previous.length === status.files.length && previous.every((file, index) => {
        const next = status.files[index];
        return file.path === next.path && file.index_status === next.index_status
          && file.worktree_status === next.worktree_status && file.original_path === next.original_path;
      }) ? previous : status.files);
      setBranch(status.branch); setAhead(status.ahead); setBehind(status.behind);
    },
    log: (log) => {
      setCommits((previous) => JSON.stringify(previous) === JSON.stringify(log.commits) ? previous : log.commits);
      setUpstream(log.upstream ?? undefined); setUpstreamCommit(log.upstream_commit ?? undefined);
      const ids = new Set(log.commits.map((commit) => commit.id));
      setExpanded((previous) => Object.keys(previous).every((id) => ids.has(id))
        ? previous : Object.fromEntries(Object.entries(previous).filter(([id]) => ids.has(id))));
      for (const key of detailCacheRef.current.keys()) {
        if (!ids.has(key.slice(key.indexOf('\0') + 1))) detailCacheRef.current.delete(key);
      }
      setCommitPopover((previous) => previous && !ids.has(previous.commit.id) ? undefined : previous);
    },
    error: setError,
  });

  const workingChanges = useMemo<ChangeItem[]>(() => workingFiles.flatMap((file) => {
    const rows: ChangeItem[] = [];
    if (file.index_status !== ' ' && file.index_status !== '?') rows.push({ id: `diff:${repository}:true:${file.path}`, path: file.path, status: `${file.index_status} S`, title: `${file.path} · staged` });
    if (file.worktree_status !== ' ') rows.push({ id: `diff:${repository}:false:${file.path}`, path: file.path, status: file.worktree_status === '?' ? 'U' : file.worktree_status, title: `${file.path} · working tree` });
    return rows;
  }), [workingFiles, repository]);
  const openWorkingChange = useCallback((item: ChangeItem) => {
    const file = workingFiles.find(file => file.path === item.path);
    if (file) onOpenDiff(repository, file, item.id === `diff:${repository}:true:${file.path}`);
  }, [workingFiles, repository, onOpenDiff]);

  const toggleCommit = async (commit: GitCommit) => {
    if (commit.id in expanded) { setExpanded((value) => { const next = { ...value }; delete next[commit.id]; return next; }); return; }
    const requestedRepository = repository;
    const requestedGeneration = detailGenerationRef.current;
    setExpanded((value) => ({ ...value, [commit.id]: null })); setError('');
    try {
      const result = await gitApi.gitCommitFiles(requestedRepository, commit.id);
      if (repositoryRef.current !== requestedRepository || detailGenerationRef.current !== requestedGeneration) return;
      setExpanded((value) => commit.id in value ? { ...value, [commit.id]: result.files } : value);
    } catch (reason) {
      if (repositoryRef.current !== requestedRepository || detailGenerationRef.current !== requestedGeneration) return;
      setExpanded((value) => { const next = { ...value }; delete next[commit.id]; return next; });
      setError(reason instanceof Error ? reason.message : String(reason));
    }
  };

  const commitGraph = useMemo(() => buildCommitGraph(commits), [commits]);
  const runGitCommand = async (command: 'pull' | 'push') => {
    setLayoutMenu(undefined);
    if (!repository || gitCommandRunning.current) return;
    const requestedRepository = repository;
    gitCommandRunning.current = true;
    setGitOperation({ repository: requestedRepository, command, state: 'running' });
    try {
      await gitApi.gitSync(requestedRepository, command);
      setGitOperation({ repository: requestedRepository, command, state: 'success' });
    } catch (reason) {
      setGitOperation({ repository: requestedRepository, command, state: 'error', message: reason instanceof Error ? reason.message : String(reason) });
    } finally {
      gitCommandRunning.current = false;
      // A failed pull can still update remote refs or leave conflict files.
      if (repositoryRef.current === requestedRepository) refresh();
    }
  };
  const toggleChangesSection = () => {
    if (!changesCollapsed && layoutMenu === 'changes') setLayoutMenu(undefined);
    setChangesCollapsed(!changesCollapsed);
  };
  const toggleCommitsSection = () => {
    if (!commitsCollapsed) closeCommitPopover();
    if (!commitsCollapsed && layoutMenu === 'commits') setLayoutMenu(undefined);
    setCommitsCollapsed(!commitsCollapsed);
  };
  const sectionIdPrefix = `source-control-${repository || root}`.replace(/[^a-zA-Z0-9_-]/g, '-');
  const branchesSectionId = `${sectionIdPrefix}-branches`;
  const changesSectionId = `${sectionIdPrefix}-changes`;
  const commitsSectionId = `${sectionIdPrefix}-commits`;
  const renderLayoutMenu = (target: 'all' | 'changes' | 'commits') => {
    if (layoutMenu !== target) return null;
    const current = target === 'all' ? layout : target === 'commits' ? commitsLayout : changesLayout;
    const selectLayout = (next: Layout) => {
      if (target === 'all') setLayout(next);
      if (target === 'changes') setChangesLayout(next);
      if (target === 'commits') setCommitsLayout(next);
      setLayoutMenu(undefined);
    };
    return createPortal(<div ref={menuRef} className="project-aow-context-menu layout-menu" role="menu"
      aria-label={`${target === 'all' ? 'Source Control' : target === 'changes' ? 'Changes' : 'Commits'} 视图选项`}
      style={{ left: menuPosition.x, top: menuPosition.y }} onPointerDown={event => event.stopPropagation()} onContextMenu={event => event.preventDefault()}>
      <button role="menuitemradio" aria-checked={current === 'list'} onClick={() => selectLayout('list')}><List /> View as list{current === 'list' ? <Check className="layout-menu-check" /> : null}</button>
      <button role="menuitemradio" aria-checked={current === 'tree'} onClick={() => selectLayout('tree')}><TreePine /> View as Tree{current === 'tree' ? <Check className="layout-menu-check" /> : null}</button>
      {target === 'commits' ? <>
        <hr />
        <button role="menuitem" disabled={!repository || gitOperation?.state === 'running'} onClick={() => void runGitCommand('pull')}><ArrowDown /> git pull</button>
        <button role="menuitem" disabled={!repository || gitOperation?.state === 'running'} onClick={() => void runGitCommand('push')}><ArrowUp /> git push</button>
      </> : null}
    </div>, document.body);
  };

  const Container = aowHeader ? AowPanelStack : Fragment;
  return (
    <section ref={panelRef} className={`side-view source-control${commitsCollapsed ? ' commits-collapsed' : ''}`}>
      <Container>
      {!aowHeader ? <div className="side-title"><strong>{titleCase ? 'Source Control' : 'SOURCE CONTROL'}</strong><span className="source-actions"><button title="刷新" onClick={() => { setRefreshKey((key) => key + 1); refresh(); }}><RefreshCw size={14} /></button><button title="视图选项" data-source-menu="all" aria-haspopup="menu" aria-expanded={layoutMenu === 'all'} onClick={() => setLayoutMenu((current) => current === 'all' ? undefined : 'all')}><MoreHorizontal size={14} /></button></span>{renderLayoutMenu('all')}</div> : null}
      {!fixedRepository ? <select value={repository} onChange={(event) => setRepository(event.target.value)} aria-label="选择 Git 仓库">
        {repositories.length ? repositories.map((repo) => <option key={repo.path} value={repo.path}>{repo.name} · {repo.branch}</option>) : <option value="">未发现仓库</option>}
      </select> : null}
      <SourceSection hideLegacyHeader aow={aowHeader} title={titleCase ? 'Branches' : 'BRANCHES'} icon={<GitBranch />} collapsed={branchesCollapsed}
        controlsId={branchesSectionId} onToggle={() => setBranchesCollapsed(!branchesCollapsed)}>
      {repository ? <div id={aowHeader ? undefined : branchesSectionId} className="branch-label" hidden={aowHeader && branchesCollapsed}>
        <GitBranch size={13} /><span className="branch-name">{branch}</span>
        {upstream ? <span className="branch-upstream" title={`Tracking ${upstream}${ahead ? ` · ahead ${ahead}` : ''}${behind ? ` · behind ${behind}` : ''}`}><Cloud />{upstream}{ahead ? ` ↑${ahead}` : ''}{behind ? ` ↓${behind}` : ''}</span> : <span className="branch-upstream missing">未配置 upstream</span>}
      </div> : null}
      </SourceSection>
      {error ? <div className="side-error">{error}</div> : null}
      {gitOperation?.repository === repository ? <div className={gitOperation.state === 'error' ? 'side-error' : 'source-git-status'} role={gitOperation.state === 'error' ? 'alert' : 'status'}>
        git {gitOperation.command}{gitOperation.state === 'running' ? ' 执行中…' : gitOperation.state === 'success' ? ' 已完成' : ` 失败：${gitOperation.message}`}
      </div> : null}
      <SourceSection
        aow={aowHeader} title={titleCase ? 'Changes' : 'CHANGES'} icon={<FileDiff />} collapsed={changesCollapsed}
        controlsId={changesSectionId} count={aowHeader ? undefined : workingChanges.length} onToggle={toggleChangesSection}
        actions={aowHeader ? <>
          <AowIconButton title="刷新 Changes" aria-label="刷新 Changes" onClick={() => refresh('changes')}><RefreshCw /></AowIconButton>
          <AowIconButton title="Changes 视图选项" aria-label="Changes 视图选项" data-source-menu="changes" aria-haspopup="menu" aria-expanded={layoutMenu === 'changes'} onClick={() => setLayoutMenu((current) => current === 'changes' ? undefined : 'changes')}><MoreHorizontal /></AowIconButton>
        </> : undefined}
        menu={aowHeader ? renderLayoutMenu('changes') : undefined}
      >
      <div id={aowHeader ? undefined : changesSectionId} className="changes-list" hidden={changesCollapsed}><SourceControlChanges items={workingChanges} layout={aowHeader ? changesLayout : layout} active={visible && !changesCollapsed} selectedId={activeDocumentId} onOpen={openWorkingChange} />{!workingChanges.length ? <div className="side-empty">没有未提交更改</div> : null}</div>
      </SourceSection>
      <SourceSection
        aow={aowHeader} title={titleCase ? 'Commits' : 'COMMITS'} icon={<History />} collapsed={commitsCollapsed}
        controlsId={commitsSectionId} onToggle={toggleCommitsSection}
        details={aowHeader ? undefined : <span className="commit-legend"><i className="outgoing" />本地<i className="pushed" />已推送</span>}
        actions={aowHeader ? <>
          <AowIconButton title="刷新 Commits" aria-label="刷新 Commits" onClick={() => refresh('commits')}><RefreshCw /></AowIconButton>
          <AowIconButton title="Commits 视图选项" aria-label="Commits 视图选项" data-source-menu="commits" aria-haspopup="menu" aria-expanded={layoutMenu === 'commits'} onClick={() => setLayoutMenu((current) => current === 'commits' ? undefined : 'commits')}><MoreHorizontal /></AowIconButton>
        </> : undefined}
        menu={aowHeader ? renderLayoutMenu('commits') : undefined}
      >
      <div id={aowHeader ? undefined : commitsSectionId} className="commit-list" hidden={commitsCollapsed}>
        {commits.map((commit, index) => {
          const isExpanded = commit.id in expanded; const files = expanded[commit.id];
          const state = commit.is_pushed ? 'pushed' : 'outgoing';
          const graphRow = commitGraph.get(commit.id)!;
          const stateTitle = commit.is_pushed ? `已推送${upstream ? `到 ${upstream}` : ''}` : upstream ? `尚未推送到 ${upstream}` : '仅存在于本地（未配置 upstream）';
          const rowStyle = { '--commit-content-offset': `${graphWidth(graphRow)}px` } as CSSProperties;
          const selected = commitPopover?.commit.id === commit.id;
          const changesId = `${sectionIdPrefix}-commit-${commit.id}`;
          return <div className={`commit-node ${state}${isExpanded ? ' expanded' : ''}${selected ? ' selected' : ''}`} style={rowStyle} key={commit.id} onPointerLeave={schedulePopoverClose}>
            <CommitGraph commit={commit} row={graphRow} expanded={isExpanded} />
            <button
              className="commit-row" type="button" aria-expanded={isExpanded} aria-controls={changesId}
              aria-label={`${isExpanded ? '收起' : '展开'} ${commit.subject} 的文件，${stateTitle}`}
              onPointerEnter={(event) => scheduleCommitPreview(commit, event.currentTarget)}
              onPointerLeave={clearHoverTimer}
              onFocus={(event) => {
                if (suppressFocusPreviewRef.current) { suppressFocusPreviewRef.current = false; return; }
                showCommitPopover(commit, event.currentTarget, false);
              }}
              onBlur={(event) => {
                if (event.relatedTarget instanceof Element && event.relatedTarget.closest('.commit-detail-popover')) return;
                schedulePopoverClose();
              }}
              onClick={() => { closeCommitPopover(); void toggleCommit(commit); }}
            >
              <span className="commit-graph-spacer" aria-hidden="true" />
              <span className="commit-disclosure" aria-hidden="true">{isExpanded ? <ChevronDown /> : <ChevronRight />}</span>
              <span className="commit-main">
                <code>{commit.short_id}</code><span className="commit-subject">{commit.subject}</span>
                <span className="commit-refs">
                  {index === 0 ? <span className="commit-ref local" title={`HEAD · ${branch}`}><GitBranch />{branch}</span> : null}
                  {upstream && commit.id === upstreamCommit ? <span className="commit-ref remote" title={upstream}><Cloud />{upstream}</span> : null}
                </span>
              </span>
            </button>
            {isExpanded ? <div id={changesId} className="commit-changes">{files === null ? <div className="side-empty" role="status">加载中…</div> : files.length ? <CommitChanges repository={repository} commit={commit} files={files} layout={aowHeader ? commitsLayout : layout} active={visible && !commitsCollapsed} onOpen={onOpenCommitDiff} /> : <div className="side-empty">此提交没有文件变更</div>}</div> : null}
          </div>;
        })}
      </div>
      </SourceSection>
      </Container>
      {visible && commitPopover ? (() => {
        const cached = detailCacheRef.current.get(detailKey(commitPopover.commit.id));
        void detailVersion;
        return <CommitDetailPopover
          commit={commitPopover.commit} detail={cached?.detail} loading={cached?.loading === true} error={cached?.error}
          anchor={commitPopover.anchor} pinned={commitPopover.pinned} upstream={upstream}
          onEnter={clearCloseTimer} onLeave={schedulePopoverClose} onClose={closeCommitPopover}
        />;
      })() : null}
    </section>
  );
});

import { memo, useCallback, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type KeyboardEvent } from 'react';
import { ChevronRight } from 'lucide-react';
import { DirectoryTypeIcon, FileTypeIcon } from '../files/FileTypeIcon';

export interface ChangeItem { id: string; path: string; status: string; title: string }
interface Directory { name: string; path: string; directories: Directory[]; files: ChangeItem[] }
type Row = { type: 'directory'; directory: Directory; depth: number } | { type: 'file'; item: ChangeItem; depth: number };
interface Props {
  items: ChangeItem[];
  layout: 'list' | 'tree';
  active: boolean;
  selectedId?: string;
  onOpen: (item: ChangeItem) => void;
}

const rowHeight = 24;
const overscan = 8;
const layoutEvent = 'source-control-list-layout';

function buildTree(items: ChangeItem[]): Directory {
  const root: Directory = { name: '', path: '', directories: [], files: [] };
  const directories = new Map<string, Directory>([['', root]]);
  for (const item of items) {
    const segments = item.path.split('/');
    segments.pop();
    let parent = root;
    for (const name of segments) {
      const path = parent.path ? `${parent.path}/${name}` : name;
      let directory = directories.get(path);
      if (!directory) {
        directory = { name, path, directories: [], files: [] };
        directories.set(path, directory);
        parent.directories.push(directory);
      }
      parent = directory;
    }
    parent.files.push(item);
  }
  for (const directory of directories.values()) {
    directory.directories.sort((a, b) => a.name.localeCompare(b.name));
    directory.files.sort((a, b) => a.path.localeCompare(b.path));
  }
  return root;
}

const FileRow = memo(function FileRow({ item, compact, depth, selected, onOpen }: {
  item: ChangeItem; compact: boolean; depth: number; selected: boolean; onOpen: Props['onOpen'];
}) {
  const slash = item.path.lastIndexOf('/');
  return <button data-workspace-open className={`tree-row change-row${selected ? ' selected' : ''}`} title={item.title}
    style={{ '--tree-depth': depth } as CSSProperties}
    aria-current={selected || undefined} onClick={() => onOpen(item)}>
    <span className="chevron" aria-hidden="true" />
    <FileTypeIcon path={item.path} className="change-file-icon" />
    <span className={`change-name${item.status.startsWith('D') ? ' deleted' : ''}`}>{compact ? item.path.slice(slash + 1) : item.path}</span>
    {!compact && slash >= 0 ? <span className="change-directory">{item.path.slice(0, slash)}</span> : null}
    <b data-status={item.status[0]}>{item.status}</b>
  </button>;
});

// Panel lists share the sidebar viewport; standalone lists use their local
// Changes/Commits viewport. Expanded commit files never add a nested scrollbar.
export const SourceControlChanges = memo(function SourceControlChanges({ items, layout, active, selectedId, onOpen }: Props) {
  const host = useRef<HTMLDivElement>(null);
  const viewport = useRef<HTMLElement | null>(null);
  const pendingFocus = useRef<number | undefined>(undefined);
  const [collapsed, setCollapsed] = useState<Set<string>>(() => new Set());
  const [range, setRange] = useState({ start: 0, end: 0 });
  const tree = useMemo(() => layout === 'tree' ? buildTree(items) : undefined, [items, layout]);
  const rows = useMemo(() => {
    if (!tree) return items.map<Row>(item => ({ type: 'file', item, depth: 0 }));
    const result: Row[] = [];
    const visit = (node: Directory, depth: number) => {
      for (const directory of node.directories) {
        result.push({ type: 'directory', directory, depth });
        if (!collapsed.has(directory.path)) visit(directory, depth + 1);
      }
      for (const item of node.files) result.push({ type: 'file', item, depth });
    };
    visit(tree, 0);
    return result;
  }, [items, tree, collapsed]);
  const toggleDirectory = useCallback((path: string) => setCollapsed(previous => {
    const next = new Set(previous);
    if (next.has(path)) next.delete(path); else next.add(path);
    return next;
  }), []);

  useLayoutEffect(() => {
    const element = host.current;
    const scrollParent = element?.closest<HTMLElement>('.aow-panel-viewport') ?? element?.closest<HTMLElement>('.changes-list, .commit-list');
    if (!element || !scrollParent || !active) return;
    viewport.current = scrollParent;
    const measure = () => {
      const box = scrollParent.getBoundingClientRect();
      const list = element.getBoundingClientRect();
      const shown = scrollParent.clientHeight > 0 && list.bottom > box.top && list.top < box.bottom;
      const start = shown ? Math.max(0, Math.floor((box.top - list.top) / rowHeight) - overscan) : 0;
      const end = shown ? Math.min(rows.length, Math.ceil((box.bottom - list.top) / rowHeight) + overscan) : 0;
      setRange(previous => previous.start === start && previous.end === end ? previous : { start, end });
    };
    const announceLayout = () => scrollParent.dispatchEvent(new Event(layoutEvent));
    const observer = new ResizeObserver(announceLayout);
    observer.observe(scrollParent);
    observer.observe(element);
    scrollParent.addEventListener('scroll', measure, { passive: true });
    scrollParent.addEventListener(layoutEvent, measure);
    scrollParent.addEventListener('aow-panel-layout', measure);
    announceLayout();
    return () => {
      observer.disconnect();
      scrollParent.removeEventListener('scroll', measure);
      scrollParent.removeEventListener(layoutEvent, measure);
      scrollParent.removeEventListener('aow-panel-layout', measure);
      viewport.current = null;
      // Removing an earlier commit's list moves its siblings without resizing
      // their viewports. Measure them after React finishes removing the DOM.
      queueMicrotask(announceLayout);
    };
  }, [active, rows]);

  useLayoutEffect(() => {
    if (pendingFocus.current === undefined) return;
    const button = host.current?.querySelector<HTMLButtonElement>(`[data-change-index="${pendingFocus.current}"] button`);
    if (button) {
      button.focus({ preventScroll: true });
      pendingFocus.current = undefined;
    }
  });

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key) || event.altKey || event.ctrlKey || event.metaKey) return;
    const element = (event.target as HTMLElement).closest<HTMLElement>('[data-change-index]');
    const scrollParent = viewport.current;
    if (!element || !scrollParent || !host.current || !rows.length) return;
    event.preventDefault();
    const index = Number(element.dataset.changeIndex);
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? rows.length - 1
      : Math.max(0, Math.min(rows.length - 1, index + (event.key === 'ArrowDown' ? 1 : -1)));
    const box = scrollParent.getBoundingClientRect();
    const style = getComputedStyle(scrollParent);
    const start = box.top + parseFloat(style.getPropertyValue('--panel-scroll-top') || '0');
    const end = box.bottom - parseFloat(style.getPropertyValue('--panel-scroll-bottom') || '0');
    const top = host.current.getBoundingClientRect().top + next * rowHeight;
    if (top < start) scrollParent.scrollTop += top - start;
    else if (top + rowHeight > end) scrollParent.scrollTop += top + rowHeight - end;
    pendingFocus.current = next;
    scrollParent.dispatchEvent(new Event(layoutEvent));
    const button = host.current.querySelector<HTMLButtonElement>(`[data-change-index="${next}"] button`);
    if (button) {
      button.focus({ preventScroll: true });
      pendingFocus.current = undefined;
    }
  };

  return <div ref={host} className={`source-change-list${layout === 'tree' ? ' source-change-tree' : ''}`}
    style={{ height: rows.length * rowHeight }} onKeyDown={onKeyDown}>
    {active ? rows.slice(range.start, range.end).map((row, offset) => {
      const index = range.start + offset;
      return <div key={row.type === 'file' ? row.item.id : `directory:${row.directory.path}`}
        className="source-change-slot" data-change-index={index}
        style={{ top: index * rowHeight }}>
        {row.type === 'file'
          ? <FileRow item={row.item} compact={layout === 'tree'} depth={row.depth} selected={row.item.id === selectedId} onOpen={onOpen} />
          : <button className="tree-row change-folder-row" title={row.directory.path}
            style={{ '--tree-depth': row.depth } as CSSProperties}
            aria-expanded={!collapsed.has(row.directory.path)} onClick={() => toggleDirectory(row.directory.path)}>
            <span className={`chevron${collapsed.has(row.directory.path) ? '' : ' expanded'}`} aria-hidden="true"><ChevronRight /></span>
            <DirectoryTypeIcon expanded={!collapsed.has(row.directory.path)} />
            <span className="change-name">{row.directory.name}</span>
          </button>}
      </div>;
    }) : null}
  </div>;
});

import type { RepositorySummary, GitIgnoredPaths, GitStatus, GitLog, GitCommitFiles, GitCommitDetail, GitDiff } from './types';
import { request } from '../../lib/http';

export const gitApi = {
  repositories: (root: string, signal?: AbortSignal) => request<RepositorySummary[]>(`/api/git/repositories?root=${encodeURIComponent(root)}&depth=5`, { signal }),
  gitIgnored: (root: string, paths: string[]) => request<GitIgnoredPaths>('/api/git/ignored', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ root, paths }),
  }, 0),
  gitStatus: (repo: string, signal?: AbortSignal) => request<GitStatus>(`/api/git/status?repo=${encodeURIComponent(repo)}`, { signal, cache: 'no-store' }, signal ? 0 : 1),
  gitSync: (repo: string, command: 'pull' | 'push') => request<void>(`/api/git/${command}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ repo }),
  }, 0, 130_000),
  gitLog: (repo: string, signal?: AbortSignal) => request<GitLog>(`/api/git/log?repo=${encodeURIComponent(repo)}&limit=100`, { signal, cache: 'no-store' }, signal ? 0 : 1),
  gitDiff: (repo: string, path?: string, staged = false, signal?: AbortSignal) => {
    const query = new URLSearchParams({ repo, staged: String(staged) });
    if (path) query.set('path', path);
    return request<GitDiff>(`/api/git/diff?${query}`, { signal, cache: 'no-store' });
  },
  gitCommitFiles: (repo: string, commit: string) => request<GitCommitFiles>(`/api/git/commit/files?repo=${encodeURIComponent(repo)}&commit=${encodeURIComponent(commit)}`),
  gitCommitDetail: (repo: string, commit: string) => request<GitCommitDetail>(`/api/git/commit/detail?repo=${encodeURIComponent(repo)}&commit=${encodeURIComponent(commit)}`),
  gitCommitDiff: (repo: string, commit: string, path: string, originalPath?: string, signal?: AbortSignal) => {
    const query = new URLSearchParams({ repo, commit, path });
    if (originalPath) query.set('original_path', originalPath);
    return request<GitDiff>(`/api/git/commit/diff?${query}`, { signal, cache: 'no-store' });
  },
};

import type { GitCommit } from './types';

interface GraphLane { color: string; expected: string }
interface GraphLine { lane: number; color: string }
interface GraphEdge { from: number; to: number; color: string; startsAtNode: boolean }
export interface CommitGraphRow {
  lane: number;
  color: string;
  incoming: GraphLine[];
  edges: GraphEdge[];
  continuing: GraphLine[];
  columns: number;
}

const graphLaneColors = ['#4daafc', '#e5c07b', '#c586c0', '#4ec9b0', '#ce9178', '#b4a0ff', '#89d185', '#f48771'];

// The log starts at the selected repository's HEAD and is topologically sorted.
// Keep each first parent in its child's lane so HEAD's mainline stays at column 0.
export function buildCommitGraph(commits: readonly Pick<GitCommit, 'id' | 'parents'>[]) {
  const active: (GraphLane | undefined)[] = [];
  const rows = new Map<string, CommitGraphRow>();
  let nextColor = 0;
  const allocateLane = (expected: string, usedColors: Set<string>): GraphLane => {
    const availableOffset = graphLaneColors.findIndex((_, offset) => !usedColors.has(graphLaneColors[(nextColor + offset) % graphLaneColors.length]));
    if (availableOffset >= 0) nextColor += availableOffset;
    const color = graphLaneColors[nextColor++ % graphLaneColors.length];
    usedColors.add(color);
    return { color, expected };
  };
  const freeLane = () => {
    const empty = active.findIndex(lane => !lane);
    return empty < 0 ? active.length : empty;
  };

  for (const commit of commits) {
    const inputLanes = [...active];
    const usedColors = new Set(inputLanes.flatMap(lane => lane ? [lane.color] : []));
    const incoming = inputLanes.flatMap((lane, index) => lane?.expected === commit.id ? [{ lane: index, color: lane.color }] : []);
    const nodeLane = incoming[0]?.lane ?? freeLane();
    const lane = active[nodeLane] ?? allocateLane(commit.id, usedColors);
    for (const line of incoming) active[line.lane] = undefined;

    const edges: GraphEdge[] = inputLanes.flatMap((candidate, index) => candidate && candidate.expected !== commit.id
      ? [{ from: index, to: index, color: candidate.color, startsAtNode: false }] : []);
    commit.parents.forEach((parent, parentIndex) => {
      let target: number;
      if (parentIndex === 0) {
        // Do not merge lanes early when both already lead to this parent:
        // they meet at the parent's node, preserving the mainline's color.
        target = nodeLane;
        active[target] = { ...lane, expected: parent };
      } else {
        target = active.findIndex(candidate => candidate?.expected === parent);
        if (target < 0) {
          target = freeLane();
          active[target] = allocateLane(parent, usedColors);
        }
      }
      edges.push({ from: nodeLane, to: target, color: active[target]!.color, startsAtNode: true });
    });

    while (active.length && !active[active.length - 1]) active.pop();
    rows.set(commit.id, {
      lane: nodeLane, color: lane.color, incoming, edges,
      continuing: active.flatMap((candidate, index) => candidate ? [{ lane: index, color: candidate.color }] : []),
      columns: Math.max(nodeLane + 1, inputLanes.length, active.length),
    });
  }

  return rows;
}

